begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":1478730,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"1,67","question":"Lò phản ứng hạt nhân ở Đà Lạt có công suất 500 kW và sử dụng nhiên liệu là  ${}_{92}^{235}U$ . Giả sử rằng mỗi hạt nhân  ${}_{92}^{235}U$  khi phân hạch tỏa ra năng lượng trung bình là 175 MeV và uranium chỉ bị tiêu hao do quá trình phân hạch. Cho 1 eV = 1,6.1019 J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259894033-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số hạt nhân  ${}_{92}^{235}U$  đã phân hạch để cung cấp năng lượng cho lò phản ứng hoạt động liên tục trong 26 giờ là x.10<sup>21</sup> hạt. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{92}^{235}U$  đã phân hạch để cung cấp năng lượng cho lò phản ứng hoạt động liên tục trong 26 giờ là:<br>$N=\\frac{P.\\tau }{\\Delta E}=\\frac{500.{10}^3.26.3600}{175.{10}^6.1,6.{10}^{-19}}\\approx 1,67.{10}^{21}$  hạt.","difficultySource":"ai"},"ex":[{"exam":156,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"1,67","question":"Lò phản ứng hạt nhân ở Đà Lạt có công suất 500 kW và sử dụng nhiên liệu là  ${}_{92}^{235}U$ . Giả sử rằng mỗi hạt nhân  ${}_{92}^{235}U$  khi phân hạch tỏa ra năng lượng trung bình là 175 MeV và uranium chỉ bị tiêu hao do quá trình phân hạch. Cho 1 eV = 1,6.1019 J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259894033-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Số hạt nhân  ${}_{92}^{235}U$  đã phân hạch để cung cấp năng lượng cho lò phản ứng hoạt động liên tục trong 26 giờ là x.10<sup>21</sup> hạt. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{92}^{235}U$  đã phân hạch để cung cấp năng lượng cho lò phản ứng hoạt động liên tục trong 26 giờ là:<br>$N=\\frac{P.\\tau }{\\Delta E}=\\frac{500.{10}^3.26.3600}{175.{10}^6.1,6.{10}^{-19}}\\approx 1,67.{10}^{21}$  hạt.","difficultySource":"ai"}}]},{"id":1478758,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"8,48","question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV. Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong một thí nghiệm vũ khí hạt nhân là 200 g. Lấy 1 eV = 1,6.1019 J và khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị u. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259911436-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tổng năng lượng tỏa ra của vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân trên là x.10<sup>13</sup> J? Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số nguyên tử  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$N=\\frac{m}{M}.N_A=\\frac{200}{4}.6,02.{10}^{23}=3,01.{10}^{25}$  nguyên tử.<br>Tổng năng lượng tỏa ra của các phản ứng nhiệt hạch là:<br>$3,01.{10}^{25}.17,6.{10}^6.1,6.{10}^{-19}=8,47616.{10}^{13}$  (J).<br>Tổng năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$2,8.{10}^{10}+8,47616.{10}^{13}\\approx 8,48.{10}^{13}$  (J).<br>Vậy  $x=8,48$ .","difficultySource":"ai"},"ex":[{"exam":157,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"8,48","question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV. Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong một thí nghiệm vũ khí hạt nhân là 200 g. Lấy 1 eV = 1,6.1019 J và khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị u. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259911436-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tổng năng lượng tỏa ra của vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân trên là x.10<sup>13</sup> J? Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Số nguyên tử  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$N=\\frac{m}{M}.N_A=\\frac{200}{4}.6,02.{10}^{23}=3,01.{10}^{25}$  nguyên tử.<br>Tổng năng lượng tỏa ra của các phản ứng nhiệt hạch là:<br>$3,01.{10}^{25}.17,6.{10}^6.1,6.{10}^{-19}=8,47616.{10}^{13}$  (J).<br>Tổng năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân là:<br>$2,8.{10}^{10}+8,47616.{10}^{13}\\approx 8,48.{10}^{13}$  (J).<br>Vậy  $x=8,48$ .","difficultySource":"ai"}}]},{"id":1478759,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2019","question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV. Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong một thí nghiệm vũ khí hạt nhân là 200 g. Lấy 1 eV = 1,6.1019 J và khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị u. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259911436-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Biết rằng năng lượng tỏa ra khi một tấn thuốc nổ TNT cháy hoàn toàn là 4,2.10<sup>9</sup> J. Để có thể cung cấp một năng lượng bằng với năng lượng tỏa ra trong vụ nổ bom hydrogen của thí nghiệm vũ khí hạt nhân trên thì cần đốt cháy hoàn toàn x.10 tấn thuốc nổ TNT. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Lượng thuốc nổ TNT cháy hoàn toàn để có năng lượng tỏa ra bằng với năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân đã cho là:<br>$\\frac{2,8.{10}^{10}+8,47616.{10}^{13}}{4,2.{10}^9}=20 188\\approx 2019.10$  tấn.<br>Vậy  $x=2019$ .","difficultySource":"ai"},"ex":[{"exam":157,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2019","question":"Bom hydrogen (bom H) là một loại vũ khí hạt nhân có sức tàn phá lớn hơn bom nguyên tử (bom A) rất nhiều lần, dù hiện nay cả bom hydrogen và bom nguyên tử đều không được sử dụng trong các cuộc chiến tranh. Sở dĩ bom hydrogen có sức tàn phá lớn như vậy là do nó là sự kết hợp của phản ứng phân hạch của  ${}_{92}^{235}U$  (giai đoạn 1) để tạo ra môi trường có nhiệt độ rất cao, cung cấp động năng cho các hạt tham gia phản ứng nhiệt hạch (giai đoạn 2) theo phương trình phản ứng  ${}_1^2H$  +  ${}_1^3H$    ${}_2^4{He}$  +  ${}_0^1n$  + 17,6 MeV. Giả sử năng lượng tỏa ra từ quá trình phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là 2,8.10<sup>10</sup> J và khối lượng  ${}_2^4{He}$  được tạo thành từ một vụ nổ bom hydrogen trong một thí nghiệm vũ khí hạt nhân là 200 g. Lấy 1 eV = 1,6.1019 J và khối lượng nguyên tử bằng số khối của nguyên tử đó tính theo đơn vị u. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259910790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259911436-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Biết rằng năng lượng tỏa ra khi một tấn thuốc nổ TNT cháy hoàn toàn là 4,2.10<sup>9</sup> J. Để có thể cung cấp một năng lượng bằng với năng lượng tỏa ra trong vụ nổ bom hydrogen của thí nghiệm vũ khí hạt nhân trên thì cần đốt cháy hoàn toàn x.10 tấn thuốc nổ TNT. Giá trị của x là bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Lượng thuốc nổ TNT cháy hoàn toàn để có năng lượng tỏa ra bằng với năng lượng tỏa ra từ một vụ nổ bom hydrogen trong thí nghiệm vũ khí hạt nhân đã cho là:<br>$\\frac{2,8.{10}^{10}+8,47616.{10}^{13}}{4,2.{10}^9}=20 188\\approx 2019.10$  tấn.<br>Vậy  $x=2019$ .","difficultySource":"ai"}}]},{"id":1478814,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"1760","question":"Máy phát điện đồng vị phóng xạ (RTG) là nguồn cung cấp năng lượng cho các thiết bị thám hiểm không gian, giúp duy trì hoạt động trên những quỹ đạo kéo dài hàng thập kỉ. Một thiết bị RTG sử dụng khối nhiên liệu plutonium  ${}_{94}^{238}{Pu}$ . Chất phóng xạ  ${}_{94}^{238}{Pu}$  phát ra tia  với chu kì bán rã là 88 năm. Biết mỗi phân rã tỏa ra năng lượng 5,5 MeV và toàn bộ năng lượng này được khối thiết bị hấp thụ hoàn toàn để chuyển thành nhiệt năng. Tại thời điểm phóng, khối nhiên liệu có độ phóng xạ là 2,0.10<sup>15</sup> Bq. Lấy 1 MeV = 1,6.10<sup>−13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259960409-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tại thời điểm thiết bị thám hiểm được phóng đi, công suất tỏa nhiệt của khối nhiên liệu này là bao nhiêu W?","difficulty":"trung-binh","explanation":"Công suất tỏa nhiệt của khối nhiên liệu lúc vừa được phóng đi:<br>$P=\\frac{Q}{t}=\\frac{N.\\Delta E}{t}=H_0.\\Delta E={2,0.10}^{15}∙\\left(5,5∙{1,6.10}^{-13}\\right)=1760 W.$","difficultySource":"ai"},"ex":[{"exam":162,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"1760","question":"Máy phát điện đồng vị phóng xạ (RTG) là nguồn cung cấp năng lượng cho các thiết bị thám hiểm không gian, giúp duy trì hoạt động trên những quỹ đạo kéo dài hàng thập kỉ. Một thiết bị RTG sử dụng khối nhiên liệu plutonium  ${}_{94}^{238}{Pu}$ . Chất phóng xạ  ${}_{94}^{238}{Pu}$  phát ra tia  với chu kì bán rã là 88 năm. Biết mỗi phân rã tỏa ra năng lượng 5,5 MeV và toàn bộ năng lượng này được khối thiết bị hấp thụ hoàn toàn để chuyển thành nhiệt năng. Tại thời điểm phóng, khối nhiên liệu có độ phóng xạ là 2,0.10<sup>15</sup> Bq. Lấy 1 MeV = 1,6.10<sup>−13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259960409-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tại thời điểm thiết bị thám hiểm được phóng đi, công suất tỏa nhiệt của khối nhiên liệu này là bao nhiêu W?","difficulty":"trung-binh","explanation":"Công suất tỏa nhiệt của khối nhiên liệu lúc vừa được phóng đi:<br>$P=\\frac{Q}{t}=\\frac{N.\\Delta E}{t}=H_0.\\Delta E={2,0.10}^{15}∙\\left(5,5∙{1,6.10}^{-13}\\right)=1760 W.$","difficultySource":"ai"}}]},{"id":1478815,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"56","question":"Máy phát điện đồng vị phóng xạ (RTG) là nguồn cung cấp năng lượng cho các thiết bị thám hiểm không gian, giúp duy trì hoạt động trên những quỹ đạo kéo dài hàng thập kỉ. Một thiết bị RTG sử dụng khối nhiên liệu plutonium  ${}_{94}^{238}{Pu}$ . Chất phóng xạ  ${}_{94}^{238}{Pu}$  phát ra tia  với chu kì bán rã là 88 năm. Biết mỗi phân rã tỏa ra năng lượng 5,5 MeV và toàn bộ năng lượng này được khối thiết bị hấp thụ hoàn toàn để chuyển thành nhiệt năng. Tại thời điểm phóng, khối nhiên liệu có độ phóng xạ là 2,0.10<sup>15</sup> Bq. Lấy 1 MeV = 1,6.10<sup>−13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259960409-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Sau 44 năm hoạt động trong không gian kể từ lúc phóng, bên cạnh sự suy giảm công suất tỏa nhiệt do phân rã phóng xạ, các cặp nhiệt điện cũng bị thoái hóa khiến hiệu suất chuyển hóa nhiệt năng thành điện năng của hệ thống chỉ còn 4,5%. Lúc này, khối nhiên liệu trên cung cấp một công suất điện xấp xỉ bao nhiêu W? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Công suất tỏa nhiệt của khối nhiên liệu sau 44 năm:<br>$P_{nhiệt}=H.\\Delta E=H_0.2^{-\\frac{t}{T}}.\\Delta E=P.2^{-\\frac{t}{T}}=1760∙2^{-\\frac{44}{88}}$<br>Công suất điện được cung cấp:<br>$P_{điện}=4,5%.P_{nhiệt}=4,5%∙1760∙2^{-\\frac{44}{88}}\\approx 56 W.$","difficultySource":"ai"},"ex":[{"exam":162,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"56","question":"Máy phát điện đồng vị phóng xạ (RTG) là nguồn cung cấp năng lượng cho các thiết bị thám hiểm không gian, giúp duy trì hoạt động trên những quỹ đạo kéo dài hàng thập kỉ. Một thiết bị RTG sử dụng khối nhiên liệu plutonium  ${}_{94}^{238}{Pu}$ . Chất phóng xạ  ${}_{94}^{238}{Pu}$  phát ra tia  với chu kì bán rã là 88 năm. Biết mỗi phân rã tỏa ra năng lượng 5,5 MeV và toàn bộ năng lượng này được khối thiết bị hấp thụ hoàn toàn để chuyển thành nhiệt năng. Tại thời điểm phóng, khối nhiên liệu có độ phóng xạ là 2,0.10<sup>15</sup> Bq. Lấy 1 MeV = 1,6.10<sup>−13</sup> J. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259960409-hinh-10.jpg\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Sau 44 năm hoạt động trong không gian kể từ lúc phóng, bên cạnh sự suy giảm công suất tỏa nhiệt do phân rã phóng xạ, các cặp nhiệt điện cũng bị thoái hóa khiến hiệu suất chuyển hóa nhiệt năng thành điện năng của hệ thống chỉ còn 4,5%. Lúc này, khối nhiên liệu trên cung cấp một công suất điện xấp xỉ bao nhiêu W? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Công suất tỏa nhiệt của khối nhiên liệu sau 44 năm:<br>$P_{nhiệt}=H.\\Delta E=H_0.2^{-\\frac{t}{T}}.\\Delta E=P.2^{-\\frac{t}{T}}=1760∙2^{-\\frac{44}{88}}$<br>Công suất điện được cung cấp:<br>$P_{điện}=4,5%.P_{nhiệt}=4,5%∙1760∙2^{-\\frac{44}{88}}\\approx 56 W.$","difficultySource":"ai"}}]},{"id":1478824,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đọc đồ thị các đẳng quá trình","answer":1,"options":["16,62.10<sup>5</sup> Pa.","8,31.10<sup>5</sup> Pa.","33,24.10<sup>5</sup> Pa.","16,62 kPa."],"question":"Một mol khí lí tưởng xác định thực hiện quá trình biến đổi trạng thái từ (1) đến (2) được biểu diễn trong hệ tọa độ (V, T) như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259964476-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí lí tưởng ở trạng thái (2) có giá trị bằng","difficulty":"de","explanation":"Áp suất của khối khí ở trạng thái (2) là:<br>$p_2.V_2=nRT_2$    $p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.600}{6.{10}^{-3}}=8,31.{10}^5$  Pa.","difficultySource":"ai"},"ex":[{"exam":163,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đọc đồ thị các đẳng quá trình","answer":1,"options":["16,62.10<sup>5</sup> Pa.","8,31.10<sup>5</sup> Pa.","33,24.10<sup>5</sup> Pa.","16,62 kPa."],"question":"Một mol khí lí tưởng xác định thực hiện quá trình biến đổi trạng thái từ (1) đến (2) được biểu diễn trong hệ tọa độ (V, T) như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259964476-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí lí tưởng ở trạng thái (2) có giá trị bằng","difficulty":"de","explanation":"Áp suất của khối khí ở trạng thái (2) là:<br>$p_2.V_2=nRT_2$    $p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.600}{6.{10}^{-3}}=8,31.{10}^5$  Pa.","difficultySource":"ai"}}]},{"id":1478869,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"7,3","question":"Một cốc nước có chứa 250 g nước ở nhiệt độ 25°C. Người ta cho vào cốc 50 g nước đá ở 0°C. Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Bỏ qua sự trao đổi nhiệt với môi trường và với cốc đựng. Nhiệt độ cân bằng của nước bằng bao nhiêu độ celsius (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Đáp số 7,3<br>Nhiệt lượng lớn nhất nước có thể tỏa ra để giảm xuống 0°C:<br>$Q_{toa max}=m_1c\\Delta t$  = 0,25.4200.25 = 26250 J.<br>Nhiệt lượng cần thiết để lượng nước đá nóng chảy hoàn toàn:<br>$Q_{thu nuoc}=m_2\\lambda$  = 0,05.3, 4.10<sup>5</sup> =17000 J<br>Vì Qtoa max > Qthu nước nên nước đá nóng chảy hoàn toàn và nhiệt độ cân bằng $t>0^0C$  .<br>Áp dụng phương trình cân bằng nhiệt  $Q_{toa}=Q_{thu}$<br>$\\Leftrightarrow m_1c\\left(25−t\\right)=m_2\\lambda +m_2c\\left(t−0\\right)$<br>$\\Leftrightarrow 0,25.4200.\\left(25−t\\right)=0,05.3,4.10^5+0,05.4200.\\left(t−0\\right)$<br>⇔1260t = 9250 ⇒ t ≈ 7,3 C","difficultySource":"ai"},"ex":[{"exam":164,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":"7,3","question":"Một cốc nước có chứa 250 g nước ở nhiệt độ 25°C. Người ta cho vào cốc 50 g nước đá ở 0°C. Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Bỏ qua sự trao đổi nhiệt với môi trường và với cốc đựng. Nhiệt độ cân bằng của nước bằng bao nhiêu độ celsius (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Đáp số 7,3<br>Nhiệt lượng lớn nhất nước có thể tỏa ra để giảm xuống 0°C:<br>$Q_{toa max}=m_1c\\Delta t$  = 0,25.4200.25 = 26250 J.<br>Nhiệt lượng cần thiết để lượng nước đá nóng chảy hoàn toàn:<br>$Q_{thu nuoc}=m_2\\lambda$  = 0,05.3, 4.10<sup>5</sup> =17000 J<br>Vì Qtoa max > Qthu nước nên nước đá nóng chảy hoàn toàn và nhiệt độ cân bằng $t>0^0C$  .<br>Áp dụng phương trình cân bằng nhiệt  $Q_{toa}=Q_{thu}$<br>$\\Leftrightarrow m_1c\\left(25−t\\right)=m_2\\lambda +m_2c\\left(t−0\\right)$<br>$\\Leftrightarrow 0,25.4200.\\left(25−t\\right)=0,05.3,4.10^5+0,05.4200.\\left(t−0\\right)$<br>⇔1260t = 9250 ⇒ t ≈ 7,3 C","difficultySource":"ai"}}]},{"id":1478870,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"1,6","question":"Trong quá trình chuyển tuyến cho một bệnh nhân cấp cứu, các y bác sĩ sử dụng một bình khí oxygen có dung tích 10 lít, áp suất 1,5.10<sup>7</sup> Pa, nhiệt độ 27°C. Coi oxygen trong bình là khí lí tưởng.<br>Trước khi khởi hành, do xe cứu thương đỗ dưới trời nắng nên nhiệt độ của bình khí tăng lên 45°C. Bỏ qua sự giãn nở nhiệt của vỏ bình. Áp suất của khí trong bình lúc này bằng x.10<sup>7</sup> Pa. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"de","explanation":"Đáp số 1,6<br>Trạng thái 1:  $p_1=1,5.10^7Pa;T_1=27+273=300K$<br>Trạng thái 2:  $p_2=?;T_2=45+273=318K$<br>Vì bỏ qua sự giãn nở vỏ bình nên thể tích khí không đổi ta áp dụng định luật Charles co quá trình biến đổi đẳng tích:  <br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259973964-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":164,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"1,6","question":"Trong quá trình chuyển tuyến cho một bệnh nhân cấp cứu, các y bác sĩ sử dụng một bình khí oxygen có dung tích 10 lít, áp suất 1,5.10<sup>7</sup> Pa, nhiệt độ 27°C. Coi oxygen trong bình là khí lí tưởng.<br>Trước khi khởi hành, do xe cứu thương đỗ dưới trời nắng nên nhiệt độ của bình khí tăng lên 45°C. Bỏ qua sự giãn nở nhiệt của vỏ bình. Áp suất của khí trong bình lúc này bằng x.10<sup>7</sup> Pa. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"de","explanation":"Đáp số 1,6<br>Trạng thái 1:  $p_1=1,5.10^7Pa;T_1=27+273=300K$<br>Trạng thái 2:  $p_2=?;T_2=45+273=318K$<br>Vì bỏ qua sự giãn nở vỏ bình nên thể tích khí không đổi ta áp dụng định luật Charles co quá trình biến đổi đẳng tích:  <br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259973964-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1478871,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"4","question":"Trong quá trình chuyển tuyến cho một bệnh nhân cấp cứu, các y bác sĩ sử dụng một bình khí oxygen có dung tích 10 lít, áp suất 1,5.10<sup>7</sup> Pa, nhiệt độ 27°C. Coi oxygen trong bình là khí lí tưởng.<br>Khi xe chuẩn bị di chuyển, hệ thống điều hòa của xe hoạt động giúp nhiệt độ của bình khí nhanh chóng giảm xuống và ổn định trở lại ở mức 27°C. Bệnh nhân được chỉ định thở oxygen qua ống thông mũi với mức tiêu thụ trung bình trong mỗi phút là 7,5.10<sup>22</sup> phân tử oxygen. Sau bao nhiêu giờ thì lượng oxygen trong bình còn lại 50% (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 4<br>Trạng thái khí ban đầu ở 27°C: 7 p =1,5.10<sup>7</sup>Pa ; V = 10 lít = 0,01 m3; T = 300K.<br>Số mol khí ban đầu trong bình là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259974264-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tổng số phân tử oxygen ban đầu có trong bình là:<br>$N=n.N_A$  = 60,168.6,02.10<sup>23</sup> ≈ 3,622.10<sup>25</sup> phân tử<br>Để lượng khí trong bình còn lại 50% thì số phân tử bệnh nhân đã hít vào bằng đúng 50%tổng số hạt ban đầu:<br>$N_{tieu thu}$  = 0,5.3,622.10<sup>25</sup> =1,811.10<sup>25</sup> phân tử<br>Thời gian sử dụng khí:<br>$t=\\frac{1,811.10^{25}}{7,5.10^{22}}\\approx$  241,47≈ (phút) ≈ 4 giờ","difficultySource":"ai"},"ex":[{"exam":164,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"4","question":"Trong quá trình chuyển tuyến cho một bệnh nhân cấp cứu, các y bác sĩ sử dụng một bình khí oxygen có dung tích 10 lít, áp suất 1,5.10<sup>7</sup> Pa, nhiệt độ 27°C. Coi oxygen trong bình là khí lí tưởng.<br>Khi xe chuẩn bị di chuyển, hệ thống điều hòa của xe hoạt động giúp nhiệt độ của bình khí nhanh chóng giảm xuống và ổn định trở lại ở mức 27°C. Bệnh nhân được chỉ định thở oxygen qua ống thông mũi với mức tiêu thụ trung bình trong mỗi phút là 7,5.10<sup>22</sup> phân tử oxygen. Sau bao nhiêu giờ thì lượng oxygen trong bình còn lại 50% (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 4<br>Trạng thái khí ban đầu ở 27°C: 7 p =1,5.10<sup>7</sup>Pa ; V = 10 lít = 0,01 m3; T = 300K.<br>Số mol khí ban đầu trong bình là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259974264-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tổng số phân tử oxygen ban đầu có trong bình là:<br>$N=n.N_A$  = 60,168.6,02.10<sup>23</sup> ≈ 3,622.10<sup>25</sup> phân tử<br>Để lượng khí trong bình còn lại 50% thì số phân tử bệnh nhân đã hít vào bằng đúng 50%tổng số hạt ban đầu:<br>$N_{tieu thu}$  = 0,5.3,622.10<sup>25</sup> =1,811.10<sup>25</sup> phân tử<br>Thời gian sử dụng khí:<br>$t=\\frac{1,811.10^{25}}{7,5.10^{22}}\\approx$  241,47≈ (phút) ≈ 4 giờ","difficultySource":"ai"}}]},{"id":1478897,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"6","question":"Gas (LPG) là nhiên liệu phổ biến hiện nay, có thành phần chính là propane (C3H8) và butane (C4H10). Trong các bồn chứa công nghiệp, gas được hóa lỏng dưới áp suất cao. Để có thể sử dụng, một phần gas sẽ hóa hơi chiếm đầy phần không gian trống phía trên của bồn. Xét một bồn chứa có phần không gian chứa khí gas là V = 0,831 m3 đang ở nhiệt độ 27°C. Phân tích thành phần của lượng hỗn hợp khí gas này cho thấy có chứa 7,04 kg propane và 2,32 kg butane. Giả sử hỗn hợp khí trong bồn là khí lí tưởng. Khối lượng mol của propane, butane lần lượt là 44 g/mol và 58 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259989549-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Theo định lí Dalton, áp suất của hỗn hợp khí chính bằng tổng áp suất phần riêng của từng thành phần tạo nên hỗn hợp khí khí đó. Áp suất toàn phần của hỗn hợp khí gas trong bồn là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Đáp số 6<br>Áp suất toàn phần của hỗn hợp khí gas trong bồn:<br>$p=p_{C_4H_{10}}+p_{C_3H_8}=\\frac{n_{C_4H_{10}}.R.T}{V}+\\frac{n_{C_3H_8}.R.T}{V}$<br>$⟺p=\\frac{\\frac{{2,32.10}^3}{58}∙8,31∙\\left(27+273\\right)}{0,831}+\\frac{\\frac{{7,04.10}^3}{44}∙8,31∙\\left(27+273\\right)}{0,831}={6.10}^5 Pa⟹x=6.$","difficultySource":"ai"},"ex":[{"exam":166,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"6","question":"Gas (LPG) là nhiên liệu phổ biến hiện nay, có thành phần chính là propane (C3H8) và butane (C4H10). Trong các bồn chứa công nghiệp, gas được hóa lỏng dưới áp suất cao. Để có thể sử dụng, một phần gas sẽ hóa hơi chiếm đầy phần không gian trống phía trên của bồn. Xét một bồn chứa có phần không gian chứa khí gas là V = 0,831 m3 đang ở nhiệt độ 27°C. Phân tích thành phần của lượng hỗn hợp khí gas này cho thấy có chứa 7,04 kg propane và 2,32 kg butane. Giả sử hỗn hợp khí trong bồn là khí lí tưởng. Khối lượng mol của propane, butane lần lượt là 44 g/mol và 58 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259989549-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Theo định lí Dalton, áp suất của hỗn hợp khí chính bằng tổng áp suất phần riêng của từng thành phần tạo nên hỗn hợp khí khí đó. Áp suất toàn phần của hỗn hợp khí gas trong bồn là x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Đáp số 6<br>Áp suất toàn phần của hỗn hợp khí gas trong bồn:<br>$p=p_{C_4H_{10}}+p_{C_3H_8}=\\frac{n_{C_4H_{10}}.R.T}{V}+\\frac{n_{C_3H_8}.R.T}{V}$<br>$⟺p=\\frac{\\frac{{2,32.10}^3}{58}∙8,31∙\\left(27+273\\right)}{0,831}+\\frac{\\frac{{7,04.10}^3}{44}∙8,31∙\\left(27+273\\right)}{0,831}={6.10}^5 Pa⟹x=6.$","difficultySource":"ai"}}]},{"id":1478952,"nq":{"form":"ly_thuyet","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"3","question":"Một bánh xe đạp có bán kính r = 35 cm được làm bằng kim loại, có các nan hoa dẫn điện. Bánh xe quay đều quanh trục cố định của nó với tốc độ 5 vòng/giây trong một từ trường đều có cảm ứng từ B = 5.10<sup>−3</sup> T. Các đường sức từ song song với trục của bánh xe. Một vôn kế được mắc vào hai đầu tiếp điểm: một đầu tì vào trục quay, đầu kia tì vào vành bánh xe. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010705-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Để làm tăng suất điện động cảm ứng xuất hiện giữa trục và vành bánh xe, người ta đưa ra các biện pháp sau: (1) Tăng tốc độ quay của bánh xe. (2) Tăng độ lớn cảm ứng từ B (3) Thay bằng một bánh xe khác có bán kính lớn hơn. (4) Tăng số lượng nan hoa của bánh xe. (5) Thay đổi vật liệu làm nan hoa từ thép sang đồng. Có bao nhiêu biện pháp đúng (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 3<br>Xét trung điểm mỗi nan hoa có  $e=Brv=B.r.\\frac{\\omega r}{2}=\\frac{1}{2}B\\omega r^2$<br>(1) Tăng ω ⇒ đúng.<br>(2) Tăng B ⇒ đúng.<br>(3) Tăng r ⇒ đúng.<br>(4) Không ảnh hưởng, giống như các nguồn ghép song song với nhau mà thôi<br>(5) Không ảnh hưởng.","difficultySource":"ai"},"ex":[{"exam":170,"idx":24,"el":{"form":"ly_thuyet","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"3","question":"Một bánh xe đạp có bán kính r = 35 cm được làm bằng kim loại, có các nan hoa dẫn điện. Bánh xe quay đều quanh trục cố định của nó với tốc độ 5 vòng/giây trong một từ trường đều có cảm ứng từ B = 5.10<sup>−3</sup> T. Các đường sức từ song song với trục của bánh xe. Một vôn kế được mắc vào hai đầu tiếp điểm: một đầu tì vào trục quay, đầu kia tì vào vành bánh xe. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010705-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Để làm tăng suất điện động cảm ứng xuất hiện giữa trục và vành bánh xe, người ta đưa ra các biện pháp sau: (1) Tăng tốc độ quay của bánh xe. (2) Tăng độ lớn cảm ứng từ B (3) Thay bằng một bánh xe khác có bán kính lớn hơn. (4) Tăng số lượng nan hoa của bánh xe. (5) Thay đổi vật liệu làm nan hoa từ thép sang đồng. Có bao nhiêu biện pháp đúng (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Đáp số 3<br>Xét trung điểm mỗi nan hoa có  $e=Brv=B.r.\\frac{\\omega r}{2}=\\frac{1}{2}B\\omega r^2$<br>(1) Tăng ω ⇒ đúng.<br>(2) Tăng B ⇒ đúng.<br>(3) Tăng r ⇒ đúng.<br>(4) Không ảnh hưởng, giống như các nguồn ghép song song với nhau mà thôi<br>(5) Không ảnh hưởng.","difficultySource":"ai"}}]},{"id":1478953,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"9,6","question":"Một bánh xe đạp có bán kính r = 35 cm được làm bằng kim loại, có các nan hoa dẫn điện. Bánh xe quay đều quanh trục cố định của nó với tốc độ 5 vòng/giây trong một từ trường đều có cảm ứng từ B = 5.10<sup>−3</sup> T. Các đường sức từ song song với trục của bánh xe. Một vôn kế được mắc vào hai đầu tiếp điểm: một đầu tì vào trục quay, đầu kia tì vào vành bánh xe. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010705-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Giá trị suất điện động cảm ứng đo được giữa hai đầu tiếp điểm là bao nhiêu mV (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Mỗi nan hoa là một thanh dẫn dài $r$ quay quanh trục trong từ trường đều vuông góc với bánh xe, suất điện động cảm ứng giữa trục và vành: $e=\\dfrac12B\\omega r^2$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc: $\\omega=2\\pi n=2\\pi\\cdot5=10\\pi$ rad/s $\\approx31{,}42$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$e=\\dfrac12\\cdot5.10^{-3}\\cdot10\\pi\\cdot0{,}35^2\\approx9{,}62.10^{-3}$ V $\\approx9{,}6$ mV.</p>","difficultySource":"ai"},"ex":[{"exam":170,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"9,6","question":"Một bánh xe đạp có bán kính r = 35 cm được làm bằng kim loại, có các nan hoa dẫn điện. Bánh xe quay đều quanh trục cố định của nó với tốc độ 5 vòng/giây trong một từ trường đều có cảm ứng từ B = 5.10<sup>−3</sup> T. Các đường sức từ song song với trục của bánh xe. Một vôn kế được mắc vào hai đầu tiếp điểm: một đầu tì vào trục quay, đầu kia tì vào vành bánh xe. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260010705-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Giá trị suất điện động cảm ứng đo được giữa hai đầu tiếp điểm là bao nhiêu mV (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Đáp số 9,6<br>$\\omega =2\\pi f=2\\pi .5=10\\pi \\left(rad/s\\right)$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260011209-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1478982,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"22,9","question":"Trong môi trường kín như tàu ngầm, người ta bổ sung Oxygen (O2) và loại bỏ Carbon dioxide (CO2) để hàm lượng O2 và CO2 không đổi. Biết rằng trung bình mỗi ngày, mỗi thuyền viên tiêu thụ 565 lít O2 và thải ra 465 lít CO2 ở áp suất 1,01.10<sup>5</sup> Pa và nhiệt độ 27,0°C, khối lượng mol của CO2 là 44,0 (g/mol)<br>Trung bình trong mỗi ngày một thuyền viên trên tàu tiêu thụ bao nhiêu mol khí O2 (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$n=\\frac{pV}{RT}=\\frac{1,01.10^5.565.10^{−3}}{8,31.300}\\approx 22,9\\left(mol\\right)$","difficultySource":"ai"},"ex":[{"exam":177,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"22,9","question":"Trong môi trường kín như tàu ngầm, người ta bổ sung Oxygen (O2) và loại bỏ Carbon dioxide (CO2) để hàm lượng O2 và CO2 không đổi. Biết rằng trung bình mỗi ngày, mỗi thuyền viên tiêu thụ 565 lít O2 và thải ra 465 lít CO2 ở áp suất 1,01.10<sup>5</sup> Pa và nhiệt độ 27,0°C, khối lượng mol của CO2 là 44,0 (g/mol)<br>Trung bình trong mỗi ngày một thuyền viên trên tàu tiêu thụ bao nhiêu mol khí O2 (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$n=\\frac{pV}{RT}=\\frac{1,01.10^5.565.10^{−3}}{8,31.300}\\approx 22,9\\left(mol\\right)$","difficultySource":"ai"}}]},{"id":1478983,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"31,4","question":"Trong môi trường kín như tàu ngầm, người ta bổ sung Oxygen (O2) và loại bỏ Carbon dioxide (CO2) để hàm lượng O2 và CO2 không đổi. Biết rằng trung bình mỗi ngày, mỗi thuyền viên tiêu thụ 565 lít O2 và thải ra 465 lít CO2 ở áp suất 1,01.10<sup>5</sup> Pa và nhiệt độ 27,0°C, khối lượng mol của CO2 là 44,0 (g/mol)<br>Để loại bỏ CO2, người ta sử dụng hệ thống lọc chứa hóa chất chuyên dụng. Biết rằng mỗi kilôgam hóa chất có khả năng hấp thụ tối đa 15 mol CO2. Trong một ngày, khối lượng hóa chất tối thiểu cần để xử lý toàn bộ lượng CO2 do 25 thuyền viên thải ra là bao nhiêu kilôgam (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$n_{CO_2}=25.\\frac{1,01.10^5.465.10^{−3}}{8,31.300}=470,97\\left(mol\\right)$<br>Khối lượng chất cần dùng  $\\frac{n_{CO_2}}{15}\\approx 31,4\\left(kg\\right)$","difficultySource":"ai"},"ex":[{"exam":177,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"31,4","question":"Trong môi trường kín như tàu ngầm, người ta bổ sung Oxygen (O2) và loại bỏ Carbon dioxide (CO2) để hàm lượng O2 và CO2 không đổi. Biết rằng trung bình mỗi ngày, mỗi thuyền viên tiêu thụ 565 lít O2 và thải ra 465 lít CO2 ở áp suất 1,01.10<sup>5</sup> Pa và nhiệt độ 27,0°C, khối lượng mol của CO2 là 44,0 (g/mol)<br>Để loại bỏ CO2, người ta sử dụng hệ thống lọc chứa hóa chất chuyên dụng. Biết rằng mỗi kilôgam hóa chất có khả năng hấp thụ tối đa 15 mol CO2. Trong một ngày, khối lượng hóa chất tối thiểu cần để xử lý toàn bộ lượng CO2 do 25 thuyền viên thải ra là bao nhiêu kilôgam (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"$n_{CO_2}=25.\\frac{1,01.10^5.465.10^{−3}}{8,31.300}=470,97\\left(mol\\right)$<br>Khối lượng chất cần dùng  $\\frac{n_{CO_2}}{15}\\approx 31,4\\left(kg\\right)$","difficultySource":"ai"}}]},{"id":1479007,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"42,4","question":"Nhiệt độ của khí trong bình bằng bao nhiêu celsius thì van sẽ bắt đầu xả khí ra ngoài (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Hướng dẫn giải Gọi p1,T1 là áp suất và nhiệt độ ban đầu của khí.<br>Gọi p2,T2 là áp suất và nhiệt độ của khí khi van bắt đầu xả khí.<br>Khi van bắt đầu xả, pít-tông đã dịch chuyển một đoạn ℓ = 2 mm = 2.10<sup>−3</sup> m.<br>Độ tăng áp suất của khí trong bình để thắng được lực đàn hồi của lò xo nén thêm đoạn l là: k.l<br>$\\Delta p=p_2−p_1=\\frac{kℓ}{S}$<br>Thể tích khí coi như không đổi, V = 20l = 20.10<sup>−3</sup> m3.<br>Áp dụng phương trình trạng thái ở hai thời điểm:<br>p1.V = nRT1<br>p2.V = nRT2<br>Trừ vế theo vế hai phương trình trên, ta được:<br>$\\left(p_2−p_1\\right).V=nR\\left(T_2−T_1\\right)$<br>Suy ra độ tăng nhiệt độ của khí là:<br>$\\Delta T=T_2−T_1=\\frac{\\left(p_2−p_1\\right)V}{nR}=\\frac{k.ℓ.V}{S.n.R}$<br>$\\Rightarrow \\Delta T=\\frac{50.2.10^{−3}.20.10^{−3}}{15,6.10^{−6}.1.8,31}\\approx 15,4278K$<br>Trong nhiệt giai Celsius, độ biến thiên nhiệt độ Δt có cùng giá trị với ΔT , nên: Δt  $\\approx$  15,4278°C .<br>Nhiệt độ của khí khi van bắt đầu xả là:<br>$t_2=t_1+\\Delta t=27+15,4278=42,4278^\\circ C$","difficultySource":"ai"},"ex":[{"exam":179,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"42,4","question":"Nhiệt độ của khí trong bình bằng bao nhiêu celsius thì van sẽ bắt đầu xả khí ra ngoài (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Hướng dẫn giải Gọi p1,T1 là áp suất và nhiệt độ ban đầu của khí.<br>Gọi p2,T2 là áp suất và nhiệt độ của khí khi van bắt đầu xả khí.<br>Khi van bắt đầu xả, pít-tông đã dịch chuyển một đoạn ℓ = 2 mm = 2.10<sup>−3</sup> m.<br>Độ tăng áp suất của khí trong bình để thắng được lực đàn hồi của lò xo nén thêm đoạn l là: k.l<br>$\\Delta p=p_2−p_1=\\frac{kℓ}{S}$<br>Thể tích khí coi như không đổi, V = 20l = 20.10<sup>−3</sup> m3.<br>Áp dụng phương trình trạng thái ở hai thời điểm:<br>p1.V = nRT1<br>p2.V = nRT2<br>Trừ vế theo vế hai phương trình trên, ta được:<br>$\\left(p_2−p_1\\right).V=nR\\left(T_2−T_1\\right)$<br>Suy ra độ tăng nhiệt độ của khí là:<br>$\\Delta T=T_2−T_1=\\frac{\\left(p_2−p_1\\right)V}{nR}=\\frac{k.ℓ.V}{S.n.R}$<br>$\\Rightarrow \\Delta T=\\frac{50.2.10^{−3}.20.10^{−3}}{15,6.10^{−6}.1.8,31}\\approx 15,4278K$<br>Trong nhiệt giai Celsius, độ biến thiên nhiệt độ Δt có cùng giá trị với ΔT , nên: Δt  $\\approx$  15,4278°C .<br>Nhiệt độ của khí khi van bắt đầu xả là:<br>$t_2=t_1+\\Delta t=27+15,4278=42,4278^0C$","difficultySource":"ai"}}]},{"id":1479008,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"6","question":"Một học sinh dùng một đoạn dây dẫn dài 10 m quấn thành một khung dây cứng hình chữ nhật ABCD có AB = 4 cm, BC = 6 cm . Khung dây được đặt trong từ trường có các đường sức từ vuông góc với mặt phẳng khung và có độ lớn cảm ứng từ B biến thiên theo thời gian như đồ thị (hình a). Đoạn dây có điện trở trên mỗi đơn vị chiều dài là 0,02Ω/m. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260079363-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Trong khoảng thời gian từ 0 đến 0,1 s, cường độ dòng điện trong khung dây có độ lớn bằng bao nhiêu miliampe (mA )?","difficulty":"trung-binh","explanation":"Chu vi của một vòng dây hình chữ nhật là: $C=2\\left(0,04+0,06\\right)=0,2m$  .<br>Số vòng dây của khung là:  $N=\\frac{10}{0,2}=$  50 (vòng).<br>Diện tích một vòng dây: S =0,04.0,06 = 2,4.10<sup>−3</sup>m2<br>Điện trở của toàn bộ khung dây: R = 0,02.10 = 0,2Ω .<br>Từ đồ thị, trong khoảng thời gian từ t = 0 đến t = 0,2 s , cảm ứng từ giảm đều từ 2 mT xuống 0. Do đó, tốc độ biến thiên cảm ứng từ trong khoảng thời gian từ 0 đến 0,1 s (cũng chính là tốc độ trên toàn đoạn từ 0 đến 0,2 s) là:<br>$\\left|\\frac{\\Delta B}{\\Delta t}\\right|=\\left|\\frac{0−2.10^{−3}}{0,2−0}\\right|=0,01\\left(T/s\\right)$<br>Độ lớn suất điện động cảm ứng xuất hiện trong toàn bộ khung dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260079659-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Cường độ dòng điện trong khung dây có độ lớn là:<br>$I=\\frac{\\left|e_c\\right|}{R}=\\frac{1,2.10^{−3}}{0,2}=6.10^{−3}A=6mA$","difficultySource":"ai"},"ex":[{"exam":179,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"6","question":"Một học sinh dùng một đoạn dây dẫn dài 10 m quấn thành một khung dây cứng hình chữ nhật ABCD có AB = 4 cm, BC = 6 cm . Khung dây được đặt trong từ trường có các đường sức từ vuông góc với mặt phẳng khung và có độ lớn cảm ứng từ B biến thiên theo thời gian như đồ thị (hình a). Đoạn dây có điện trở trên mỗi đơn vị chiều dài là 0,02Ω/m. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260079363-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Trong khoảng thời gian từ 0 đến 0,1 s, cường độ dòng điện trong khung dây có độ lớn bằng bao nhiêu miliampe (mA )?","difficulty":"trung-binh","explanation":"Chu vi của một vòng dây hình chữ nhật là: $C=2\\left(0,04+0,06\\right)=0,2m$  .<br>Số vòng dây của khung là:  $N=\\frac{10}{0,2}=$  50 (vòng).<br>Diện tích một vòng dây: S =0,04.0,06 = 2,4.10<sup>−3</sup>m2<br>Điện trở của toàn bộ khung dây: R = 0,02.10 = 0,2Ω .<br>Từ đồ thị, trong khoảng thời gian từ t = 0 đến t = 0,2 s , cảm ứng từ giảm đều từ 2 mT xuống 0. Do đó, tốc độ biến thiên cảm ứng từ trong khoảng thời gian từ 0 đến 0,1 s (cũng chính là tốc độ trên toàn đoạn từ 0 đến 0,2 s) là:<br>$\\left|\\frac{\\Delta B}{\\Delta t}\\right|=\\left|\\frac{0−2.10^{−3}}{0,2−0}\\right|=0,01\\left(T/s\\right)$<br>Độ lớn suất điện động cảm ứng xuất hiện trong toàn bộ khung dây là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260079659-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Cường độ dòng điện trong khung dây có độ lớn là:<br>$I=\\frac{\\left|e_c\\right|}{R}=\\frac{1,2.10^{−3}}{0,2}=6.10^{−3}A=6mA$","difficultySource":"ai"}}]},{"id":1479010,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"0,05","question":"Đồng vị Xenon ${}_{54}^{133}{Xe}$  là chất phóng xạ β- có chu kì bán rã là 5,24 ngày đêm. Trong y học, hỗn hợp khí chứa Xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều Xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq . Coi rằng 85% lượng Xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24 giờ. Biết khối lượng mol nguyên tử của Xenon là 133 g / mol.<br>Khối lượng  ${}_{54}^{133}{Xe}$  có trong liều mà người bệnh đã hít vào là bao nhiêu microgram (µg ) (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Chu kì bán rã: T = 5,24 ngày đêm = 5,24.24.24.3600 = 452736 s.<br>Độ phóng xạ ban đầu của liều hít vào: H0 = 3,18.10<sup>8</sup>Bq<br>Từ công thức  $H_0=\\frac{ln2}{T}.\\frac{m_0}{N}.N_A$ , ta có:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260080338-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_0=4,59.10^{−2}\\mu g\\approx 0,05\\mu g$","difficultySource":"ai"},"ex":[{"exam":179,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"0,05","question":"Đồng vị Xenon ${}_{54}^{133}{Xe}$  là chất phóng xạ β- có chu kì bán rã là 5,24 ngày đêm. Trong y học, hỗn hợp khí chứa Xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều Xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq . Coi rằng 85% lượng Xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24 giờ. Biết khối lượng mol nguyên tử của Xenon là 133 g / mol.<br>Khối lượng  ${}_{54}^{133}{Xe}$  có trong liều mà người bệnh đã hít vào là bao nhiêu microgram (µg ) (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Chu kì bán rã: T = 5,24 ngày đêm = 5,24.24.24.3600 = 452736 s.<br>Độ phóng xạ ban đầu của liều hít vào: H0 = 3,18.10<sup>8</sup>Bq<br>Từ công thức  $H_0=\\frac{ln2}{T}.\\frac{m_0}{N}.N_A$ , ta có:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260080338-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\Rightarrow m_0=4,59.10^{−2}\\mu g\\approx 0,05\\mu g$","difficultySource":"ai"}}]},{"id":1479011,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"2,4","question":"Đồng vị Xenon ${}_{54}^{133}{Xe}$  là chất phóng xạ β- có chu kì bán rã là 5,24 ngày đêm. Trong y học, hỗn hợp khí chứa Xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều Xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq . Coi rằng 85% lượng Xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24 giờ. Biết khối lượng mol nguyên tử của Xenon là 133 g / mol.<br>Sau khi dùng thuốc 24,0 giờ, lượng  ${}_{54}^{133}{Xe}$  đã lắng đọng tại phổi có độ phóng xạ là x.10<sup>8</sup> Bq. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Độ phóng xạ ban đầu của lượng Xenon lắng đọng tại phổi là:<br>H0p = 85%H0 = 0,85.3,18.10<sup>8</sup> = 2,703.10<sup>8</sup> (Bq)<br>Thời gian sau lần chụp thứ nhất là t = 24,0h = 1 ngày<br>Độ phóng xạ của lượng Xenon lắng đọng tại phổi sau thời gian t là:<br>$H=H_0.2^{−\\frac{t}{T}}=2,703.10^8.2^{\\frac{−1}{5,24}}\\approx 2,4.10^8\\left(Bq\\right)$","difficultySource":"ai"},"ex":[{"exam":179,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"2,4","question":"Đồng vị Xenon ${}_{54}^{133}{Xe}$  là chất phóng xạ β- có chu kì bán rã là 5,24 ngày đêm. Trong y học, hỗn hợp khí chứa Xenon được sử dụng để đánh giá độ thông khí của phổi người bệnh. Một người bệnh được chỉ định sử dụng liều Xenon có độ phóng xạ 3,18.10<sup>8</sup> Bq . Coi rằng 85% lượng Xenon trong liều đó lắng đọng tại phổi. Người bệnh được chụp ảnh phổi lần thứ nhất ngay sau khi hít khí và lần thứ hai sau đó 24 giờ. Biết khối lượng mol nguyên tử của Xenon là 133 g / mol.<br>Sau khi dùng thuốc 24,0 giờ, lượng  ${}_{54}^{133}{Xe}$  đã lắng đọng tại phổi có độ phóng xạ là x.10<sup>8</sup> Bq. Tìm x (làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Độ phóng xạ ban đầu của lượng Xenon lắng đọng tại phổi là:<br>H0p = 85%H0 = 0,85.3,18.10<sup>8</sup> = 2,703.10<sup>8</sup> (Bq)<br>Thời gian sau lần chụp thứ nhất là t = 24,0h = 1 ngày<br>Độ phóng xạ của lượng Xenon lắng đọng tại phổi sau thời gian t là:<br>$H=H_0.2^{−\\frac{t}{T}}=2,703.10^8.2^{\\frac{−1}{5,24}}\\approx 2,4.10^8\\left(Bq\\right)$","difficultySource":"ai"}}]},{"id":1479022,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["0,2 V.","8 V.","2.10<sup>−4</sup> V.","2.10<sup>−3</sup> V."],"question":"Một khung dây phẳng có diện tích 25 cm2, gồm 10 vòng dây đặt trong từ trường đều, mặt phẳng vòng dây vuông góc với các đường sức từ. Hình bên là đồ thị biểu diễn sự phụ thuộc của độ lớn cảm ứng từ B vào thời gian t. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260140105-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Độ lớn của suất điện động cảm ứng xuất hiện trong khung từ thời điểm t1 = 0 đến thời điểm t2 = 0,5 s là","difficulty":"trung-binh","explanation":"$\\left|e_C\\right|=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{N\\Delta BS}{\\Delta t}=\\frac{10.\\left(6−2\\right).10^{−3}.25.10^{−4}}{0,5−0}=2.10^{−4}V$","distractorNotes":{"A":"Quên đổi mT sang T khi tính $\\Delta B$, nên kết quả lớn gấp nhiều bậc.","B":"Chỉ lấy $\\Delta B/\\Delta t$, bỏ sót số vòng $N$ và diện tích $S$ trong $\\Delta\\Phi=N\\Delta BS$.","D":"Sai một bậc lũy thừa 10 khi đổi cm² sang m² hoặc khi nhân các số."},"difficultySource":"ai"},"ex":[{"exam":189,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["0,2 V.","8 V.","2.10<sup>−4</sup> V.","2.10<sup>−3</sup> V."],"question":"Một khung dây phẳng có diện tích 25 cm2, gồm 10 vòng dây đặt trong từ trường đều, mặt phẳng vòng dây vuông góc với các đường sức từ. Hình bên là đồ thị biểu diễn sự phụ thuộc của độ lớn cảm ứng từ B vào thời gian t. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790260140105-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Độ lớn của suất điện động cảm ứng xuất hiện trong khung từ thời điểm t1 = 0 đến thời điểm t2 = 0,5 s là","difficulty":"trung-binh","explanation":"$\\left|e_C\\right|=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=\\frac{N\\Delta BS}{\\Delta t}=\\frac{10.\\left(6−2\\right).10^{−3}.25.10^{−4}}{0,5−0}=2.10^{−4}V$","distractorNotes":{"A":"Quên đổi mT sang T khi tính $\\Delta B$, nên kết quả lớn gấp nhiều bậc.","B":"Chỉ lấy $\\Delta B/\\Delta t$, bỏ sót số vòng $N$ và diện tích $S$ trong $\\Delta\\Phi=N\\Delta BS$.","D":"Sai một bậc lũy thừa 10 khi đổi cm² sang m² hoặc khi nhân các số."},"difficultySource":"ai"}}]},{"id":1479077,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["225 mW.","0,09 mW.","22,5 mW.","9 W."],"question":"Một khung dây dẫn kín hình vuông có cạnh dài 10cm gồm 500 vòng được đặt trong từ trường đều sao vector cảm ứng từ vuông góc với bề mặt khung dây. Điện trở suất và tiết diện của dây kim loại có giá trị lần lượt là 2.10<sup>−8</sup> Ω𝑚 và 0,4 mm2. Giá trị cảm ứng từ biến thiên theo thời gian có đồ thị như hình bên. Công suất tỏa nhiệt sinh ra trong khung dây có giá trị bao nhiêu?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383285-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:195px;height:auto\" />","difficulty":"trung-binh","explanation":"Chiều dài dây là:  $ℓ=nc=500.4.10=20000\\left(cm\\right)=200\\left(m\\right)$<br>Điện trở khung dây là:  $R=\\rho .\\frac{ℓ}{S}=10\\Omega$<br>Suất điện động cảm ứng là:  $e=−\\frac{\\Delta \\Phi }{\\Delta t}=1,5\\left(V\\right)$<br>Dòng điện cảm ứng  $i=\\frac{e}{R}=0,15\\left(A\\right)$<br>Công suất:  $P=i^2R=0,225\\left(W\\right)=225\\left(mmW\\right)$","difficultySource":"ai"},"ex":[{"exam":301,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["225 mW.","0,09 mW.","22,5 mW.","9 W."],"question":"Một khung dây dẫn kín hình vuông có cạnh dài 10cm gồm 500 vòng được đặt trong từ trường đều sao vector cảm ứng từ vuông góc với bề mặt khung dây. Điện trở suất và tiết diện của dây kim loại có giá trị lần lượt là 2.10<sup>−8</sup> Ω𝑚 và 0,4 mm2. Giá trị cảm ứng từ biến thiên theo thời gian có đồ thị như hình bên. Công suất tỏa nhiệt sinh ra trong khung dây có giá trị bao nhiêu?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383285-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:195px;height:auto\" />","difficulty":"trung-binh","explanation":"Chiều dài dây là:  $ℓ=nc=500.4.10=20000\\left(cm\\right)=200\\left(m\\right)$<br>Điện trở khung dây là:  $R=\\rho .\\frac{ℓ}{S}=10\\Omega$<br>Suất điện động cảm ứng là:  $e=−\\frac{\\Delta \\Phi }{\\Delta t}=1,5\\left(V\\right)$<br>Dòng điện cảm ứng  $i=\\frac{e}{R}=0,15\\left(A\\right)$<br>Công suất:  $P=i^2R=0,225\\left(W\\right)=225\\left(mmW\\right)$","difficultySource":"ai"}}]},{"id":1479091,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Để nghiên cứu và ứng dụng các hạt vật chất nhỏ hơn nguyên tử,người ta thường sử dụng máy cyclotron (hình vẽ). Máy này hoạt động dựa trên nguyên tắc kết hợp điện trường và từ trường để làm tăng tốc các hạt điện tích chuyển động.Máy cyclotron có hai hộp rỗng hình chữ D (hai cực D1 và D2) làm bằng đồng ghép với nhau thành một hình tròn được đặt trong chân không từ trường đều có cảm ứng từ B vuông góc với mặt hộp. Hai cạnh thẳng đứng của các hộp D không đặt sát nhau mà cách nhau một khoảng hẹp,ở giữa khoảng<br>hẹp có một điện trường E. Điện tích phóng ra ở gần tâm máy được tăng tốc trực tiếp bởi lực điện khi đi qua điện trường giữa hai hộp D và được lực từ làm cho chuyển động tròn trong hộp. Vì điện tích được tăng tốc dần nên bán kính quỹ đạo cũng tăng theo. Xét chuyển động của hạt đơ-tơ-rôn trong một máy cyclotron. Biết đơ-tơ-rôn có khối lượng nghỉ là 3,31.10<sup>−27</sup> kg và điện tích +1,6.10<sup>−19</sup>, bay theo phương vuông góc với các đường sức từ với tốc độ 3,2.10<sup>6</sup>m/s (ở cực D1). Hiệu điện thế giữa hai cực D là 100kV và độ lớn cảm ứng từ B là 1,6T. Biết đơ-tơ-rôn bay ra khỏi các cực theo phương song song với các đường sức điện của điện trường giữa hai cực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383818-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:191px;height:auto\" />","difficulty":"kho","statements":[{"text":"Bán kính quỹ đạo chuyển động của deuteron trong từ trường ở cực D1 = 4,175cm.","answer":true},{"text":"Chu kì chuyển động của deuteron trong từ trường ở cực D1 =  0,063µs.","answer":false},{"text":"Bán kính của quỹ đạo của deuteron trong từ trưởng ở cực D2 bằng 5,8/2cm.","answer":false},{"text":"Nếu bán kính của cyclotron là 50cm thì hạt deuteron được tăng tốc bởi điện trường 189 lần.","answer":false}],"explanation":"a) đúng<br>F = q.B.v và lực lo-ren-xơ đóng vai trò lực hướng tâm làm vật chuyển động tròn đều nên: m.v<br>Bán kính của vật là:  $R_0=\\frac{m.v}{q.B}=4,175\\left(cm\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Do chuyển động tròn đều nên chu kì  $T=\\frac{2\\pi .m}{qB}$<br>Thay số vào tính được:  $T=0,082\\left(\\mu s\\right)$<br>c) sai<br>Gọi V0 là vận tốc ban đầu của vật m (khi xuất phát ở D1)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sau khi chuyển động tròn nó đi vào vùng từ trường và được tăng tốc bởi hiệu điện thế U nên có vận tốc v1<br>Và vào vùng từ trường D2 sẽ tiếp tục chuyển động tròn đều với vận tốc v1 dưới tác dụng lực lorenxo.<br>Ta có A = Wđ1 – Wđ2<br>$\\begin{aligned}\\end{aligned}\\Leftrightarrow \\frac{2qU}{m}=v_1^2−v_0^2\\Rightarrow v_1=4,452.10^6\\left(m/s\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính quỹ đạo lúc này là  $R_1=\\frac{mv_1}{qB}\\Rightarrow$  R1 = 5,8 (cm)<br>d) sai<br>Ta chứng minh một các tuần tự để quy nạp :<br>Sau khi qui nạp ra ta có:  $v_n^2=v_0^2+\\frac{2qU}{m}.n\\left(*\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khi Rn = 50cm<br>Ta có tỉ lệ thuận R và v nên khi đó  $v_n=\\frac{2000}{167}v_0Website: thukhoadaihoc.vn$<br>Thay số vào (*) ta tính ngay được n = 150","difficultySource":"ai"},"ex":[{"exam":301,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ. Cảm ứng từ","question":"Để nghiên cứu và ứng dụng các hạt vật chất nhỏ hơn nguyên tử,người ta thường sử dụng máy cyclotron (hình vẽ). Máy này hoạt động dựa trên nguyên tắc kết hợp điện trường và từ trường để làm tăng tốc các hạt điện tích chuyển động.Máy cyclotron có hai hộp rỗng hình chữ D (hai cực D1 và D2) làm bằng đồng ghép với nhau thành một hình tròn được đặt trong chân không từ trường đều có cảm ứng từ B vuông góc với mặt hộp. Hai cạnh thẳng đứng của các hộp D không đặt sát nhau mà cách nhau một khoảng hẹp,ở giữa khoảng<br>hẹp có một điện trường E. Điện tích phóng ra ở gần tâm máy được tăng tốc trực tiếp bởi lực điện khi đi qua điện trường giữa hai hộp D và được lực từ làm cho chuyển động tròn trong hộp. Vì điện tích được tăng tốc dần nên bán kính quỹ đạo cũng tăng theo. Xét chuyển động của hạt đơ-tơ-rôn trong một máy cyclotron. Biết đơ-tơ-rôn có khối lượng nghỉ là 3,31.10<sup>−27</sup> kg và điện tích +1,6.10<sup>−19</sup>, bay theo phương vuông góc với các đường sức từ với tốc độ 3,2.10<sup>6</sup>m/s (ở cực D1). Hiệu điện thế giữa hai cực D là 100kV và độ lớn cảm ứng từ B là 1,6T. Biết đơ-tơ-rôn bay ra khỏi các cực theo phương song song với các đường sức điện của điện trường giữa hai cực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224383818-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:191px;height:auto\" />","difficulty":"kho","statements":[{"text":"Bán kính quỹ đạo chuyển động của deuteron trong từ trường ở cực D1 = 4,175cm.","answer":true},{"text":"Chu kì chuyển động của deuteron trong từ trường ở cực D1 =  0,063µs.","answer":false},{"text":"Bán kính của quỹ đạo của deuteron trong từ trưởng ở cực D2 bằng 5,8/2cm.","answer":false},{"text":"Nếu bán kính của cyclotron là 50cm thì hạt deuteron được tăng tốc bởi điện trường 189 lần.","answer":false}],"explanation":"a) đúng<br>F = q.B.v và lực lo-ren-xơ đóng vai trò lực hướng tâm làm vật chuyển động tròn đều nên: m.v<br>Bán kính của vật là:  $R_0=\\frac{m.v}{q.B}=4,175\\left(cm\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Do chuyển động tròn đều nên chu kì  $T=\\frac{2\\pi .m}{qB}$<br>Thay số vào tính được:  $T=0,082\\left(\\mu s\\right)$<br>c) sai<br>Gọi V0 là vận tốc ban đầu của vật m (khi xuất phát ở D1)<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Sau khi chuyển động tròn nó đi vào vùng từ trường và được tăng tốc bởi hiệu điện thế U nên có vận tốc v1<br>Và vào vùng từ trường D2 sẽ tiếp tục chuyển động tròn đều với vận tốc v1 dưới tác dụng lực lorenxo.<br>Ta có A = Wđ1 – Wđ2<br>$\\begin{aligned}\\end{aligned}\\Leftrightarrow \\frac{2qU}{m}=v_1^2−v_0^2\\Rightarrow v_1=4,452.10^6\\left(m/s\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Bán kính quỹ đạo lúc này là  $R_1=\\frac{mv_1}{qB}\\Rightarrow$  R1 = 5,8 (cm)<br>d) sai<br>Ta chứng minh một các tuần tự để quy nạp :<br>Sau khi qui nạp ra ta có:  $v_n^2=v_0^2+\\frac{2qU}{m}.n\\left(*\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khi Rn = 50cm<br>Ta có tỉ lệ thuận R và v nên khi đó  $v_n=\\frac{2000}{167}v_0Website: thukhoadaihoc.vn$<br>Thay số vào (*) ta tính ngay được n = 150","difficultySource":"ai"}}]},{"id":1479146,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"5,9","question":"Thông thường, phổi của một người trưởng thành có thể tích khoảng 5,7 lít. Biết không khí trong phổi có áp suất bằng áp suất khí quyển (101 kPa) và nhiệt độ là 37 °C. Giả sử số phân tử khí oxygen chiếm 21% số phân tử không khí có trong phổi.<br>Khi người đó hít sâu, giả sử không khí trong phổi có 1,4.10<sup>23</sup> phân tử. Dung tích phổi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Một dây dẫn thẳng nằm ngang, được dùng để truyền tải dòng điện xoay chiều đi xa. Cường độ dòng điện hiệu dụng trong dây dẫn này là 106 A.","difficulty":"trung-binh","explanation":"Đáp số 5,9<br>Phương pháp:<br>Áp dụng phương trình Clapeyron:  $pV=nRT$<br>Cách giải:<br>Số mol phân tử khí trong phổi là:<br>$n=\\frac{N}{N_A}=\\frac{1,4.10^{23}}{6,022.10^{23}}=0,2325\\left(mol\\right)$<br>Áp dụng phương trình Clapeyron:<br>$\\begin{aligned}\\end{aligned}pV=nRT\\Rightarrow V=\\frac{nRT}{p}=\\frac{0,2325.8,314.310}{101.10^3}=5,9.10^{−3}m^3=5,9\\left(ℓ\\right)$<br>Vậy thể tích phổi là 5,9l .","difficultySource":"ai"},"ex":[{"exam":214,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"5,9","question":"Thông thường, phổi của một người trưởng thành có thể tích khoảng 5,7 lít. Biết không khí trong phổi có áp suất bằng áp suất khí quyển (101 kPa) và nhiệt độ là 37 °C. Giả sử số phân tử khí oxygen chiếm 21% số phân tử không khí có trong phổi.<br>Khi người đó hít sâu, giả sử không khí trong phổi có 1,4.10<sup>23</sup> phân tử. Dung tích phổi khi đó là bao nhiêu lít (làm tròn kết quả đến chữ số hàng phần mười)?<br>Sử dụng các thông tin sau cho Câu 3 và Câu 4: Một dây dẫn thẳng nằm ngang, được dùng để truyền tải dòng điện xoay chiều đi xa. Cường độ dòng điện hiệu dụng trong dây dẫn này là 106 A.","difficulty":"trung-binh","explanation":"Đáp số 5,9<br>Phương pháp:<br>Áp dụng phương trình Clapeyron:  $pV=nRT$<br>Cách giải:<br>Số mol phân tử khí trong phổi là:<br>$n=\\frac{N}{N_A}=\\frac{1,4.10^{23}}{6,022.10^{23}}=0,2325\\left(mol\\right)$<br>Áp dụng phương trình Clapeyron:<br>$\\begin{aligned}\\end{aligned}pV=nRT\\Rightarrow V=\\frac{nRT}{p}=\\frac{0,2325.8,314.310}{101.10^3}=5,9.10^{−3}m^3=5,9\\left(ℓ\\right)$<br>Vậy thể tích phổi là 5,9l .","difficultySource":"ai"}}]},{"id":1479371,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"8,9","question":"Để nghiên cứu hiệu quả của một loại phân bón vi lượng mới, các nhà khoa học sử dụng đồng vị phóng xạ Phosphorus-32 (32P) làm nguyên tử đánh dấu. Biết rằng 32P là chất phóng xạ β‒ với chu kỳ bán rã là T = 14,3 ngày. Một lượng phân bón chứa 32P với độ phóng xạ ban đầu là H0 = 5.10<sup>5</sup> Bq được bón vào gốc một cây ngô. Các nhà khoa học nhận thấy rằng quá trình hấp thụ 32P của cây ngô diễn ra không đều theo thời gian. Trong chu kì bán rã đầu tiên, cây hấp thụ và tích lũy được số nguyên tử 32P bằng 20% số nguyên tử 32P có trong lượng phân bón ban đầu. Trong chu kì bán rã tiếp theo, cây hấp thụ và tích lũy thêm số nguyên tử 32P bằng 40% số nguyên tử 32P còn lại trong đất kể từ thời điểm bắt đầu chu kỳ thứ hai.<br>Số nguyên tử 32P chứa trong lượng phân bón ban đầu là m.1011 nguyên tử. Tìm m (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Chu kỳ bán rã tính theo giây: T = 14,3 ngày = 14,3.24.3600 = 1235520s .<br>Số nguyên tử ban đầu:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790515955099-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />nguyên tử<br>Ta có N0 = m.1011 , suy ra m  $\\approx$  8,912 .<br>Làm tròn đến chữ số hàng phần mười, ta được 8,9.","difficultySource":"ai"},"ex":[{"exam":229,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"8,9","question":"Để nghiên cứu hiệu quả của một loại phân bón vi lượng mới, các nhà khoa học sử dụng đồng vị phóng xạ Phosphorus-32 (32P) làm nguyên tử đánh dấu. Biết rằng 32P là chất phóng xạ β‒ với chu kỳ bán rã là T = 14,3 ngày. Một lượng phân bón chứa 32P với độ phóng xạ ban đầu là H0 = 5.10<sup>5</sup> Bq được bón vào gốc một cây ngô. Các nhà khoa học nhận thấy rằng quá trình hấp thụ 32P của cây ngô diễn ra không đều theo thời gian. Trong chu kì bán rã đầu tiên, cây hấp thụ và tích lũy được số nguyên tử 32P bằng 20% số nguyên tử 32P có trong lượng phân bón ban đầu. Trong chu kì bán rã tiếp theo, cây hấp thụ và tích lũy thêm số nguyên tử 32P bằng 40% số nguyên tử 32P còn lại trong đất kể từ thời điểm bắt đầu chu kỳ thứ hai.<br>Số nguyên tử 32P chứa trong lượng phân bón ban đầu là m.1011 nguyên tử. Tìm m (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Chu kỳ bán rã tính theo giây: T = 14,3 ngày = 14,3.24.3600 = 1235520s .<br>Số nguyên tử ban đầu:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790515955099-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />nguyên tử<br>Ta có N0 = m.1011 , suy ra m  $\\approx$  8,912 .<br>Làm tròn đến chữ số hàng phần mười, ta được 8,9.","difficultySource":"ai"}}]},{"id":1479372,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"1,1","question":"Để nghiên cứu hiệu quả của một loại phân bón vi lượng mới, các nhà khoa học sử dụng đồng vị phóng xạ Phosphorus-32 (32P) làm nguyên tử đánh dấu. Biết rằng 32P là chất phóng xạ β‒ với chu kỳ bán rã là T = 14,3 ngày. Một lượng phân bón chứa 32P với độ phóng xạ ban đầu là H0 = 5.10<sup>5</sup> Bq được bón vào gốc một cây ngô. Các nhà khoa học nhận thấy rằng quá trình hấp thụ 32P của cây ngô diễn ra không đều theo thời gian. Trong chu kì bán rã đầu tiên, cây hấp thụ và tích lũy được số nguyên tử 32P bằng 20% số nguyên tử 32P có trong lượng phân bón ban đầu. Trong chu kì bán rã tiếp theo, cây hấp thụ và tích lũy thêm số nguyên tử 32P bằng 40% số nguyên tử 32P còn lại trong đất kể từ thời điểm bắt đầu chu kỳ thứ hai.<br>Độ phóng xạ của 32P có trong cây ngô sau 28,6 ngày là n.105 Bq. Tìm n (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Thời gian t = 28,6 ngày =2T (trải qua 2 chu kỳ bán rã).<br>Tại thời điểm cuối chu kỳ 1 (t = T)<br>Cây tích lũy được lượng nguyên tử là: Ncây1 = 0,2N0.<br>Tổng số hạt 32P chưa bị phân rã (cả trong cây và đất) ở thời điểm này là:  $N_0.2^{−1}=0,5N_0$  .<br>Suy ra lượng nguyên tử còn lại trong đất tại t = T là:  $N_{dat1}=0,5N_0−0,2N_0=0,3N_0$  .<br>Tại thời điểm cuối chu kỳ 2(t = 2T):<br>Trong chu kỳ 2, lượng nguyên tử cũ trong cây (Ncây) bị phân rã đi một nửa.<br>Vậy lượng nguyên tử cũ còn lại trong cây là: Ncây1  $=\\frac{0,2N_0}{2}=0,1N_0$  .<br>Đồng thời cây tích lũy thêm 40% số hạt có trong đất từ đầu chu kỳ 2:<br>ΔNcây 2 =  0,4.Ndat 1 = 0,4.0,3N0 = 0,12N0 .<br>Tổng số nguyên tử 32P trong cây tại t = 2T là:<br>Ncây 2 = Ncây 1’ + ΔNcây 2 = 0,1N0 + 0,12N0 = 0,22N0 .<br>Độ phóng xạ của cây lúc này:<br>Hcây = λ.Ncây 2 = λ.(0,22N0) = 0,22.(λN0) = 0,22.H0<br>Thay số H0 = 5.10<sup>5</sup> Bq, ta được:<br>Hcây = 0,22.5.10<sup>5</sup> = 1,1.10<sup>5</sup>Bq.<br>Ta có Hcây = n.105, suy ra n =1,1.","difficultySource":"ai"},"ex":[{"exam":229,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"1,1","question":"Để nghiên cứu hiệu quả của một loại phân bón vi lượng mới, các nhà khoa học sử dụng đồng vị phóng xạ Phosphorus-32 (32P) làm nguyên tử đánh dấu. Biết rằng 32P là chất phóng xạ β‒ với chu kỳ bán rã là T = 14,3 ngày. Một lượng phân bón chứa 32P với độ phóng xạ ban đầu là H0 = 5.10<sup>5</sup> Bq được bón vào gốc một cây ngô. Các nhà khoa học nhận thấy rằng quá trình hấp thụ 32P của cây ngô diễn ra không đều theo thời gian. Trong chu kì bán rã đầu tiên, cây hấp thụ và tích lũy được số nguyên tử 32P bằng 20% số nguyên tử 32P có trong lượng phân bón ban đầu. Trong chu kì bán rã tiếp theo, cây hấp thụ và tích lũy thêm số nguyên tử 32P bằng 40% số nguyên tử 32P còn lại trong đất kể từ thời điểm bắt đầu chu kỳ thứ hai.<br>Độ phóng xạ của 32P có trong cây ngô sau 28,6 ngày là n.105 Bq. Tìm n (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"Thời gian t = 28,6 ngày =2T (trải qua 2 chu kỳ bán rã).<br>Tại thời điểm cuối chu kỳ 1 (t = T)<br>Cây tích lũy được lượng nguyên tử là: Ncây1 = 0,2N0.<br>Tổng số hạt 32P chưa bị phân rã (cả trong cây và đất) ở thời điểm này là:  $N_0.2^{−1}=0,5N_0$  .<br>Suy ra lượng nguyên tử còn lại trong đất tại t = T là:  $N_{dat1}=0,5N_0−0,2N_0=0,3N_0$  .<br>Tại thời điểm cuối chu kỳ 2(t = 2T):<br>Trong chu kỳ 2, lượng nguyên tử cũ trong cây (Ncây) bị phân rã đi một nửa.<br>Vậy lượng nguyên tử cũ còn lại trong cây là: Ncây1  $=\\frac{0,2N_0}{2}=0,1N_0$  .<br>Đồng thời cây tích lũy thêm 40% số hạt có trong đất từ đầu chu kỳ 2:<br>ΔNcây 2 =  0,4.Ndat 1 = 0,4.0,3N0 = 0,12N0 .<br>Tổng số nguyên tử 32P trong cây tại t = 2T là:<br>Ncây 2 = Ncây 1’ + ΔNcây 2 = 0,1N0 + 0,12N0 = 0,22N0 .<br>Độ phóng xạ của cây lúc này:<br>Hcây = λ.Ncây 2 = λ.(0,22N0) = 0,22.(λN0) = 0,22.H0<br>Thay số H0 = 5.10<sup>5</sup> Bq, ta được:<br>Hcây = 0,22.5.10<sup>5</sup> = 1,1.10<sup>5</sup>Bq.<br>Ta có Hcây = n.105, suy ra n =1,1.","difficultySource":"ai"}}]},{"id":1479541,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"186","question":"Trong thành phần sữa bò có chứa potassium với nồng độ 2 g/ℓ. Trong đó có 0,0117 % là đồng vị phóng xạ potassium  ${}_{19}^{40}K$  với chu kì bán rã là 1,25.10<sup>9</sup> năm.<br>Sau tai nạn ở nhà máy điện hạt nhân Chernobyl vào năm 1986, người ta phát hiện có các đồng vị phóng xạ  ${}_{53}^{131}I$  trong khí quyển. Mưa sẽ làm cỏ nhiễm đồng vị phóng xạ này và cuối cùng nó xuất hiện trong sữa bò. Người ta đo được độ phóng xạ  ${}_{53}^{131}I$  trong sữa bò ở Ba Lan lúc đó là 2 kBq/ℓ. Biết chu kì bán rã của  ${}_{53}^{131}I$  là 8,02 ngày. Khối lượng của nguyên tử được xem gần bằng số khối của nguyên tử tính theo đơn vị amu. Lấy một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790617075332-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tính độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò theo đơn vị Bq (làm tròn kết quả đến hàng đơn vị).","difficulty":"trung-binh","explanation":"Khối lượng của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò là:<br>$m=3.2.0,0117%=0,000702 g$<br>Độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong sữa bò khi đó là:<br>$H_K=.N=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A=\\frac{\\ln\\left(2\\right)}{1,25.{10}^9.365.24.3600}.\\frac{0,000702}{40}.6,02.{10}^{23}\\approx 186 Bq$ .","difficultySource":"ai"},"ex":[{"exam":236,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"186","question":"Trong thành phần sữa bò có chứa potassium với nồng độ 2 g/ℓ. Trong đó có 0,0117 % là đồng vị phóng xạ potassium  ${}_{19}^{40}K$  với chu kì bán rã là 1,25.10<sup>9</sup> năm.<br>Sau tai nạn ở nhà máy điện hạt nhân Chernobyl vào năm 1986, người ta phát hiện có các đồng vị phóng xạ  ${}_{53}^{131}I$  trong khí quyển. Mưa sẽ làm cỏ nhiễm đồng vị phóng xạ này và cuối cùng nó xuất hiện trong sữa bò. Người ta đo được độ phóng xạ  ${}_{53}^{131}I$  trong sữa bò ở Ba Lan lúc đó là 2 kBq/ℓ. Biết chu kì bán rã của  ${}_{53}^{131}I$  là 8,02 ngày. Khối lượng của nguyên tử được xem gần bằng số khối của nguyên tử tính theo đơn vị amu. Lấy một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790617075332-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Tính độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò theo đơn vị Bq (làm tròn kết quả đến hàng đơn vị).","difficulty":"trung-binh","explanation":"Khối lượng của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò là:<br>$m=3.2.0,0117%=0,000702 g$<br>Độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong sữa bò khi đó là:<br>$H_K=.N=\\frac{\\ln\\left(2\\right)}{T}.\\frac{m}{M}.N_A=\\frac{\\ln\\left(2\\right)}{1,25.{10}^9.365.24.3600}.\\frac{0,000702}{40}.6,02.{10}^{23}\\approx 186 Bq$ .","difficultySource":"ai"}}]},{"id":1479542,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"40,2","question":"Trong thành phần sữa bò có chứa potassium với nồng độ 2 g/ℓ. Trong đó có 0,0117 % là đồng vị phóng xạ potassium  ${}_{19}^{40}K$  với chu kì bán rã là 1,25.10<sup>9</sup> năm.<br>Sau tai nạn ở nhà máy điện hạt nhân Chernobyl vào năm 1986, người ta phát hiện có các đồng vị phóng xạ  ${}_{53}^{131}I$  trong khí quyển. Mưa sẽ làm cỏ nhiễm đồng vị phóng xạ này và cuối cùng nó xuất hiện trong sữa bò. Người ta đo được độ phóng xạ  ${}_{53}^{131}I$  trong sữa bò ở Ba Lan lúc đó là 2 kBq/ℓ. Biết chu kì bán rã của  ${}_{53}^{131}I$  là 8,02 ngày. Khối lượng của nguyên tử được xem gần bằng số khối của nguyên tử tính theo đơn vị amu. Lấy một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790617075332-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Sau bao lâu thì độ phóng xạ của đồng vị phóng xạ  ${}_{53}^{131}I$  có trong 3 lít sữa bò ở Ba Lan khi đó giảm xuống bằng độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  được tính ở Câu 5?","difficulty":"trung-binh","explanation":"Độ phóng xạ của đồng vị phóng xạ  ${}_{53}^{131}I$  có trong sữa bò ở thời điểm t có giá trị bằng độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò, được xác định bằng biểu thức:<br>$H_I=H_o.2^{-\\frac{t}{T}}=H_K$    $2000.3.2^{-\\frac{t}{8,02}}=186$<br>$t\\approx 40,2$  ngày.","difficultySource":"ai"},"ex":[{"exam":236,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"40,2","question":"Trong thành phần sữa bò có chứa potassium với nồng độ 2 g/ℓ. Trong đó có 0,0117 % là đồng vị phóng xạ potassium  ${}_{19}^{40}K$  với chu kì bán rã là 1,25.10<sup>9</sup> năm.<br>Sau tai nạn ở nhà máy điện hạt nhân Chernobyl vào năm 1986, người ta phát hiện có các đồng vị phóng xạ  ${}_{53}^{131}I$  trong khí quyển. Mưa sẽ làm cỏ nhiễm đồng vị phóng xạ này và cuối cùng nó xuất hiện trong sữa bò. Người ta đo được độ phóng xạ  ${}_{53}^{131}I$  trong sữa bò ở Ba Lan lúc đó là 2 kBq/ℓ. Biết chu kì bán rã của  ${}_{53}^{131}I$  là 8,02 ngày. Khối lượng của nguyên tử được xem gần bằng số khối của nguyên tử tính theo đơn vị amu. Lấy một năm có 365 ngày.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790617075332-hinh-19.png\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Sau bao lâu thì độ phóng xạ của đồng vị phóng xạ  ${}_{53}^{131}I$  có trong 3 lít sữa bò ở Ba Lan khi đó giảm xuống bằng độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  được tính ở Câu 5?","difficulty":"trung-binh","explanation":"Độ phóng xạ của đồng vị phóng xạ  ${}_{53}^{131}I$  có trong sữa bò ở thời điểm t có giá trị bằng độ phóng xạ của đồng vị phóng xạ  ${}_{19}^{40}K$  có trong 3 lít sữa bò, được xác định bằng biểu thức:<br>$H_I=H_o.2^{-\\frac{t}{T}}=H_K$    $2000.3.2^{-\\frac{t}{8,02}}=186$<br>$t\\approx 40,2$  ngày.","difficultySource":"ai"}}]},{"id":1479579,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["chỉ truyền được trong chân không.","bị phản xạ khi gặp mặt phân cách giữa hai môi trường.","lan truyền trong chân không với tốc độ c = 3.10<sup>8</sup> m/s .","là sóng ngang và mang năng lượng."],"question":"Khi nói về sóng điện từ, phát biểu nào sau đây là sai? Sóng điện từ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai. Sóng điện từ truyền được trong cả chân không lẫn các môi trường vật chất như không khí, nước, thủy tinh... Không phải chỉ truyền trong chân không.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng. Sóng điện từ bị phản xạ khi gặp mặt phân cách giữa hai môi trường, như mọi loại sóng khác.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng. Trong chân không, sóng điện từ lan truyền với tốc độ $c = 3\\cdot 10^{8}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng. Vectơ cường độ điện trường $\\vec{E}$ và cảm ứng từ $\\vec{B}$ dao động vuông góc với nhau và cùng vuông góc với phương truyền sóng, nên sóng điện từ là sóng ngang. Sóng điện từ mang năng lượng.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: phát biểu sai là phương án <b>A</b>.</p>","difficultySource":"ai"},"ex":[{"exam":261,"idx":8,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["chỉ truyền được trong chân không.","bị phản xạ khi gặp mặt phân cách giữa hai môi trường.","lan truyền trong chân không với tốc độ c = 3.10<sup>8</sup> m/s .","là sóng ngang và mang năng lượng."],"question":"Khi nói về sóng điện từ, phát biểu nào sau đây là sai? Sóng điện từ","difficulty":"de","explanation":"Sóng điện từ truyền được trong tất cả các môi trường kể cả chân không.","difficultySource":"ai"}}]},{"id":1479652,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,69","question":"Giả sử quả bom nguyên tử thả xuống Hiroshima có chứa 100 kg quặng uranium trong đó  ${}_{92}^{235}U$ chiếm 25%. Biết trung bình mỗi phân hạch của  ${}_{92}^{235}U$ giải phóng 200 MeV.<br>Năng lượng giải phóng của vụ nổ tương đương x.10<sup>8</sup> kW.h? Tìm x (làm tròn đến hàng phần trăm). Lấy NA = 6,02.10<sup>23</sup> hạt; 1 MeV = 1,6.10<sup>−13</sup>J.","difficulty":"trung-binh","explanation":"Theo kết quả Câu 5, khối lượng  ${}_{92}^{235}U$ chứa trong 100 kg quặng uranium:<br>25%.100 = 25 kg = 25 000 g.<br>Số hạt nhân nguyên tử  ${}_{92}^{235}U$ :<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=n.N_A=\\frac{m}{M}.N_A=\\frac{25000}{235}.6,02.10^{23}=\\frac{301}{470}.10^{26}$  nguyên tử.<br>Năng lượng tỏa ra của vụ nổ:<br>$W=N.200 MeV=\\frac{301}{470}.10^{26}.200MeV=\\frac{301}{235}.10^{28}MeV=\\frac{301}{235}.10^{28}.1,6.10^{−13}=\\frac{2408}{1175}.10^{15}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số điện tương đương:  $n=\\frac{W}{3600000}=\\frac{\\frac{2408}{1175}.10^{15}}{3600000}\\approx 5,69.10^8\\left(kW.h\\right)$","difficultySource":"ai"},"ex":[{"exam":272,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,69","question":"Giả sử quả bom nguyên tử thả xuống Hiroshima có chứa 100 kg quặng uranium trong đó  ${}_{92}^{235}U$ chiếm 25%. Biết trung bình mỗi phân hạch của  ${}_{92}^{235}U$ giải phóng 200 MeV.<br>Năng lượng giải phóng của vụ nổ tương đương x.10<sup>8</sup> kW.h? Tìm x (làm tròn đến hàng phần trăm). Lấy NA = 6,02.10<sup>23</sup> hạt; 1 MeV = 1,6.10<sup>−13</sup>J.","difficulty":"trung-binh","explanation":"Theo kết quả Câu 5, khối lượng  ${}_{92}^{235}U$ chứa trong 100 kg quặng uranium:<br>25%.100 = 25 kg = 25 000 g.<br>Số hạt nhân nguyên tử  ${}_{92}^{235}U$ :<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=n.N_A=\\frac{m}{M}.N_A=\\frac{25000}{235}.6,02.10^{23}=\\frac{301}{470}.10^{26}$  nguyên tử.<br>Năng lượng tỏa ra của vụ nổ:<br>$W=N.200 MeV=\\frac{301}{470}.10^{26}.200MeV=\\frac{301}{235}.10^{28}MeV=\\frac{301}{235}.10^{28}.1,6.10^{−13}=\\frac{2408}{1175}.10^{15}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Số điện tương đương:  $n=\\frac{W}{3600000}=\\frac{\\frac{2408}{1175}.10^{15}}{3600000}\\approx 5,69.10^8\\left(kW.h\\right)$","difficultySource":"ai"}}]},{"id":1479741,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["65 C.","60 C.\tC. 55","","80 C."],"question":"Quá trình nấu rượu gạo (dung dịch ethanol) thủ công được thực hiện như sau:<br>Gạo được nấu chín, để nguội, rắc men, ủ kín từ 3 đến 5 ngày thu được hỗn hợp chủ yếu gồm nước, ethanol và bã rượu.<br>Đun nóng hỗn hợp trên (trong nồi chưng cất) đến nhiệt độ sôi để ethanol và nước hóa hơi và đi vào đường ống dẫn. Hỗn hợp hơi (ethanol và nước) trong đường ống được làm lạnh sẽ hóa lỏng và chảy vào bình hứng. Ta có bảng giá trị của ethanol và nước như sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045413921-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhiệt độ sôi (C)\tKhối lượng riêng (kg/m3)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg)<br>Ethanol\t78\t789\t2 440\t0,9.106<br>Nước\t100\t997\t4 200\t2,3.10<sup>6</sup><br>Giả thuyết trong quá trình nấu rượu, hỗn hợp được cung cấp nhiệt một cách đều đặn. Ethanol sôi và hóa hơi trước ở 78 C. Sau đó đến 100 C thì nước bắt đầu sôi và hóa hơi. Bỏ qua lượng hơi nước ban đầu trong ống dẫn. Bỏ qua sự truyền nhiệt với môi trường, ống dẫn và bình hứng. Thùng nước lạnh chứa lượng nước có thể tích 250 lít ở nhiệt độ 20 C. Khi thu được 20 lít rượu gạo 40 (thể tích ethanol chiếm 40%), người ta đo nhiệt độ của rượu khi có cân bằng nhiệt là 45 C. Biết nhiệt độ của ethanol khi ra khỏi thùng nước lạnh là 35 C.<br>Trong quá trình nấu rượu, nước trong thùng nước lạnh không được thay. Nhiệt độ của nước trong thùng nước lạnh khi thu được 20 lít rượu gạo 40 là","difficulty":"kho","explanation":"Khối lượng nước chứa trong thùng nước lạnh là:  $m=D_n.V=997.250.{10}^{-3}=249,25$  kg.<br>Xét sự trao đổi nhiệt giữa ethanol, nước (trong ống dẫn) với nước trong thùng nước lạnh, ta có:<br>$Q_{tỏa}=Q_{thu}$<br>$L_n.m_n+m_n.c_n.\\left(100-48\\right)+L_e.m_e+m_e.c_e.\\left(78-35\\right)=m.c_n.\\left(t-20\\right)$<br>$2,3.{10}^6.11,964+11,964.4200.52+0,9.{10}^6.6,312+6,312.2440.43=249,25.4200\\left(t-20\\right)$<br>$t\\approx 55 ℃$ .","difficultySource":"ai"},"ex":[{"exam":283,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":2,"options":["65 C.","60 C.\tC. 55","","80 C."],"question":"Quá trình nấu rượu gạo (dung dịch ethanol) thủ công được thực hiện như sau:<br>Gạo được nấu chín, để nguội, rắc men, ủ kín từ 3 đến 5 ngày thu được hỗn hợp chủ yếu gồm nước, ethanol và bã rượu.<br>Đun nóng hỗn hợp trên (trong nồi chưng cất) đến nhiệt độ sôi để ethanol và nước hóa hơi và đi vào đường ống dẫn. Hỗn hợp hơi (ethanol và nước) trong đường ống được làm lạnh sẽ hóa lỏng và chảy vào bình hứng. Ta có bảng giá trị của ethanol và nước như sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045413921-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhiệt độ sôi (C)\tKhối lượng riêng (kg/m3)\tNhiệt dung riêng (J/(kg.K))\tNhiệt hóa hơi riêng (J/kg)<br>Ethanol\t78\t789\t2 440\t0,9.106<br>Nước\t100\t997\t4 200\t2,3.10<sup>6</sup><br>Giả thuyết trong quá trình nấu rượu, hỗn hợp được cung cấp nhiệt một cách đều đặn. Ethanol sôi và hóa hơi trước ở 78 C. Sau đó đến 100 C thì nước bắt đầu sôi và hóa hơi. Bỏ qua lượng hơi nước ban đầu trong ống dẫn. Bỏ qua sự truyền nhiệt với môi trường, ống dẫn và bình hứng. Thùng nước lạnh chứa lượng nước có thể tích 250 lít ở nhiệt độ 20 C. Khi thu được 20 lít rượu gạo 40 (thể tích ethanol chiếm 40%), người ta đo nhiệt độ của rượu khi có cân bằng nhiệt là 45 C. Biết nhiệt độ của ethanol khi ra khỏi thùng nước lạnh là 35 C.<br>Trong quá trình nấu rượu, nước trong thùng nước lạnh không được thay. Nhiệt độ của nước trong thùng nước lạnh khi thu được 20 lít rượu gạo 40 là","difficulty":"kho","explanation":"Khối lượng nước chứa trong thùng nước lạnh là:  $m=D_n.V=997.250.{10}^{-3}=249,25$  kg.<br>Xét sự trao đổi nhiệt giữa ethanol, nước (trong ống dẫn) với nước trong thùng nước lạnh, ta có:<br>$Q_{tỏa}=Q_{thu}$<br>$L_n.m_n+m_n.c_n.\\left(100-48\\right)+L_e.m_e+m_e.c_e.\\left(78-35\\right)=m.c_n.\\left(t-20\\right)$<br>$2,3.{10}^6.11,964+11,964.4200.52+0,9.{10}^6.6,312+6,312.2440.43=249,25.4200\\left(t-20\\right)$<br>$t\\approx 55 ℃$ .","difficultySource":"ai"}}]},{"id":1480036,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2450","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất  $32%$ . Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  là 200 MeV. Nước làm mát hấp thụ nhiệt lượng dư từ lò phản ứng và được xả ra biển sau khi qua quá trình làm mát trong các hệ thống trao đổi nhiệt. Khối lượng mol của  ${}_{92}^{235}U$  là  $235 g/mol$ . Biết  $1eV=1,6.10^{−19} J$ . Khối lượng mol nguyên tử của  ${}_{92}^{235}U$  là  $235 g/mol$ .<br>Biết  $70%$  nhiệt lượng dư từ phân hạch được hấp thụ bởi nước làm mát. Nhà máy sẽ xả ra môi trường một lượng nhiệt dư bao nhiêu MW (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Phương pháp:<br>Công suất của nhiệt dư thừa từ phân hạch:  $P^/=\\frac{Q}{t}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Cách giải:<br>Nhiệt lượng dư thừa từ phân hạch:<br>Q = 70%E = 0,7.3,5.10<sup>9</sup> = 2,45.10<sup>9</sup>(J)<br>Nhà máy sẽ xả ra môi trường một lượng nhiệt dư với công suất là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P^/=\\frac{Q}{t}=\\frac{2,45.10^9}{1}$  = 2,49.10<sup>9</sup> (W) = 2450(MW)","difficultySource":"ai"},"ex":[{"exam":297,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2450","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất  $32%$ . Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  là 200 MeV. Nước làm mát hấp thụ nhiệt lượng dư từ lò phản ứng và được xả ra biển sau khi qua quá trình làm mát trong các hệ thống trao đổi nhiệt. Khối lượng mol của  ${}_{92}^{235}U$  là  $235 g/mol$ . Biết  $1eV=1,6.10^{−19} J$ . Khối lượng mol nguyên tử của  ${}_{92}^{235}U$  là  $235 g/mol$ .<br>Biết  $70%$  nhiệt lượng dư từ phân hạch được hấp thụ bởi nước làm mát. Nhà máy sẽ xả ra môi trường một lượng nhiệt dư bao nhiêu MW (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Phương pháp:<br>Công suất của nhiệt dư thừa từ phân hạch:  $P^/=\\frac{Q}{t}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Cách giải:<br>Nhiệt lượng dư thừa từ phân hạch:<br>Q = 70%E = 0,7.3,5.10<sup>9</sup> = 2,45.10<sup>9</sup>(J)<br>Nhà máy sẽ xả ra môi trường một lượng nhiệt dư với công suất là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P^/=\\frac{Q}{t}=\\frac{2,45.10^9}{1}$  = 2,49.10<sup>9</sup> (W) = 2450(MW)","difficultySource":"ai"}}]},{"id":1480169,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thang Celsius và thang Kelvin","answer":"34,3","question":"Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là  $3,0^∘C$ . Thể tích khí chứa trong mỗi lốp xe là  $1,50 m^3$  và áp suất khí trong các lốp xe là  $3,42.10^5 Pa$ . Đến giữa trưa, nhiệt độ tăng lên đến  $42,0^∘C$ , áp suất khí trong lốp bằng  $x.10^5 Pa$ . Coi khí trong lốp xe có nhiệt độ như ngoài trời và khí trong lốp không thoát ra ngoài, thể tích lốp không thay đổi.<br>Độ chênh lệch nhiệt độ lúc sáng sớm và giữa trưa trên sa mạc bằng bao nhiêu Kelvin?","difficulty":"trung-binh","explanation":"Phương pháp:<br>− Công suất trung bình của bức xạ mặt trời: P = I S.<br>− Năng lượng mà mặt trời cung cấp: A= Pt.<br>− Nhiệt lượng mà nước nhận để thay đổi nhiệt độ: Q = mc∆t.<br>Cách giải:<br>Công suất trung bình của bức xạ mặt trời là:<br>P = I S. = 675.2,94 = 1984,5(W)<br>Năng lượng mặt trời cung cấp trong 8h là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>A = P.t = 1984,5.8.60.60 = 57153,6.10<sup>3</sup>(J)<br>Nhiệt lượng dùng để làm nóng nước:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q = HA = 0,35.57153,6.10<sup>3</sup> = 20003,76.10<sup>3</sup>(J)<br>Với m = VD = 140.10−3.997 = 139,58(kg)<br>Lại có: Q = mc∆t = 20003,76.10<sup>3</sup> = 139,58.4180.∆t<br>$\\Rightarrow \\Delta t\\approx$  34,30C<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là  $3,0^∘C$ . Thể tích khí chứa trong mỗi lốp xe là  $1,50 m^3$  và áp suất khí trong các lốp xe là  $3,42.10^5 Pa$ . Đến giữa trưa, nhiệt độ tăng lên đến  $42,0^∘C$ , áp suất khí trong lốp bằng  $x.10^5 Pa$ . Coi khí trong lốp xe có nhiệt độ như ngoài trời và khí trong lốp không thoát ra ngoài, thể tích lốp không thay đổi.","difficultySource":"ai"},"ex":[{"exam":302,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Thang Celsius và thang Kelvin","answer":"34,3","question":"Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là  $3,0^∘C$ . Thể tích khí chứa trong mỗi lốp xe là  $1,50 m^3$  và áp suất khí trong các lốp xe là  $3,42.10^5 Pa$ . Đến giữa trưa, nhiệt độ tăng lên đến  $42,0^∘C$ , áp suất khí trong lốp bằng  $x.10^5 Pa$ . Coi khí trong lốp xe có nhiệt độ như ngoài trời và khí trong lốp không thoát ra ngoài, thể tích lốp không thay đổi.<br>Độ chênh lệch nhiệt độ lúc sáng sớm và giữa trưa trên sa mạc bằng bao nhiêu Kelvin?","difficulty":"trung-binh","explanation":"Phương pháp:<br>− Công suất trung bình của bức xạ mặt trời: P = I S.<br>− Năng lượng mà mặt trời cung cấp: A= Pt.<br>− Nhiệt lượng mà nước nhận để thay đổi nhiệt độ: Q = mc∆t.<br>Cách giải:<br>Công suất trung bình của bức xạ mặt trời là:<br>P = I S. = 675.2,94 = 1984,5(W)<br>Năng lượng mặt trời cung cấp trong 8h là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>A = P.t = 1984,5.8.60.60 = 57153,6.10<sup>3</sup>(J)<br>Nhiệt lượng dùng để làm nóng nước:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Q = HA = 0,35.57153,6.10<sup>3</sup> = 20003,76.10<sup>3</sup>(J)<br>Với m = VD = 140.10−3.997 = 139,58(kg)<br>Lại có: Q = mc∆t = 20003,76.10<sup>3</sup> = 139,58.4180.∆t<br>$\\Rightarrow \\Delta t\\approx$  34,30C<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Một chiếc xe tải vượt qua sa mạc Sahara. Chuyến đi bắt đầu vào sáng sớm khi nhiệt độ là  $3,0^∘C$ . Thể tích khí chứa trong mỗi lốp xe là  $1,50 m^3$  và áp suất khí trong các lốp xe là  $3,42.10^5 Pa$ . Đến giữa trưa, nhiệt độ tăng lên đến  $42,0^∘C$ , áp suất khí trong lốp bằng  $x.10^5 Pa$ . Coi khí trong lốp xe có nhiệt độ như ngoài trời và khí trong lốp không thoát ra ngoài, thể tích lốp không thay đổi.","difficultySource":"ai"}}]},{"id":1480183,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["5.10<sup>4</sup> Wb.","3.10<sup>4</sup> Wb.","5 mWb.","3 mWb."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 30 cm2 được đặt trong một từ trường đều có độ lớn cảm ứng từ bằng 0,2 T sao cho mặt phẳng vòng dây hợp với vector cảm ứng từ một góc 30.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403048-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:161.1px;height:auto\" /><br>Từ thông xuyên qua diện tích vòng dây có độ lớn bằng","difficulty":"de","explanation":"Từ thông xuyên qua diện tích vòng dây là:<br>$=NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)=1.0,2.30.{10}^{-4}.\\cos\\left(\\left(90^{\\circ}-30^{\\circ}\\right)\\right)=3.{10}^{-4} Wb=0,3 mWb$ .","difficultySource":"ai"},"ex":[{"exam":305,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":1,"options":["5.10<sup>4</sup> Wb.","3.10<sup>4</sup> Wb.","5 mWb.","3 mWb."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 30 cm2 được đặt trong một từ trường đều có độ lớn cảm ứng từ bằng 0,2 T sao cho mặt phẳng vòng dây hợp với vector cảm ứng từ một góc 30.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403048-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:161.1px;height:auto\" /><br>Từ thông xuyên qua diện tích vòng dây có độ lớn bằng","difficulty":"de","explanation":"Từ thông xuyên qua diện tích vòng dây là:<br>$=NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)=1.0,2.30.{10}^{-4}.\\cos\\left(\\left(90^{\\circ}-30^{\\circ}\\right)\\right)=3.{10}^{-4} Wb=0,3 mWb$ .","difficultySource":"ai"}}]},{"id":1480191,"nq":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Một ống dây dẫn hình trụ dài gồm 1 000 vòng dây, mỗi vòng có đường kính 10 cm, được đặt trong vùng EFGH có từ trường đều có các đường sức từ song song với trục của ống dây và độ lớn của cảm ứng từ tăng đều theo thời gian với quy luật  $\\frac{\\Delta B}{\\Delta t}=0,01$  T/s và độ lớn cảm ứng từ tại thời điểm t = 0 bằng 0 T. Cho biết dây dẫn có tiết diện 0,4 mm2 và có điện trở suất 1,75.10<sup>8</sup> (.m). Một tụ điện có điện dung 10 F được mắc vào mạch điện như hình vẽ. Ban đầu tụ điện chưa có năng lượng. Bỏ qua điện trở của các dây nối.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403364-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:253.8px;height:auto\" />","difficulty":"kho","statements":[{"text":"Từ thông xuyên qua tiết diện của ống dây tại thời điểm t là  $\\left(t\\right)=0,025\\pi t$  (Wb).","answer":true},{"text":"Suất điện động cảm ứng xuất hiện trong ống dây có độ lớn bằng  $0,025\\pi$  (V).","answer":true},{"text":"Khi chấu 0 thông với chấu 1 thì công suất tỏa nhiệt trong ống dây dẫn xấp xỉ bằng 8,8 W.","answer":true},{"text":"Khi chấu 0 thông với chấu 2 thì năng lượng mà tụ điện tích được xấp xỉ bằng  $3,1.{10}^{-8}$  J.","answer":true}],"explanation":"a) đúng<br>Từ thông xuyên qua tiết diện của ống dây tại thời điểm t là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left(t\\right)=NS\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right).\\left(B_0+0,01.\\Delta t\\right)=1000.\\pi \\frac{{0,1}^2}{4}.\\cos\\left(0^{\\circ}\\right).\\left(0+0,01.t\\right)=0,025\\pi t$  (Wb).<br>b) đúng<br>Suất điện động cảm ứng xuất hiện trong ống dây có độ lớn bằng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{NS\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right).\\Delta B}{\\Delta t}\\right|=\\left|-1000.\\pi \\frac{{0,1}^2}{4}.\\cos\\left(0^{\\circ}\\right).0,01\\right|=0,025\\pi$  (V).<br>c) đúng<br>Điện trở của ống dây dẫn:  $R=\\rho .\\frac{l}{S}=\\rho .\\frac{N.\\pi d}{\\pi \\frac{d^2}{4}}=\\frac{4\\rho N}{d}=\\frac{4.1,75.{10}^{-8}.1000}{0,1}=7.{10}^{-4}$  .<br>Khi chấu 0 thông với chấu 1 thì công suất tỏa nhiệt trong ống dây dẫn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P={i_c}^2.R={\\left(\\frac{e_c}{R}\\right)}^2.R=\\frac{{e_c}^2}{R}=\\frac{{\\left(0,025\\pi \\right)}^2}{7.{10}^{-4}}\\approx 8,8 W$ .<br>d) đúng<br>Khi chấu 0 thông với chấu 2 thì tụ điện được tích điện.<br>Năng lượng mà tụ điện tích được là:<br>$W=\\frac{1}{2}.C.{e_c}^2=\\frac{1}{2}.10.{10}^{-6}.{\\left(0,025\\pi \\right)}^2\\approx 3,1.{10}^{-8}$  (J).","difficultySource":"ai"},"ex":[{"exam":305,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Một ống dây dẫn hình trụ dài gồm 1 000 vòng dây, mỗi vòng có đường kính 10 cm, được đặt trong vùng EFGH có từ trường đều có các đường sức từ song song với trục của ống dây và độ lớn của cảm ứng từ tăng đều theo thời gian với quy luật  $\\frac{\\Delta B}{\\Delta t}=0,01$  T/s và độ lớn cảm ứng từ tại thời điểm t = 0 bằng 0 T. Cho biết dây dẫn có tiết diện 0,4 mm2 và có điện trở suất 1,75.10<sup>8</sup> (.m). Một tụ điện có điện dung 10 F được mắc vào mạch điện như hình vẽ. Ban đầu tụ điện chưa có năng lượng. Bỏ qua điện trở của các dây nối.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403364-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:253.8px;height:auto\" />","difficulty":"kho","statements":[{"text":"Từ thông xuyên qua tiết diện của ống dây tại thời điểm t là  $\\left(t\\right)=0,025\\pi t$  (Wb).","answer":true},{"text":"Suất điện động cảm ứng xuất hiện trong ống dây có độ lớn bằng  $0,025\\pi$  (V).","answer":true},{"text":"Khi chấu 0 thông với chấu 1 thì công suất tỏa nhiệt trong ống dây dẫn xấp xỉ bằng 8,8 W.","answer":true},{"text":"Khi chấu 0 thông với chấu 2 thì năng lượng mà tụ điện tích được xấp xỉ bằng  $3,1.{10}^{-8}$  J.","answer":true}],"explanation":"a) đúng<br>Từ thông xuyên qua tiết diện của ống dây tại thời điểm t là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left(t\\right)=NS\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right).\\left(B_0+0,01.\\Delta t\\right)=1000.\\pi \\frac{{0,1}^2}{4}.\\cos\\left(0^{\\circ}\\right).\\left(0+0,01.t\\right)=0,025\\pi t$  (Wb).<br>b) đúng<br>Suất điện động cảm ứng xuất hiện trong ống dây có độ lớn bằng:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{NS\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right).\\Delta B}{\\Delta t}\\right|=\\left|-1000.\\pi \\frac{{0,1}^2}{4}.\\cos\\left(0^{\\circ}\\right).0,01\\right|=0,025\\pi$  (V).<br>c) đúng<br>Điện trở của ống dây dẫn:  $R=\\rho .\\frac{l}{S}=\\rho .\\frac{N.\\pi d}{\\pi \\frac{d^2}{4}}=\\frac{4\\rho N}{d}=\\frac{4.1,75.{10}^{-8}.1000}{0,1}=7.{10}^{-4}$  .<br>Khi chấu 0 thông với chấu 1 thì công suất tỏa nhiệt trong ống dây dẫn là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P={i_c}^2.R={\\left(\\frac{e_c}{R}\\right)}^2.R=\\frac{{e_c}^2}{R}=\\frac{{\\left(0,025\\pi \\right)}^2}{7.{10}^{-4}}\\approx 8,8 W$ .<br>d) đúng<br>Khi chấu 0 thông với chấu 2 thì tụ điện được tích điện.<br>Năng lượng mà tụ điện tích được là:<br>$W=\\frac{1}{2}.C.{e_c}^2=\\frac{1}{2}.10.{10}^{-6}.{\\left(0,025\\pi \\right)}^2\\approx 3,1.{10}^{-8}$  (J).","difficultySource":"ai"}}]},{"id":1480192,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồ thị trong hình bên biểu diễn sự thay đổi độ phóng xạ của một mẫu chất phóng xạ + theo thời gian. Ban đầu (tại thời điểm  $t=0$  s) mẫu chất phóng xạ này nguyên chất.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403575-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:207px;height:auto\" />","difficulty":"kho","statements":[{"text":"Chu kì bán rã của chất phóng xạ này là 1,8 giờ.","answer":true},{"text":"Tại thời điểm  $t=0$  s, số hạt nhân có chứa trong mẫu chất phóng xạ đó xấp xỉ bằng 2,08.10<sup>5</sup> hạt nhân.","answer":false},{"text":"Trong 3,6 giờ đầu, mẫu chất phóng xạ đó đã phát ra 1,56.10<sup>5</sup> hạt positron.","answer":false},{"text":"Kể từ thời điểm ban đầu, số hạt nhân chất phóng xạ còn lại trong mẫu sau 9 giờ bằng 1/64 số hạt nhân chất phóng xạ ban đầu.","answer":false}],"explanation":"a) đúng<br>Dựa vào đồ thị ta xác định được khoảng thời gian để độ phóng xạ của mẫu chất giảm đi một nửa (hay một nửa số hạt nhân của mẫu phóng xạ phân rã) là 1,8 giờ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Vậy chu kì bán rã của chất phóng xạ này là 1,8 giờ.<br>b) sai<br>Tại thời điểm  $t=0$  s, số hạt nhân có chứa trong mẫu chất phóng xạ đó:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=N_0=\\frac{\\ln\\left(2\\right)}{T}.N_0$    $N_0=\\frac{T.H_0}{\\ln\\left(2\\right)}=\\frac{1,8.3600.80.{10}^3}{\\ln\\left(2\\right)}\\approx 7,48.{10}^8$  hạt nhân.<br>c) sai<br>Số hạt positron được phát ra bằng số hạt nhân của mẫu chất phóng xạ đã phân rã. Trong 3,6 giờ đầu, số hạt positron đã được mẫu chất phóng xạ đó phát ra là:<br>$\\Delta N=N_0\\left(1-2^{-\\frac{t_1}{T}}\\right)=\\frac{T.H_0}{\\ln\\left(2\\right)}.\\left(1-2^{-\\frac{t_1}{T}}\\right)=\\frac{1,8.3600.80.{10}^3}{\\ln\\left(2\\right)}.\\left(1-2^{-\\frac{3,6}{1,8}}\\right)\\approx 5,6.{10}^8$  hạt positron.<br>d) sai<br>Sau 9 giờ kể từ thời điểm ban đầu, ta có:<br>$\\frac{N_t}{N_0}=2^{-\\frac{t_2}{T}}=2^{-\\frac{9}{1,8}}=\\frac{1}{32}$    $N_t=\\frac{1}{32}N_0$","difficultySource":"ai"},"ex":[{"exam":305,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Đồ thị trong hình bên biểu diễn sự thay đổi độ phóng xạ của một mẫu chất phóng xạ + theo thời gian. Ban đầu (tại thời điểm  $t=0$  s) mẫu chất phóng xạ này nguyên chất.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224403575-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:207px;height:auto\" />","difficulty":"kho","statements":[{"text":"Chu kì bán rã của chất phóng xạ này là 1,8 giờ.","answer":true},{"text":"Tại thời điểm  $t=0$  s, số hạt nhân có chứa trong mẫu chất phóng xạ đó xấp xỉ bằng 2,08.10<sup>5</sup> hạt nhân.","answer":false},{"text":"Trong 3,6 giờ đầu, mẫu chất phóng xạ đó đã phát ra 1,56.10<sup>5</sup> hạt positron.","answer":false},{"text":"Kể từ thời điểm ban đầu, số hạt nhân chất phóng xạ còn lại trong mẫu sau 9 giờ bằng 1/64 số hạt nhân chất phóng xạ ban đầu.","answer":false}],"explanation":"a) đúng<br>Dựa vào đồ thị ta xác định được khoảng thời gian để độ phóng xạ của mẫu chất giảm đi một nửa (hay một nửa số hạt nhân của mẫu phóng xạ phân rã) là 1,8 giờ.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Vậy chu kì bán rã của chất phóng xạ này là 1,8 giờ.<br>b) sai<br>Tại thời điểm  $t=0$  s, số hạt nhân có chứa trong mẫu chất phóng xạ đó:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$H_0=N_0=\\frac{\\ln\\left(2\\right)}{T}.N_0$    $N_0=\\frac{T.H_0}{\\ln\\left(2\\right)}=\\frac{1,8.3600.80.{10}^3}{\\ln\\left(2\\right)}\\approx 7,48.{10}^8$  hạt nhân.<br>c) sai<br>Số hạt positron được phát ra bằng số hạt nhân của mẫu chất phóng xạ đã phân rã. Trong 3,6 giờ đầu, số hạt positron đã được mẫu chất phóng xạ đó phát ra là:<br>$\\Delta N=N_0\\left(1-2^{-\\frac{t_1}{T}}\\right)=\\frac{T.H_0}{\\ln\\left(2\\right)}.\\left(1-2^{-\\frac{t_1}{T}}\\right)=\\frac{1,8.3600.80.{10}^3}{\\ln\\left(2\\right)}.\\left(1-2^{-\\frac{3,6}{1,8}}\\right)\\approx 5,6.{10}^8$  hạt positron.<br>d) sai<br>Sau 9 giờ kể từ thời điểm ban đầu, ta có:<br>$\\frac{N_t}{N_0}=2^{-\\frac{t_2}{T}}=2^{-\\frac{9}{1,8}}=\\frac{1}{32}$    $N_t=\\frac{1}{32}N_0$","difficultySource":"ai"}}]},{"id":1480246,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một lượng nước đá đựng trong nhiệt lượng kế từ 0°C đến khi tan thành nước và hóa hơi ở 100°C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc hóa hơi và sự thay đổi nhiệt độ của nó. Biết nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg, nhiệt hóa hơi của nước là 2,3.10<sup>6</sup> J/kg, bỏ qua nhiệt dung của nhiệt lượng kế.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224405030-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:214px;height:auto\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cung cấp cho quá trình hóa hơi của nước là 121 kJ.","answer":false},{"text":"Từ khi nước đá nóng chảy hoàn toàn đến khi nước bắt đầu sôi, nước đã nhận nhiệt lượng 42 kJ.","answer":true},{"text":"Khối lượng của nước đá ban đầu là 80 g.","answer":false},{"text":"Đoạn BC cho biết lượng nước đã hóa hơi là 20 g.","answer":true}],"explanation":"a) sai<br>$BC\\rightarrow 121−75=46\\left(kJ\\right)$<br>b) đúng<br>$AB\\rightarrow 75−33=42kJ$<br>c) sai<br>$OA\\rightarrow 33.10^3=m.\\left(3,3.10^5\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=0,1kg=100g$<br>d) đúng<br>$46.10^3=m^/.2,3.10^6\\Rightarrow m^/=0,02kg=20g$","difficultySource":"ai"},"ex":[{"exam":309,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một lượng nước đá đựng trong nhiệt lượng kế từ 0°C đến khi tan thành nước và hóa hơi ở 100°C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc hóa hơi và sự thay đổi nhiệt độ của nó. Biết nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup> J/kg, nhiệt hóa hơi của nước là 2,3.10<sup>6</sup> J/kg, bỏ qua nhiệt dung của nhiệt lượng kế.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224405030-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:214px;height:auto\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng cung cấp cho quá trình hóa hơi của nước là 121 kJ.","answer":false},{"text":"Từ khi nước đá nóng chảy hoàn toàn đến khi nước bắt đầu sôi, nước đã nhận nhiệt lượng 42 kJ.","answer":true},{"text":"Khối lượng của nước đá ban đầu là 80 g.","answer":false},{"text":"Đoạn BC cho biết lượng nước đã hóa hơi là 20 g.","answer":true}],"explanation":"a) sai<br>$BC\\rightarrow 121−75=46\\left(kJ\\right)$<br>b) đúng<br>$AB\\rightarrow 75−33=42kJ$<br>c) sai<br>$OA\\rightarrow 33.10^3=m.\\left(3,3.10^5\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow m=0,1kg=100g$<br>d) đúng<br>$46.10^3=m^/.2,3.10^6\\Rightarrow m^/=0,02kg=20g$","difficultySource":"ai"}}]},{"id":1480250,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"14,7","question":"Vào mùa hè, một số người thường có thói quen uống trà đá. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,05kg nước trà nóng ở 800C vào cốc, sau đó cho tiếp m (g) đá viên ở 00C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 100C. Biết nhiệt dung riêng của nước là 4,2 kJ/kg.K; nhiệt nóng chảy riêng của nước đá là 3,33.10<sup>5</sup> J/kg.<br>Tính nhiệt lượng do nước trà tỏa ra để hạ nhiệt độ từ 800C xuống 100C. (Kết quả được tính theo đơn vị kJ và làm tròn đến chữ số hàng phần mười).","difficulty":"de","explanation":"$Q_{toa}=mc\\Delta t=0,05.4200.70=14,7\\left(kJ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":309,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"14,7","question":"Vào mùa hè, một số người thường có thói quen uống trà đá. Để có một cốc trà đá chất lượng, người chủ quán rót khoảng 0,05kg nước trà nóng ở 800C vào cốc, sau đó cho tiếp m (g) đá viên ở 00C. Cuối cùng được cốc trà đá ở nhiệt độ phù hợp nhất là 100C. Biết nhiệt dung riêng của nước là 4,2 kJ/kg.K; nhiệt nóng chảy riêng của nước đá là 3,33.10<sup>5</sup> J/kg.<br>Tính nhiệt lượng do nước trà tỏa ra để hạ nhiệt độ từ 800C xuống 100C. (Kết quả được tính theo đơn vị kJ và làm tròn đến chữ số hàng phần mười).","difficulty":"de","explanation":"$Q_{toa}=mc\\Delta t=0,05.4200.70=14,7\\left(kJ\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1480280,"nq":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"11","question":"Một tàu ngầm được dùng để nghiên cứu biển đang lặn ở độ sâu 100 m. Để tàu nổi lên, người ta mở một bình chứa khí có dung tích 50,0 lít, khí ở áp suất 1,00.10<sup>7</sup> Pa và nhiệt độ 270C để đẩy nước ra khỏi khoang chứa nước ở giữa hai lớp vỏ của tàu. Sau khi giãn nở, nhiệt độ của khí là 50C. Coi khối lượng riêng của nước biển là 1020 kg/m3; gia tốc trọng trường là 9,81 $m/s^2$; áp suất khí quyển là 1,01.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706398-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khí sau khi giãn nở là x.10<sup>5</sup> Pa. Giá trị của x là bao nhiêu (lấy 3 chữ số có nghĩa)?","difficulty":"trung-binh","explanation":"Áp suất của khí sau khi giãn nở là:<br>$P=Dgh+P_a=1020.9,81.100+1,01.10^5=1101620\\left(Pa\\right)\\approx 11,0.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":311,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"11","question":"Một tàu ngầm được dùng để nghiên cứu biển đang lặn ở độ sâu 100 m. Để tàu nổi lên, người ta mở một bình chứa khí có dung tích 50,0 lít, khí ở áp suất 1,00.10<sup>7</sup> Pa và nhiệt độ 270C để đẩy nước ra khỏi khoang chứa nước ở giữa hai lớp vỏ của tàu. Sau khi giãn nở, nhiệt độ của khí là 50C. Coi khối lượng riêng của nước biển là 1020 kg/m3; gia tốc trọng trường là 9,81 m/s2; áp suất khí quyển là 1,01.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706398-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khí sau khi giãn nở là x.10<sup>5</sup> Pa. Giá trị của x là bao nhiêu (lấy 3 chữ số có nghĩa)?","difficulty":"trung-binh","explanation":"Áp suất của khí sau khi giãn nở là:<br>$P=Dgh+P_a=1020.9,81.100+1,01.10^5=1101620\\left(Pa\\right)\\approx 11,0.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1480281,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"371","question":"Một tàu ngầm được dùng để nghiên cứu biển đang lặn ở độ sâu 100 m. Để tàu nổi lên, người ta mở một bình chứa khí có dung tích 50,0 lít, khí ở áp suất 1,00.10<sup>7</sup> Pa và nhiệt độ 270C để đẩy nước ra khỏi khoang chứa nước ở giữa hai lớp vỏ của tàu. Sau khi giãn nở, nhiệt độ của khí là 50C. Coi khối lượng riêng của nước biển là 1020 kg/m3; gia tốc trọng trường là 9,81 $m/s^2$; áp suất khí quyển là 1,01.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706398-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Thể tích của lượng nước bị đẩy ra khỏi tàu là bao nhiêu lít (lấy 3 chữ số có nghĩa)?","difficulty":"trung-binh","explanation":"Áp dụng phương trình trạng thái ta có:<br>$\\begin{aligned}\\end{aligned}\\frac{P_1V_1}{T_1}=\\frac{P_2V_2}{T_2}\\Rightarrow V_2=\\frac{P_1V_1}{T_1}.\\frac{T_2}{P_2}=\\frac{1,00.10^7.50}{\\left(27+273\\right)}.\\frac{\\left(5+273\\right)}{11,0.10^5}=421,2\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lượng nước bị đẩy khỏi tàu là:<br>$V=V_2−V_1=421,2−50=371,2\\left(lit\\right)\\approx 371\\left(lit\\right)$","difficultySource":"ai"},"ex":[{"exam":311,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"371","question":"Một tàu ngầm được dùng để nghiên cứu biển đang lặn ở độ sâu 100 m. Để tàu nổi lên, người ta mở một bình chứa khí có dung tích 50,0 lít, khí ở áp suất 1,00.10<sup>7</sup> Pa và nhiệt độ 270C để đẩy nước ra khỏi khoang chứa nước ở giữa hai lớp vỏ của tàu. Sau khi giãn nở, nhiệt độ của khí là 50C. Coi khối lượng riêng của nước biển là 1020 kg/m3; gia tốc trọng trường là 9,81 m/s2; áp suất khí quyển là 1,01.10<sup>5</sup> Pa.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045706398-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Thể tích của lượng nước bị đẩy ra khỏi tàu là bao nhiêu lít (lấy 3 chữ số có nghĩa)?","difficulty":"trung-binh","explanation":"Áp dụng phương trình trạng thái ta có:<br>$\\begin{aligned}\\end{aligned}\\frac{P_1V_1}{T_1}=\\frac{P_2V_2}{T_2}\\Rightarrow V_2=\\frac{P_1V_1}{T_1}.\\frac{T_2}{P_2}=\\frac{1,00.10^7.50}{\\left(27+273\\right)}.\\frac{\\left(5+273\\right)}{11,0.10^5}=421,2\\left(lit\\right)Website: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Lượng nước bị đẩy khỏi tàu là:<br>$V=V_2−V_1=421,2−50=371,2\\left(lit\\right)\\approx 371\\left(lit\\right)$","difficultySource":"ai"}}]},{"id":1480400,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":2,"options":["2.10<sup>−2</sup> N.","4.102 Ν.","4.10<sup>−4</sup> N.","0 N."],"question":"Tại một nơi có từ trường Trái Đất nằm ngang (độ lớn cảm ứng từ 40 μT), đặt một đoạn dây dẫn dài 10 m có dòng điện 1 A theo phương vuông góc với đường sức từ.<br>Lực từ do từ trường Trái Đất tác dụng lên đoạn dây có độ lớn là","difficulty":"de","explanation":"Vì đoạn dây vuông góc với đường sức từ (sinα=1), độ lớn lực từ: F = B·I·ℓ.<br>Thay số: F = 40×10⁻⁶·1·10 = 4×10⁻⁴ N.<br>$F=ILB=1\\cdot 10\\cdot 40\\cdot 10^{−6}=4\\cdot 10^{−4} N.$","difficultySource":"ai"},"ex":[{"exam":319,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":2,"options":["2.10<sup>−2</sup> N.","4.102 Ν.","4.10<sup>−4</sup> N.","0 N."],"question":"Tại một nơi có từ trường Trái Đất nằm ngang (độ lớn cảm ứng từ 40 μT), đặt một đoạn dây dẫn dài 10 m có dòng điện 1 A theo phương vuông góc với đường sức từ.<br>Lực từ do từ trường Trái Đất tác dụng lên đoạn dây có độ lớn là","difficulty":"de","explanation":"Vì đoạn dây vuông góc với đường sức từ (sinα=1), độ lớn lực từ: F = B·I·ℓ.<br>Thay số: F = 40×10⁻⁶·1·10 = 4×10⁻⁴ N.<br>$F=ILB=1\\cdot 10\\cdot 40\\cdot 10^{−6}=4\\cdot 10^{−4} N.$","difficultySource":"ai"}}]},{"id":1480517,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện trở và đơn vị đo","answer":2,"options":["0,61.","2,65.","1,63.","0,38."],"question":"<br>Kim loại\tĐiện trở suất ở 200C (Ωm)<br>Bạc\t1,62.10<sup>−8</sup><br>Đồng\t1,69.10<sup>−8</sup><br>Vàng\t2,44.10<sup>−8</sup><br>Nhôm\t2,75.10<sup>−8</sup><br>Sắt\t9,68.10<sup>−8</sup><br>Một dây dẫn hình trụ bằng Đồng và một dây dẫn hình trụ bằng Nhôm có cùng kích thước. Nếu đặt vào hai đầu mỗi dây cùng một hiệu điện thế thì tỷ số giữa công suất toả nhiệt trên dây Đồng và công suất toả nhiệt trên dây Nhôm xấp xỉ bằng","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}P=\\frac{U}{R}\\Rightarrow \\frac{P_{Cu}}{P_{Al}}=\\frac{R_{Al}}{R_{Cu}}=\\frac{\\delta_{Al}ℓS}{\\delta_{Cu}ℓS}=\\frac{2,75}{1,69}\\approx 1,63Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":329,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện trở và đơn vị đo","answer":2,"options":["0,61.","2,65.","1,63.","0,38."],"question":"<br>Kim loại\tĐiện trở suất ở 200C (Ωm)<br>Bạc\t1,62.10<sup>−8</sup><br>Đồng\t1,69.10<sup>−8</sup><br>Vàng\t2,44.10<sup>−8</sup><br>Nhôm\t2,75.10<sup>−8</sup><br>Sắt\t9,68.10<sup>−8</sup><br>Một dây dẫn hình trụ bằng Đồng và một dây dẫn hình trụ bằng Nhôm có cùng kích thước. Nếu đặt vào hai đầu mỗi dây cùng một hiệu điện thế thì tỷ số giữa công suất toả nhiệt trên dây Đồng và công suất toả nhiệt trên dây Nhôm xấp xỉ bằng","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}P=\\frac{U}{R}\\Rightarrow \\frac{P_{Cu}}{P_{Al}}=\\frac{R_{Al}}{R_{Cu}}=\\frac{\\delta_{Al}ℓS}{\\delta_{Cu}ℓS}=\\frac{2,75}{1,69}\\approx 1,63Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1480518,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện trở và đơn vị đo","answer":3,"options":["Dây dẫn bằng Cu.","Dây dẫn bằng Al.","Dây dẫn bằng Fe.","Dây dẫn bằng Ag."],"question":"<br>Kim loại\tĐiện trở suất ở 200C (Ωm)<br>Bạc\t1,62.10<sup>−8</sup><br>Đồng\t1,69.10<sup>−8</sup><br>Vàng\t2,44.10<sup>−8</sup><br>Nhôm\t2,75.10<sup>−8</sup><br>Sắt\t9,68.10<sup>−8</sup><br>Bốn vật dẫn hình trụ có cùng kích thước được chế tạo bằng Bạc (Ag), Đồng (Cu), Nhôm (Al), Sắt (Fe). Lần lượt nối vào hai đầu mỗi vật dẫn cùng một nguồn điện có suất điện động không đổi thì dòng điện chạy trong dây dẫn nào có cường độ lớn nhất?","difficulty":"de","explanation":"Bạc là kim loại dẫn điện rất tốt, điện trở của nó nhỏ tức là cản trở dòng điện đi vào là ít<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":329,"idx":16,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện trở và đơn vị đo","answer":3,"options":["Dây dẫn bằng Cu.","Dây dẫn bằng Al.","Dây dẫn bằng Fe.","Dây dẫn bằng Ag."],"question":"<br>Kim loại\tĐiện trở suất ở 200C (Ωm)<br>Bạc\t1,62.10<sup>−8</sup><br>Đồng\t1,69.10<sup>−8</sup><br>Vàng\t2,44.10<sup>−8</sup><br>Nhôm\t2,75.10<sup>−8</sup><br>Sắt\t9,68.10<sup>−8</sup><br>Bốn vật dẫn hình trụ có cùng kích thước được chế tạo bằng Bạc (Ag), Đồng (Cu), Nhôm (Al), Sắt (Fe). Lần lượt nối vào hai đầu mỗi vật dẫn cùng một nguồn điện có suất điện động không đổi thì dòng điện chạy trong dây dẫn nào có cường độ lớn nhất?","difficulty":"de","explanation":"Bạc là kim loại dẫn điện rất tốt, điện trở của nó nhỏ tức là cản trở dòng điện đi vào là ít<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1480775,"nq":{"form":"bai_tap","type":"short_answer","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":"150","question":"Một dây dẫn thẳng nằm ngang truyền tải dòng điện xoay chiều từ một nhà máy nhiệt điện đến các khu vực xung quanh. Cường độ dòng điện hiệu dụng trong dây dẫn này là I = 106A . Thành phần nằm ngang của từ trường Trái Đất tại khu vực nhà máy nhiệt điện có độ lớn B = 4.10<sup>−5</sup> T và tạo với dây dẫn một góc sao cho lực từ đạt cực đại.<br>Cường độ dòng điện cực đại trong dây dẫn trên là bao nhiêu Ampe (Làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Với dòng điện xoay chiều hình sin: $I_0 = I\\sqrt{2}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $I_0 = 106\\sqrt{2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_0 \\approx 149{,}9\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_0 \\approx 150\\ \\text{A}$ (làm tròn đến hàng đơn vị).</p><p class=\"text-base leading-relaxed my-2\">Dữ kiện về từ trường Trái Đất không dùng cho câu hỏi này.</p>","difficultySource":"ai"},"ex":[{"exam":343,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":"150","question":"Một dây dẫn thẳng nằm ngang truyền tải dòng điện xoay chiều từ một nhà máy nhiệt điện đến các khu vực xung quanh. Cường độ dòng điện hiệu dụng trong dây dẫn này là I = 106A . Thành phần nằm ngang của từ trường Trái Đất tại khu vực nhà máy nhiệt điện có độ lớn B = 4.10<sup>−5</sup> T và tạo với dây dẫn một góc sao cho lực từ đạt cực đại.<br>Cường độ dòng điện cực đại trong dây dẫn trên là bao nhiêu Ampe (Làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Với dòng điện xoay chiều hình sin: $I_0 = I\\sqrt{2}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $I_0 = 106\\sqrt{2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_0 \\approx 149{,}9\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_0 \\approx 150\\ \\text{A}$ (làm tròn đến hàng đơn vị).</p><p class=\"text-base leading-relaxed my-2\">Dữ kiện về từ trường Trái Đất không dùng cho câu hỏi này.</p>","difficultySource":"ai"}}]},{"id":1480833,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"14,4","question":"Sơn tĩnh điện là một ứng dụng của lực tương tác tĩnh điện giữa hai điện tích. Các hạt bột sơn sẽ được nhiễm điện và phun vào bề mặt vật liệu sơn. Nhờ lực hút tĩnh điện, các hạt sơn này bám rất chặt trên bề mặt vật liệu. Bài toán sau đây minh họa cho tương tác tĩnh điện giữa hai điện tích trái dấu: Một vật A có điện tích Q = −8.10<sup>−6</sup>C được cố định tại một điểm trong chân không. Một vật B có khối lượng m =10 g, mang điện tích q = 8.10<sup>−6</sup>C được bắn trực diện vào vật A từ vị trí M cách A một đoạn 20 cm . Xem các vật như điện tích điểm; lấy k = 9.10<sup>9</sup> Nm2.C-2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046058842-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khi hai vật cách nhau 20 cm thì lực tương tác tĩnh điện giữa chúng có độ lớn bằng bao nhiêu N (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}F=k\\frac{\\left|Qq\\right|}{r^2}=9.10^9.\\frac{\\left|8.10^{−6}.8.10^{−6}\\right|}{0,2^2}=14,4NWebsite: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":345,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"14,4","question":"Sơn tĩnh điện là một ứng dụng của lực tương tác tĩnh điện giữa hai điện tích. Các hạt bột sơn sẽ được nhiễm điện và phun vào bề mặt vật liệu sơn. Nhờ lực hút tĩnh điện, các hạt sơn này bám rất chặt trên bề mặt vật liệu. Bài toán sau đây minh họa cho tương tác tĩnh điện giữa hai điện tích trái dấu: Một vật A có điện tích Q = −8.10<sup>−6</sup>C được cố định tại một điểm trong chân không. Một vật B có khối lượng m =10 g, mang điện tích q = 8.10<sup>−6</sup>C được bắn trực diện vào vật A từ vị trí M cách A một đoạn 20 cm . Xem các vật như điện tích điểm; lấy k = 9.10<sup>9</sup> Nm2.C-2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046058842-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Khi hai vật cách nhau 20 cm thì lực tương tác tĩnh điện giữa chúng có độ lớn bằng bao nhiêu N (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\begin{aligned}\\end{aligned}F=k\\frac{\\left|Qq\\right|}{r^2}=9.10^9.\\frac{\\left|8.10^{−6}.8.10^{−6}\\right|}{0,2^2}=14,4NWebsite: thukhoadaihoc.vn$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1480887,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"19","question":"Tại một trang trại điện gió ngoài khơi ven biển tỉnh Bạc Liêu, dòng điện được tạo ra từ máy phát trong tuabin gió được truyền qua dây dẫn ngầm dưới biển vào đất liền. Dòng điện mạnh truyền qua dây dẫn có thể tương tác với từ trường Trái Đất, gây ra một lực từ đáng kể lên dây. Các kỹ sư cần kiểm tra độ bền cơ học của dây dẫn và hiệu suất truyền tải điện năng để đảm bảo an toàn và tối ưu hóa hiệu suất. Một dây dẫn thẳng dài được bố trí ngầm dưới biển có dòng điện hiệu dụng truyền trên dây dẫn là I = 250 A từ một tuabin gió về trạm biến áp trên bờ. Thành phần nằm ngang của từ trường Trái<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046147232-hinh-21.jpg\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đất tại khu vực này có độ lớn B = 3,8.10<sup>−5</sup> T. Biết dây dẫn có chiều dài l = 2 km và đặt vuông góc với đường sức từ.<br>Độ lớn của lực từ do từ trường Trái Đất tác dụng lên toàn bộ dây dẫn bằng bao nhiêu N?","difficulty":"de","explanation":"Độ lớn của lực từ tác dụng lên toàn bộ dây dẫn:<br>$F=B.I.l.\\sin\\left(\\alpha \\right)={3,8.10}^{-5}\\times 250\\times 2000=19 N.$","difficultySource":"ai"},"ex":[{"exam":351,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"19","question":"Tại một trang trại điện gió ngoài khơi ven biển tỉnh Bạc Liêu, dòng điện được tạo ra từ máy phát trong tuabin gió được truyền qua dây dẫn ngầm dưới biển vào đất liền. Dòng điện mạnh truyền qua dây dẫn có thể tương tác với từ trường Trái Đất, gây ra một lực từ đáng kể lên dây. Các kỹ sư cần kiểm tra độ bền cơ học của dây dẫn và hiệu suất truyền tải điện năng để đảm bảo an toàn và tối ưu hóa hiệu suất. Một dây dẫn thẳng dài được bố trí ngầm dưới biển có dòng điện hiệu dụng truyền trên dây dẫn là I = 250 A từ một tuabin gió về trạm biến áp trên bờ. Thành phần nằm ngang của từ trường Trái<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046147232-hinh-21.jpg\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đất tại khu vực này có độ lớn B = 3,8.10<sup>−5</sup> T. Biết dây dẫn có chiều dài l = 2 km và đặt vuông góc với đường sức từ.<br>Độ lớn của lực từ do từ trường Trái Đất tác dụng lên toàn bộ dây dẫn bằng bao nhiêu N?","difficulty":"de","explanation":"Độ lớn của lực từ tác dụng lên toàn bộ dây dẫn:<br>$F=B.I.l.\\sin\\left(\\alpha \\right)={3,8.10}^{-5}\\times 250\\times 2000=19 N.$","difficultySource":"ai"}}]},{"id":1480888,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công, công suất và lực phát động (ôn tập lớp 10)","answer":"98,6","question":"Tại một trang trại điện gió ngoài khơi ven biển tỉnh Bạc Liêu, dòng điện được tạo ra từ máy phát trong tuabin gió được truyền qua dây dẫn ngầm dưới biển vào đất liền. Dòng điện mạnh truyền qua dây dẫn có thể tương tác với từ trường Trái Đất, gây ra một lực từ đáng kể lên dây. Các kỹ sư cần kiểm tra độ bền cơ học của dây dẫn và hiệu suất truyền tải điện năng để đảm bảo an toàn và tối ưu hóa hiệu suất. Một dây dẫn thẳng dài được bố trí ngầm dưới biển có dòng điện hiệu dụng truyền trên dây dẫn là I = 250 A từ một tuabin gió về trạm biến áp trên bờ. Thành phần nằm ngang của từ trường Trái<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046147232-hinh-21.jpg\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đất tại khu vực này có độ lớn B = 3,8.10<sup>−5</sup> T. Biết dây dẫn có chiều dài l = 2 km và đặt vuông góc với đường sức từ.<br>Giả sử dây dẫn được làm bằng nhôm, có điện trở suất  $\\rho ={2,65.10}^{-8}\\Omega .m,$  tiết diện dây là S = 150 mm2 và công suất điện của tuabin là 1,6 MW. Hiệu suất truyền tải điện năng trong trường hợp này bằng bao nhiêu phần trăm? (Làm tròn đến chữ số thập phân thứ nhất)","difficulty":"trung-binh","explanation":"Công suất hao phí trên dây dẫn:<br>$P_{hp}=RI^2=\\rho .\\frac{l}{S}.I^2=2,65.10^{-8}\\times \\frac{2000}{150.10^{-6}}\\times {250}^2=22083,3 W;$<br>Hiệu suất truyền tải điện năng:<br>$H=1-\\frac{P_{hp}}{P}=1-\\frac{22083,3}{{1,6.10}^6}\\approx 98,6%.$","difficultySource":"ai"},"ex":[{"exam":351,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Công, công suất và lực phát động (ôn tập lớp 10)","answer":"98,6","question":"Tại một trang trại điện gió ngoài khơi ven biển tỉnh Bạc Liêu, dòng điện được tạo ra từ máy phát trong tuabin gió được truyền qua dây dẫn ngầm dưới biển vào đất liền. Dòng điện mạnh truyền qua dây dẫn có thể tương tác với từ trường Trái Đất, gây ra một lực từ đáng kể lên dây. Các kỹ sư cần kiểm tra độ bền cơ học của dây dẫn và hiệu suất truyền tải điện năng để đảm bảo an toàn và tối ưu hóa hiệu suất. Một dây dẫn thẳng dài được bố trí ngầm dưới biển có dòng điện hiệu dụng truyền trên dây dẫn là I = 250 A từ một tuabin gió về trạm biến áp trên bờ. Thành phần nằm ngang của từ trường Trái<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046147232-hinh-21.jpg\" alt=\"Hình 21\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Đất tại khu vực này có độ lớn B = 3,8.10<sup>−5</sup> T. Biết dây dẫn có chiều dài l = 2 km và đặt vuông góc với đường sức từ.<br>Giả sử dây dẫn được làm bằng nhôm, có điện trở suất  $\\rho ={2,65.10}^{-8}\\Omega .m,$  tiết diện dây là S = 150 mm2 và công suất điện của tuabin là 1,6 MW. Hiệu suất truyền tải điện năng trong trường hợp này bằng bao nhiêu phần trăm? (Làm tròn đến chữ số thập phân thứ nhất)","difficulty":"trung-binh","explanation":"Công suất hao phí trên dây dẫn:<br>$P_{hp}=RI^2=\\rho .\\frac{l}{S}.I^2=2,65.10^{-8}\\times \\frac{2000}{150.10^{-6}}\\times {250}^2=22083,3 W;$<br>Hiệu suất truyền tải điện năng:<br>$H=1-\\frac{P_{hp}}{P}=1-\\frac{22083,3}{{1,6.10}^6}\\approx 98,6%.$","difficultySource":"ai"}}]},{"id":1480941,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"175","question":"Xilanh của một động cơ ô tô Camy 2.4 Q có dung tích là 2,4 dm3. Ở kỳ nạp, hỗn hợp khí được nạp vào dưới áp suất 1,5.10<sup>5</sup>Pa và nhiệt độ 470C. Đến cuối kỳ nén, píttông nén xuống tối đa làm cho thể tích của hỗn hợp khí giảm xuống chỉ còn 0,24 dm3 và áp suất tăng 14 lần so với ban đầu.<br>Nhiệt độ của hỗn hợp khí ở cuối kỳ nén  là bao nhiêu 0C (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=const\\Rightarrow \\frac{2,4}{47+273}=\\frac{14.0,24}{T}\\Rightarrow T=448K=175^0C$","difficultySource":"ai"},"ex":[{"exam":353,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"175","question":"Xilanh của một động cơ ô tô Camy 2.4 Q có dung tích là 2,4 dm3. Ở kỳ nạp, hỗn hợp khí được nạp vào dưới áp suất 1,5.10<sup>5</sup>Pa và nhiệt độ 470C. Đến cuối kỳ nén, píttông nén xuống tối đa làm cho thể tích của hỗn hợp khí giảm xuống chỉ còn 0,24 dm3 và áp suất tăng 14 lần so với ban đầu.<br>Nhiệt độ của hỗn hợp khí ở cuối kỳ nén  là bao nhiêu 0C (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$\\frac{pV}{T}=const\\Rightarrow \\frac{2,4}{47+273}=\\frac{14.0,24}{T}\\Rightarrow T=448K=175^0C$","difficultySource":"ai"}}]},{"id":1480971,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"3,2","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất 32%. Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  tỏa ra là 200 MeV . Khối lượng mol của  ${}_{92}^{235}U$ là 235 g / mol, biết 1eV =1,60.10<sup>−19</sup>J<br>Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$ tỏa ra là x.10<sup>−11</sup> J. Tính x . (kết quả làm tròn đến chữ số hàng phần chục).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị năng lượng phân hạch của một hạt nhân ${}_{92}^{235}U$ từ MeV sang J, với $1\\,\\text{eV} = 1{,}60\\cdot 10^{-19}\\,\\text{J}$:</p><p class=\"text-base leading-relaxed my-2\">$E = 200\\,\\text{MeV} = 200\\cdot 10^{6}\\cdot 1{,}60\\cdot 10^{-19}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E = 3{,}20\\cdot 10^{-11}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">So với dạng $x\\cdot 10^{-11}\\,\\text{J}$ thì $x = 3{,}2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $x = 3{,}2$.</p>","difficultySource":"ai"},"ex":[{"exam":354,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"3,2","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất 32%. Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  tỏa ra là 200 MeV . Khối lượng mol của  ${}_{92}^{235}U$ là 235 g / mol, biết 1eV =1,60.10<sup>−19</sup>J<br>Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$ tỏa ra là x.10<sup>−11</sup> J. Tính x . (kết quả làm tròn đến chữ số hàng phần chục).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị năng lượng phân hạch của một hạt nhân ${}_{92}^{235}U$ từ MeV sang J, với $1\\,\\text{eV} = 1{,}60\\cdot 10^{-19}\\,\\text{J}$:</p><p class=\"text-base leading-relaxed my-2\">$E = 200\\,\\text{MeV} = 200\\cdot 10^{6}\\cdot 1{,}60\\cdot 10^{-19}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E = 3{,}20\\cdot 10^{-11}\\,\\text{J}$</p><p class=\"text-base leading-relaxed my-2\">So với dạng $x\\cdot 10^{-11}\\,\\text{J}$ thì $x = 3{,}2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $x = 3{,}2$.</p>","difficultySource":"ai"}}]},{"id":1480972,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"5,4","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất 32%. Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  tỏa ra là 200 MeV . Khối lượng mol của  ${}_{92}^{235}U$ là 235 g / mol, biết 1eV =1,60.10<sup>−19</sup>J<br>Nhiên liệu là các thanh  ${}_{92}^{235}U$ đã làm giàu 25% ( tỉ lệ phần trăm khối lượng của  ${}_{92}^{235}U$ và khối lượng thanh là 25% ). Khối lượng nhiên liệu cần cho nhà máy Diablo Canyon hoạt động liên tục trong 1 năm (365 ngày) là bao nhiêu tấn (kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"$A=Pt=1120.10^6.365.24.60.60=3,532032.10^{16}J$<br>$Q=\\frac{A}{H}=\\frac{3,532032.10^{16}}{0,32}=1,10376.10^{17}J$<br>$\\begin{aligned}\\end{aligned}N=\\frac{Q}{\\Delta E}=\\frac{1,10376.10^{17}}{3,2.10^{−11}}=3,44925.10^{27}Website: thukhoadaihoc.vn$<br>$n=\\frac{N}{N_A}=\\frac{3,44925.10^{27}}{6,02.10^{23}}\\approx 5729,65 mol$<br>$m=n.M=5729,65.0,235=1346,46775kg$","difficultySource":"ai"},"ex":[{"exam":354,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"5,4","question":"Nhà máy điện hạt nhân Diablo Canyon ở California, Mỹ có công suất phát điện là 1120 MW với hiệu suất 32%. Năng lượng phân hạch trung bình của một hạt nhân  ${}_{92}^{235}U$  tỏa ra là 200 MeV . Khối lượng mol của  ${}_{92}^{235}U$ là 235 g / mol, biết 1eV =1,60.10<sup>−19</sup>J<br>Nhiên liệu là các thanh  ${}_{92}^{235}U$ đã làm giàu 25% ( tỉ lệ phần trăm khối lượng của  ${}_{92}^{235}U$ và khối lượng thanh là 25% ). Khối lượng nhiên liệu cần cho nhà máy Diablo Canyon hoạt động liên tục trong 1 năm (365 ngày) là bao nhiêu tấn (kết quả làm tròn đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"$A=Pt=1120.10^6.365.24.60.60=3,532032.10^{16}J$<br>$Q=\\frac{A}{H}=\\frac{3,532032.10^{16}}{0,32}=1,10376.10^{17}J$<br>$\\begin{aligned}\\end{aligned}N=\\frac{Q}{\\Delta E}=\\frac{1,10376.10^{17}}{3,2.10^{−11}}=3,44925.10^{27}Website: thukhoadaihoc.vn$<br>$n=\\frac{N}{N_A}=\\frac{3,44925.10^{27}}{6,02.10^{23}}\\approx 5729,65 mol$<br>$m=n.M=5729,65.0,235=1346,46775kg$","difficultySource":"ai"}}]},{"id":1481025,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2","question":"Nhà máy điện hạt nhân có công suất phát điện 205 MW. Cho rằng toàn bộ năng lượng mà lò phản ứng này sinh ra đều do sự phân hạch của uranium   ${}_{92}^{235}U$ với hiệu suất 32%. Biết mỗi phân hạch của đồng vị  ${}_{92}^{235}U$ tỏa năng lượng 201 MeV. Lấy 1eV = 1, 6.10<sup>−19</sup> J. Số Avogadro NA = 6,02.10<sup>23</sup> hạt /mol. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Trong mỗi giây, số nguyên tử  ${}_{92}^{235}U$ trong lò phản ứng đã phân hạch là x. 10<sup>19</sup> nguyên tử. Tìm x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$A=P.t=205.10^6J$<br>$Q=\\frac{A}{H}=\\frac{205.10^6}{0,32}=640,625.10^6J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}N_{ph}=\\frac{Q}{\\Delta E}=\\frac{640,625.10^6}{201.1,6.10^{−13}}\\approx 2.10^{19}Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":360,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2","question":"Nhà máy điện hạt nhân có công suất phát điện 205 MW. Cho rằng toàn bộ năng lượng mà lò phản ứng này sinh ra đều do sự phân hạch của uranium   ${}_{92}^{235}U$ với hiệu suất 32%. Biết mỗi phân hạch của đồng vị  ${}_{92}^{235}U$ tỏa năng lượng 201 MeV. Lấy 1eV = 1, 6.10<sup>−19</sup> J. Số Avogadro NA = 6,02.10<sup>23</sup> hạt /mol. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Trong mỗi giây, số nguyên tử  ${}_{92}^{235}U$ trong lò phản ứng đã phân hạch là x. 10<sup>19</sup> nguyên tử. Tìm x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"trung-binh","explanation":"$A=P.t=205.10^6J$<br>$Q=\\frac{A}{H}=\\frac{205.10^6}{0,32}=640,625.10^6J$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}N_{ph}=\\frac{Q}{\\Delta E}=\\frac{640,625.10^6}{201.1,6.10^{−13}}\\approx 2.10^{19}Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481026,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"91","question":"Nhà máy điện hạt nhân có công suất phát điện 205 MW. Cho rằng toàn bộ năng lượng mà lò phản ứng này sinh ra đều do sự phân hạch của uranium   ${}_{92}^{235}U$ với hiệu suất 32%. Biết mỗi phân hạch của đồng vị  ${}_{92}^{235}U$ tỏa năng lượng 201 MeV. Lấy 1eV = 1, 6.10<sup>−19</sup> J. Số Avogadro NA = 6,02.10<sup>23</sup> hạt /mol. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Biết chỉ có 89% số nguyên tử  ${}_{92}^{235}U$ phân hạch. Nhà máy điện hạt nhân này sẽ sử dụng hết 69 kg  23592 U trong bao nhiêu ngày (làm tròn kết quả đến chữ số hàng đơn vì)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{69.10^3}{235}=\\frac{13800}{47}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=\\frac{13800}{47}.6,02.10^{23}\\approx 1,77.10^{26}$<br>$\\begin{aligned}\\end{aligned}t=\\frac{0,89N}{N_{ph}}=\\frac{0,89.1,77.10^{26}}{2.10^{19}}\\approx 7,9.10^6s\\approx 91Website: thukhoadaihoc.vn$  ngày","difficultySource":"ai"},"ex":[{"exam":360,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"91","question":"Nhà máy điện hạt nhân có công suất phát điện 205 MW. Cho rằng toàn bộ năng lượng mà lò phản ứng này sinh ra đều do sự phân hạch của uranium   ${}_{92}^{235}U$ với hiệu suất 32%. Biết mỗi phân hạch của đồng vị  ${}_{92}^{235}U$ tỏa năng lượng 201 MeV. Lấy 1eV = 1, 6.10<sup>−19</sup> J. Số Avogadro NA = 6,02.10<sup>23</sup> hạt /mol. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Biết chỉ có 89% số nguyên tử  ${}_{92}^{235}U$ phân hạch. Nhà máy điện hạt nhân này sẽ sử dụng hết 69 kg  23592 U trong bao nhiêu ngày (làm tròn kết quả đến chữ số hàng đơn vì)?","difficulty":"kho","explanation":"$n=\\frac{m}{M}=\\frac{69.10^3}{235}=\\frac{13800}{47}mol$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$N=nN_A=\\frac{13800}{47}.6,02.10^{23}\\approx 1,77.10^{26}$<br>$\\begin{aligned}\\end{aligned}t=\\frac{0,89N}{N_{ph}}=\\frac{0,89.1,77.10^{26}}{2.10^{19}}\\approx 7,9.10^6s\\approx 91Website: thukhoadaihoc.vn$  ngày","difficultySource":"ai"}}]},{"id":1481107,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"208","question":"Tàu phá băng mang tên Rossiya là tàu phá băng  lớn nhất của nước Nga chạy bằng năng lượng hạt nhân. Tàu nặng 69.700 tấn, chiều dài 209,2 mét, chiều rộng 47,7 mét, sâu 18,7 mét, tốc độ 23 hải lý/giờ, tàu được trang bị hai lò phản ứng RITM - 400. Mỗi lò có công suất hữu ích 120MW giúp tàu phá lớp băng dày đến 4 m. Nếu lò phản ứng này sử dụng năng lượng từ sự phân hạch của ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra trung bình 200 MeV. Cho biết hiệu suất của lò phản ứng là 20%, khối lượng mol nguyên tử của   ${}_{92}^{235}U$ là 235 g/mol.<br>Để tàu ở trên cũng hoạt động trong thời gian 6 tháng mà dùng nhiên liệu xăng với năng suất tỏa nhiệt của xăng là q = 44,8.MJ/kg ( nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 1 kg xăng là 44,8MJ), biết hiệu suất của động cơ xăng là 40% thì cần ít nhất là x.10<sup>6</sup> kg xăng, tìm giá trị x? (kết quả làm tròn đến hàng đơn vị).","difficulty":"trung-binh","explanation":"$Q=\\frac{A}{H}=\\frac{3,73248.10^{15}}{0,4}=9,3312.10^{15}J$<br>$m=\\frac{Q}{m}=\\frac{9,3312.10^{15}}{44,8.10^6}\\approx 208.10^6kg$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một mô hình máy phát điện từ năng lượng sóng biển  được mô tả như hình 10 trong đó máy phát điện được chú thích như hình vẽ. Giả sử stato gồm 500 vòng dây giống nhau, mỗi vòng có diện tích 0, 126 m2, nam châm điện tạo ra từ trường cảm ứng từ 0,015 T, hộp tăng tốc độ góc đang ở chế độ tăng 45 lần. Người ta quan sát thấy phao thực hiện 14 lần dao động trong 20 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046310641-hinh-14.webp\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":367,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"208","question":"Tàu phá băng mang tên Rossiya là tàu phá băng  lớn nhất của nước Nga chạy bằng năng lượng hạt nhân. Tàu nặng 69.700 tấn, chiều dài 209,2 mét, chiều rộng 47,7 mét, sâu 18,7 mét, tốc độ 23 hải lý/giờ, tàu được trang bị hai lò phản ứng RITM - 400. Mỗi lò có công suất hữu ích 120MW giúp tàu phá lớp băng dày đến 4 m. Nếu lò phản ứng này sử dụng năng lượng từ sự phân hạch của ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra trung bình 200 MeV. Cho biết hiệu suất của lò phản ứng là 20%, khối lượng mol nguyên tử của   ${}_{92}^{235}U$ là 235 g/mol.<br>Để tàu ở trên cũng hoạt động trong thời gian 6 tháng mà dùng nhiên liệu xăng với năng suất tỏa nhiệt của xăng là q = 44,8.MJ/kg ( nhiệt lượng tỏa ra khi đốt cháy hoàn toàn 1 kg xăng là 44,8MJ), biết hiệu suất của động cơ xăng là 40% thì cần ít nhất là x.10<sup>6</sup> kg xăng, tìm giá trị x? (kết quả làm tròn đến hàng đơn vị).","difficulty":"trung-binh","explanation":"$Q=\\frac{A}{H}=\\frac{3,73248.10^{15}}{0,4}=9,3312.10^{15}J$<br>$m=\\frac{Q}{m}=\\frac{9,3312.10^{15}}{44,8.10^6}\\approx 208.10^6kg$<br>Sử dụng thông tin sau cho Câu 3 và Câu 4: Một mô hình máy phát điện từ năng lượng sóng biển  được mô tả như hình 10 trong đó máy phát điện được chú thích như hình vẽ. Giả sử stato gồm 500 vòng dây giống nhau, mỗi vòng có diện tích 0, 126 m2, nam châm điện tạo ra từ trường cảm ứng từ 0,015 T, hộp tăng tốc độ góc đang ở chế độ tăng 45 lần. Người ta quan sát thấy phao thực hiện 14 lần dao động trong 20 s.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046310641-hinh-14.webp\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1481120,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":3,"options":["10 lít.","20 lít.","15 lít.","8 lít."],"question":"Người ta biến đổi đẳng nhiệt một khối khí có thể tích là 12 lít ở áp suất 105 Pa sang trạng thái có áp suất 1, 5.10<sup>5</sup> Pa. Sau khi biến đổi, thể tích khối khí là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình biến đổi đẳng nhiệt của một lượng khí xác định tuân theo định luật Boyle–Mariotte: $p_1V_1 = p_2V_2$ (nhiệt độ không đổi, khối lượng khí không đổi).</p><p class=\"text-base leading-relaxed my-2\">Trạng thái đầu: $p_1 = 10^5$ Pa, $V_1 = 12$ lít.</p><p class=\"text-base leading-relaxed my-2\">Trạng thái sau: $p_2 = 1{,}5\\cdot 10^5$ Pa, $V_2 = ?$</p><p class=\"text-base leading-relaxed my-2\">Từ định luật Boyle–Mariotte, suy ra $V_2 = \\dfrac{p_1V_1}{p_2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_2 = \\dfrac{10^5 \\cdot 12}{1{,}5\\cdot 10^5} = 8$ lít.</p><p class=\"text-base leading-relaxed my-2\">Vậy thể tích khối khí sau biến đổi là 8 lít, chọn D.</p>","difficultySource":"ai"},"ex":[{"exam":369,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":3,"options":["10 lít.","20 lít.","15 lít.","8 lít."],"question":"Người ta biến đổi đẳng nhiệt một khối khí có thể tích là 12 lít ở áp suất 105 Pa sang trạng thái có áp suất 1, 5.10<sup>5</sup> Pa. Sau khi biến đổi, thể tích khối khí là","difficulty":"de","explanation":"$pV=const\\Rightarrow 10^5.12=1,5.10^5.V\\Rightarrow V=8ℓ$","difficultySource":"ai"}}]},{"id":1481161,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"1,32","question":"Chất NaN3, được sử dụng trong túi khí ô tô như một nguồn cung cấp khí Nitơ để bơm căng túi khí nhanh chóng khi xảy ra va chạm. Khi ô tô va chạm mạnh vào vật cản, cảm biến va chạm sẽ kích thích làm chất rắn này phân hủy tạo ra khí N2 theo phương trình: 2NaN3 → 2Na + 3N2. Khí N2 làm túi khí phồng lên, giúp người lái xe không va chạm trực tiếp với hệ thống lái. Trong một vụ thử nghiệm làm túi khí phồng lên, khi người lái không đè lên túi khí, túi khí có thể tích là 8,75 lít, nhiệt độ 270C. Khi người lái đè lên túi khí, túi khí có thể tích là 7,95 lít, áp suất 1,2.10<sup>5</sup> Pa. Coi nhiệt độ túi khí không thay đổi.<br>Khi người lái không đè lên túi khí, áp suất của túi khí bằng x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"de","explanation":"Phương trình định luật Boyle:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow p_1=\\frac{p_2V_2}{V_1}=\\frac{1,2.10^8.8,75}{7,95}=1,32.10^5PaWebsite: thukhoadaihoc.vn$<br>$\\Rightarrow x=1,32$<br>Sử dụng thông tin sau đây cho Câu 3 và Câu 4: Một mô hình máy phát điện xoay chiều gồm khung dây dẫn phẳng hình chữ nhật ABCD có AB = 16,0 cm, BC = 4,50 cm. Biết khung dây có 100 vòng, quay đều với tốc độ 15,0 vòng/s quanh trục cố định vuông góc với cảm ứng từ của từ trường đều có cảm ứng từ B = 1,45 T, điện trở của khung không đáng kể. Đầu ra của khung được nối với điện trở R = 2,50 Ω. Cho π = 3,14.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046329643-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":370,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":"1,32","question":"Chất NaN3, được sử dụng trong túi khí ô tô như một nguồn cung cấp khí Nitơ để bơm căng túi khí nhanh chóng khi xảy ra va chạm. Khi ô tô va chạm mạnh vào vật cản, cảm biến va chạm sẽ kích thích làm chất rắn này phân hủy tạo ra khí N2 theo phương trình: 2NaN3 → 2Na + 3N2. Khí N2 làm túi khí phồng lên, giúp người lái xe không va chạm trực tiếp với hệ thống lái. Trong một vụ thử nghiệm làm túi khí phồng lên, khi người lái không đè lên túi khí, túi khí có thể tích là 8,75 lít, nhiệt độ 270C. Khi người lái đè lên túi khí, túi khí có thể tích là 7,95 lít, áp suất 1,2.10<sup>5</sup> Pa. Coi nhiệt độ túi khí không thay đổi.<br>Khi người lái không đè lên túi khí, áp suất của túi khí bằng x.10<sup>5</sup> Pa. Giá trị của x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"de","explanation":"Phương trình định luật Boyle:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}p_1V_1=p_2V_2\\Rightarrow p_1=\\frac{p_2V_2}{V_1}=\\frac{1,2.10^8.8,75}{7,95}=1,32.10^5PaWebsite: thukhoadaihoc.vn$<br>$\\Rightarrow x=1,32$<br>Sử dụng thông tin sau đây cho Câu 3 và Câu 4: Một mô hình máy phát điện xoay chiều gồm khung dây dẫn phẳng hình chữ nhật ABCD có AB = 16,0 cm, BC = 4,50 cm. Biết khung dây có 100 vòng, quay đều với tốc độ 15,0 vòng/s quanh trục cố định vuông góc với cảm ứng từ của từ trường đều có cảm ứng từ B = 1,45 T, điện trở của khung không đáng kể. Đầu ra của khung được nối với điện trở R = 2,50 Ω. Cho π = 3,14.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046329643-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1481164,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,55","question":"Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.<br>Trong mỗi ngày tàu ngầm tiêu thụ hết bao nhiêu kgnhiên liệu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"Số phản ứng phân hạch diễn ra trong 1 ngày:<br>$N=\\frac{9,72.10^6.3600000}{0,25.205.10^6.1,6.10^{−19}}=4,27.10^{24}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>⇒ Khối lượng Uranium tương ứng:<br>$m=\\frac{4,27.10^{24}}{6,023.10^{23}}.235=1665g$<br>Khối lượng nhiên liệu:<br>$M=\\frac{1665}{0,3}=5,55kg$<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.","difficultySource":"ai"},"ex":[{"exam":370,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5,55","question":"Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.<br>Trong mỗi ngày tàu ngầm tiêu thụ hết bao nhiêu kgnhiên liệu (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"kho","explanation":"Số phản ứng phân hạch diễn ra trong 1 ngày:<br>$N=\\frac{9,72.10^6.3600000}{0,25.205.10^6.1,6.10^{−19}}=4,27.10^{24}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>⇒ Khối lượng Uranium tương ứng:<br>$m=\\frac{4,27.10^{24}}{6,023.10^{23}}.235=1665g$<br>Khối lượng nhiên liệu:<br>$M=\\frac{1665}{0,3}=5,55kg$<br>Sử dụng các thông tin sau cho Câu 5 và Câu 6: Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.","difficultySource":"ai"}}]},{"id":1481165,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"9,72","question":"Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.<br>Mỗi ngày lò phản ứng trên tàu tạo ra x.10<sup>6</sup> kWh điện.  Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Điện năng mà mỗi ngày lò phản ứng tạo ra:<br>$A=P.t=405.10^6.24=9,72.10^6kWh$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow x=9,72$","difficultySource":"ai"},"ex":[{"exam":370,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"9,72","question":"Một tàu ngầm sử dụng năng lượng phân hạch để vận hành động cơ trong thời gian dài mà không cần tiếp nhiên liệu. Lò phản ứng trên tàu sử dụng năng lượng phân hạch hạt nhân  ${}_{92}^{235}U$  để phát điện cho động cơ hoạt động. Biết rằng mỗi phản ứng phân hạch  ${}_{92}^{235}U$  tỏa ra năng lượng khoảng 205MeVvà chỉ có 25% năng lượng phân hạch được chuyển thành điện năng, công suất phát điện của lò là 405MW. Nhiên liệu uranium sử dụng được làm giàu đến 30,0%( ${}_{92}^{235}U$  chiếm tỉ lệ 30,0% khối lượng nhiên liệu). Cho khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol; 1eV 1,60.10<sup>−19</sup>J.<br>Mỗi ngày lò phản ứng trên tàu tạo ra x.10<sup>6</sup> kWh điện.  Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"Điện năng mà mỗi ngày lò phản ứng tạo ra:<br>$A=P.t=405.10^6.24=9,72.10^6kWh$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow x=9,72$","difficultySource":"ai"}}]},{"id":1481191,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","answer":"7,98","question":"Mỗi hạt nhân oxygen  ${}_8^{16}O$ có khối lượng xấp xỉ 15,990523amu. Biết khối lượng của proton và neutron lần lượt là 1,007276amu, 1,008665 amu và 1amu = 931,5MeV/c2.<br>Năng lượng liên kết riêng của hạt nhân oxygen là bao nhiêu MeV/ nucleon (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}\\Delta m=8m_p+8m_n−m=8.1,007276+8.1,008665−15,990523=0,137005uWebsite: thukhoadaihoc.vn$<br>$W_{lk}=\\Delta mc^2=0,137005.931,5=127,62MeV$<br>$W_{lkr}=\\frac{W_{lk}}{A}=\\frac{127,62}{16}\\approx 7,98\\left(MeV/nucleon\\right)$<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Một bộ thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều; một nam châm; một chiếc cân; một bộ nguồn điện có suất điện động E = 16,0 V, điện trở trong r = 0,6Ω; một khóa K có điện trở không đáng kể. Sợi dây có tiết diện S = 3, 5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở của sợi dây được xác định bằng công thức R = 1,7.10<sup>−8</sup>. $\\frac{L}{S}$ , trong đó L tính bằng m, S tính bằng m2, R tính bằng Ω. Nối sợi dây vào bộ nguồn điện qua công tắc K.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046347138-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":371,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng liên kết riêng và độ bền hạt nhân","answer":"7,98","question":"Mỗi hạt nhân oxygen  ${}_8^{16}O$ có khối lượng xấp xỉ 15,990523amu. Biết khối lượng của proton và neutron lần lượt là 1,007276amu, 1,008665 amu và 1amu = 931,5MeV/c2.<br>Năng lượng liên kết riêng của hạt nhân oxygen là bao nhiêu MeV/ nucleon (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"$\\begin{aligned}\\end{aligned}\\Delta m=8m_p+8m_n−m=8.1,007276+8.1,008665−15,990523=0,137005uWebsite: thukhoadaihoc.vn$<br>$W_{lk}=\\Delta mc^2=0,137005.931,5=127,62MeV$<br>$W_{lkr}=\\frac{W_{lk}}{A}=\\frac{127,62}{16}\\approx 7,98\\left(MeV/nucleon\\right)$<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Một bộ thiết bị bao gồm một sợi dây dẫn điện đồng chất, tiết diện đều; một nam châm; một chiếc cân; một bộ nguồn điện có suất điện động E = 16,0 V, điện trở trong r = 0,6Ω; một khóa K có điện trở không đáng kể. Sợi dây có tiết diện S = 3, 5.10<sup>−9</sup> m2, chiều dài L = 72,0 cm và điện trở của sợi dây được xác định bằng công thức R = 1,7.10<sup>−8</sup>. $\\frac{L}{S}$ , trong đó L tính bằng m, S tính bằng m2, R tính bằng Ω. Nối sợi dây vào bộ nguồn điện qua công tắc K.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046347138-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1481231,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Lực từ. Cảm ứng từ","answer":3,"options":["8,01 mN.","22,25 N.","22,25 mN.","8,01 N."],"question":"Một đoạn dây dẫn tải điện dài 36,0 m, nằm ngang có dòng điện 22,0 A chạy qua theo chiều từ Tây sang Đông. Giả sử tại vị trí này, từ trường Trái Đất nằm ngang và chiều từ Nam lên Bắc với độ lớn 0,5.104 T.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046429914-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Biết đoạn dây dẫn tải điện đó được làm bằng đồng và có tiết diện là 2,5.10<sup>6</sup> m2, khối lượng riêng của đồng là 8,9.10<sup>3</sup> kg/m3, lấy g = 10 $m/s^2$. Lực hấp dẫn của Trái Đất tác dụng lên đoạn dây dẫn tải điện đó có độ lớn bằng","difficulty":"trung-binh","explanation":"Lực hấp dẫn của Trái Đất tác dụng lên đoạn dây dẫn tải điện đó là:<br>$F_{hd}=P=m.g=D.V.g=D.S.l.g=8,9.{10}^3.2,5.{10}^{-6}.36.10=8,01$  N.","difficultySource":"ai"},"ex":[{"exam":376,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Lực từ. Cảm ứng từ","answer":3,"options":["8,01 mN.","22,25 N.","22,25 mN.","8,01 N."],"question":"Một đoạn dây dẫn tải điện dài 36,0 m, nằm ngang có dòng điện 22,0 A chạy qua theo chiều từ Tây sang Đông. Giả sử tại vị trí này, từ trường Trái Đất nằm ngang và chiều từ Nam lên Bắc với độ lớn 0,5.104 T.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046429914-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Biết đoạn dây dẫn tải điện đó được làm bằng đồng và có tiết diện là 2,5.10<sup>6</sup> m2, khối lượng riêng của đồng là 8,9.10<sup>3</sup> kg/m3, lấy g = 10 m/s2. Lực hấp dẫn của Trái Đất tác dụng lên đoạn dây dẫn tải điện đó có độ lớn bằng","difficulty":"trung-binh","explanation":"Lực hấp dẫn của Trái Đất tác dụng lên đoạn dây dẫn tải điện đó là:<br>$F_{hd}=P=m.g=D.V.g=D.S.l.g=8,9.{10}^3.2,5.{10}^{-6}.36.10=8,01$  N.","difficultySource":"ai"}}]},{"id":1481276,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,21. 10<sup>−21</sup> J.","2,76. 10<sup>−21</sup> J.","6,12. 10<sup>−21</sup> J.","5,59. 10<sup>−22</sup> J."],"question":"Động năng tịnh tiến trung bình của mỗi phân tử khí là","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}J$","difficultySource":"ai"},"ex":[{"exam":379,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":0,"options":["6,21. 10<sup>−21</sup> J.","2,76. 10<sup>−21</sup> J.","6,12. 10<sup>−21</sup> J.","5,59. 10<sup>−22</sup> J."],"question":"Động năng tịnh tiến trung bình của mỗi phân tử khí là","difficulty":"de","explanation":"$W_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,21.10^{−21}J$","difficultySource":"ai"}}]},{"id":1481328,"nq":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"5,01","question":"Một loại khí chứa trong một xilanh được lắp một pít-tông như hình bên. Thể tích của nó trong xilanh là 1,5 lít. Chỉ số áp suất trên đồng hồ đo bằng áp kế Bourdon là 2,54.10<sup>5</sup> N/m2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046520498-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu nhiệt độ của khối khí tăng từ giá trị ban đầu 270C lên đến 3270C nhưng thể tích giữ nguyên. Áp suất mới của lượng khí là bao nhiêu atm? (kết quả làm tròn đến chữ số hàng phần trăm)? Biết 1 atm = 101325 Pa.","difficulty":"de","explanation":"$\\frac{p}{T}=const\\Rightarrow \\frac{2,54.10^5}{27+273}=\\frac{p}{327+273}\\Rightarrow p=5,08.10^5Pa\\approx 5,01atm$","difficultySource":"ai"},"ex":[{"exam":380,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Quá trình đẳng áp và định luật Charles","answer":"5,01","question":"Một loại khí chứa trong một xilanh được lắp một pít-tông như hình bên. Thể tích của nó trong xilanh là 1,5 lít. Chỉ số áp suất trên đồng hồ đo bằng áp kế Bourdon là 2,54.10<sup>5</sup> N/m2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046520498-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu nhiệt độ của khối khí tăng từ giá trị ban đầu 270C lên đến 3270C nhưng thể tích giữ nguyên. Áp suất mới của lượng khí là bao nhiêu atm? (kết quả làm tròn đến chữ số hàng phần trăm)? Biết 1 atm = 101325 Pa.","difficulty":"de","explanation":"$\\frac{p}{T}=const\\Rightarrow \\frac{2,54.10^5}{27+273}=\\frac{p}{327+273}\\Rightarrow p=5,08.10^5Pa\\approx 5,01atm$","difficultySource":"ai"}}]},{"id":1481352,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Xenon  ${}_{54}^{133}Xe$  là đồng vị phóng xạ β‒ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Chu kì bán rã của xenon  ${}_{54}^{133}Xe$ là 5,24 ngày. Một mẫu khí chứa  ${}_{54}^{133}Xe$  Xe khi được sản xuất tại nhà máy có độ phóng xạ là 4,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện sử dụng cho bệnh nhân sau đó 3,0 ngày.","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của xenon  ${}_{54}^{133}Xe$  Xe là 0,132 s‒1.","answer":false},{"text":"Sản phẩm phân rã của xenon  ${}_{54}^{133}Xe$ là cesium 13355 Cs","answer":true},{"text":"Khi bệnh nhân sử dụng, độ phóng xạ của mẫu khí là 1,86.10<sup>9</sup> Bq","answer":false},{"text":"Số nguyên tử  có trong mẫu mới sản xuất là 2,78.10<sup>15</sup> nguyên tử.","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{5,24.24.3600}=1,531.10^{−6}(s^{−1})$<br>b) đúng<br>${}_{54}^{133}Xe\\rightarrow {{}_{−1}^0\\beta}^−+{}_{55}^{133}Cs$<br>c) sai<br>$H=H_0.2^{−\\frac{t}{T}}=4,25.10^9.2^{\\frac{−3}{5,24}}\\approx 2,86.10^9\\left(Bq\\right)$<br>d) đúng<br>$H_0=N_0\\lambda \\Rightarrow N_0=\\frac{H_0}{\\lambda }=2,78.10^{15}$","difficultySource":"ai"},"ex":[{"exam":381,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật phóng xạ và chu kì bán rã","question":"Xenon  ${}_{54}^{133}Xe$  là đồng vị phóng xạ β‒ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Chu kì bán rã của xenon  ${}_{54}^{133}Xe$ là 5,24 ngày. Một mẫu khí chứa  ${}_{54}^{133}Xe$  Xe khi được sản xuất tại nhà máy có độ phóng xạ là 4,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện sử dụng cho bệnh nhân sau đó 3,0 ngày.","difficulty":"kho","statements":[{"text":"Hằng số phóng xạ của xenon  ${}_{54}^{133}Xe$  Xe là 0,132 s‒1.","answer":false},{"text":"Sản phẩm phân rã của xenon  ${}_{54}^{133}Xe$ là cesium 13355 Cs","answer":true},{"text":"Khi bệnh nhân sử dụng, độ phóng xạ của mẫu khí là 1,86.10<sup>9</sup> Bq","answer":false},{"text":"Số nguyên tử  có trong mẫu mới sản xuất là 2,78.10<sup>15</sup> nguyên tử.","answer":true}],"explanation":"a) sai<br>$\\lambda =\\frac{ln2}{T}=\\frac{ln2}{5,24.24.3600}=1,531.10^{−6}(s^{−1})$<br>b) đúng<br>${}_{54}^{133}Xe\\rightarrow {{}_{−1}^0\\beta}^−+{}_{55}^{133}Cs$<br>c) sai<br>$H=H_0.2^{−\\frac{t}{T}}=4,25.10^9.2^{\\frac{−3}{5,24}}\\approx 2,86.10^9\\left(Bq\\right)$<br>d) đúng<br>$H_0=N_0\\lambda \\Rightarrow N_0=\\frac{H_0}{\\lambda }=2,78.10^{15}$","difficultySource":"ai"}}]},{"id":1481434,"nq":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Thí nghiệm đo nhiệt nóng chảy riêng của nước đá được mô tả như hình vẽ. Dây đun (dây điện trở) có công suất 480 W dùng để làm nóng chảy nước đá trong thùng chứa. Sau 120 s, số chỉ của cân điện tử giảm đi 0,172 kg . Cho biết chỉ có sự trao đổi nhiệt giữa nước đá và dây đun.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046573701-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg .","answer":true},{"text":"Việc đọc số liệu trên cân điện tử phải được thực hiện khi nguồn điện còn đang bật và ống thoát nước vẫn mở để tăng độ chính xác.","answer":false},{"text":"Nhiệt lượng cần thiết để làm tan nước đá ở thí nghiệm trên là 57600 J.","answer":true},{"text":"Nhiệt nóng chảy riêng của nước đá đo được ở thí nghiệm này lớn hơn 3,4.10<sup>5</sup> J/kg","answer":false}],"explanation":"Công thức: nhiệt lượng do dây đun tỏa ra Q = P·t; nhiệt lượng này dùng làm nóng chảy nước đá: Q = λ·Δm (λ là nhiệt nóng chảy riêng).<br>Xét ý a): khối lượng nước đá đã tan chính bằng độ giảm số chỉ của cân, Δm = 0,172 kg — đúng như phát biểu ⇒ ý a) đúng.<br>Xét ý b): việc đọc số liệu trên cân điện tử phải được thực hiện SAU KHI đã tắt nguồn điện và ngừng cấp nhiệt (không phải trong lúc nguồn đang bật), vì nguồn điện đang bật sẽ tiếp tục truyền nhiệt và gây nhiễu/rung khi đọc số liệu ⇒ phát biểu 'còn đang bật' là không đúng, ý b) sai.<br>Xét ý c): Q = P·t = 480×120 = 57600 J — đúng như phát biểu ⇒ ý c) đúng.<br>Xét ý d): λ = Q/Δm = 57600/0,172 ≈ 334884 J/kg ≈ 3,35×10⁵ J/kg, nhỏ hơn 3,4×10⁵ J/kg chứ không lớn hơn ⇒ ý d) sai.<br>Kết quả: a) Đúng, b) Sai, c) Đúng, d) Sai.<br>a) đúng<br>Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg .<br>b) sai<br>Nguồn điện còn đang bật sẽ gây nhiếu<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}Q=Pt=480.120=57600JWebsite: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}\\end{aligned}\\lambda =\\frac{Q}{\\Delta m}=\\frac{57600}{0,172}\\approx 334883,7\\left(J/kg\\right)<3,4.10^5\\left(J/kg\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":386,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Xử lí số liệu thí nghiệm đo nhiệt","question":"Thí nghiệm đo nhiệt nóng chảy riêng của nước đá được mô tả như hình vẽ. Dây đun (dây điện trở) có công suất 480 W dùng để làm nóng chảy nước đá trong thùng chứa. Sau 120 s, số chỉ của cân điện tử giảm đi 0,172 kg . Cho biết chỉ có sự trao đổi nhiệt giữa nước đá và dây đun.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046573701-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg .","answer":true},{"text":"Việc đọc số liệu trên cân điện tử phải được thực hiện khi nguồn điện còn đang bật và ống thoát nước vẫn mở để tăng độ chính xác.","answer":false},{"text":"Nhiệt lượng cần thiết để làm tan nước đá ở thí nghiệm trên là 57600 J.","answer":true},{"text":"Nhiệt nóng chảy riêng của nước đá đo được ở thí nghiệm này lớn hơn 3,4.10<sup>5</sup> J/kg","answer":false}],"explanation":"Công thức: nhiệt lượng do dây đun tỏa ra Q = P·t; nhiệt lượng này dùng làm nóng chảy nước đá: Q = λ·Δm (λ là nhiệt nóng chảy riêng).<br>Xét ý a): khối lượng nước đá đã tan chính bằng độ giảm số chỉ của cân, Δm = 0,172 kg — đúng như phát biểu ⇒ ý a) đúng.<br>Xét ý b): việc đọc số liệu trên cân điện tử phải được thực hiện SAU KHI đã tắt nguồn điện và ngừng cấp nhiệt (không phải trong lúc nguồn đang bật), vì nguồn điện đang bật sẽ tiếp tục truyền nhiệt và gây nhiễu/rung khi đọc số liệu ⇒ phát biểu 'còn đang bật' là không đúng, ý b) sai.<br>Xét ý c): Q = P·t = 480×120 = 57600 J — đúng như phát biểu ⇒ ý c) đúng.<br>Xét ý d): λ = Q/Δm = 57600/0,172 ≈ 334884 J/kg ≈ 3,35×10⁵ J/kg, nhỏ hơn 3,4×10⁵ J/kg chứ không lớn hơn ⇒ ý d) sai.<br>Kết quả: a) Đúng, b) Sai, c) Đúng, d) Sai.<br>a) đúng<br>Khối lượng nước đá đã tan trong thời gian đun là 0,172 kg .<br>b) sai<br>Nguồn điện còn đang bật sẽ gây nhiếu<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>$\\begin{aligned}\\end{aligned}Q=Pt=480.120=57600JWebsite: thukhoadaihoc.vn$<br>d) sai<br>$\\begin{aligned}\\end{aligned}\\lambda =\\frac{Q}{\\Delta m}=\\frac{57600}{0,172}\\approx 334883,7\\left(J/kg\\right)<3,4.10^5\\left(J/kg\\right)Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481441,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"14,1","question":"Một dây dẫn thẳng nằm ngang truyền tải dòng điện xoay chiều từ nhà máy điện đến nơi tiêu thụ. Cường độ dòng điện hiệu dụng trong dây dẫn này là 50A. Thành phần nằm ngang của từ trường Trái Đất tại khu vực truyền tải có độ lớn 4.10<sup>−5</sup>T và tạo với dây dẫn một góc sao cho lực từ đạt cực đại.<br>Biết dây dẫn có chiều dài 5 km. Lực từ cực đại do từ trường Trái Đất tác dụng lên toàn bộ chiều dài dây dẫn là bao nhiêu Newton? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Công thức: lực từ cực đại tác dụng lên dây dẫn mang dòng điện xoay chiều F_max = I₀·L·B, với I₀ = I√2 là giá trị cực đại của dòng điện hiệu dụng I.<br>Thay số: I₀ = 50√2 A, L = 5 km = 5×10³ m, B = 4×10⁻⁵ T. F_max = 50√2×5×10³×4×10⁻⁵ ≈ 14,14 N.<br>Kết quả: làm tròn đến hàng phần mười, F_max ≈ 14,1 N. Đáp số: 14,1.<br>$I_0=I\\sqrt2=50\\sqrt2A$<br>$\\begin{aligned}\\end{aligned}F_{max}=I_0LB=50\\sqrt2.5.10^3.4.10^{−5}\\approx 14,1NWebsite: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":386,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"14,1","question":"Một dây dẫn thẳng nằm ngang truyền tải dòng điện xoay chiều từ nhà máy điện đến nơi tiêu thụ. Cường độ dòng điện hiệu dụng trong dây dẫn này là 50A. Thành phần nằm ngang của từ trường Trái Đất tại khu vực truyền tải có độ lớn 4.10<sup>−5</sup>T và tạo với dây dẫn một góc sao cho lực từ đạt cực đại.<br>Biết dây dẫn có chiều dài 5 km. Lực từ cực đại do từ trường Trái Đất tác dụng lên toàn bộ chiều dài dây dẫn là bao nhiêu Newton? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Công thức: lực từ cực đại tác dụng lên dây dẫn mang dòng điện xoay chiều F_max = I₀·L·B, với I₀ = I√2 là giá trị cực đại của dòng điện hiệu dụng I.<br>Thay số: I₀ = 50√2 A, L = 5 km = 5×10³ m, B = 4×10⁻⁵ T. F_max = 50√2×5×10³×4×10⁻⁵ ≈ 14,14 N.<br>Kết quả: làm tròn đến hàng phần mười, F_max ≈ 14,1 N. Đáp số: 14,1.<br>$I_0=I\\sqrt2=50\\sqrt2A$<br>$\\begin{aligned}\\end{aligned}F_{max}=I_0LB=50\\sqrt2.5.10^3.4.10^{−5}\\approx 14,1NWebsite: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481466,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"730","question":"Một xe điện sử dụng hệ thống phanh tái sinh để thu hồi năng lượng khi giảm tốc. Trong lúc hãm phanh, bánh xe quay với tốc độ góc ω = 40,0 rad/s và động cơ điện hoạt động như một máy phát điện xoay chiều. Biết rằng cuộn dây của động cơ có N = 987 vòng, diện tích mỗi vòng S = 20,0.10<sup>−3</sup> m2; đặt trong từ trường đều B = 925 mT. Suất điện động xoay chiều qua bộ chuyển đổi và tạo ra dòng một chiều để nạp vào ắc quy. Biết 80,0% năng lượng điện tạo ra ở máy phát được nạp vào ắc quy 400,0 V. Điện trở toàn mạch là 4,00 Ω.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046608168-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Suất điện động được tạo ra trong quá trình phanh có giá trị cực đại là bao nhiêu vôn (V) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"Công thức: suất điện động cực đại của khung dây quay trong từ trường đều: E0 = N.B.ω.S.<br>Thay số: N = 987, B = 925 mT = 0,925 T, ω = 40,0 rad/s, S = 20,0.10^-3 m² → E0 = 987 . 0,925 . 40 . 0,02 = 730,38 V.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: E0 ≈ 730 V.<br>$E_0=NBS\\omega =987.925.10^{−3}.20.10^{−3}.40=730,38V$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":389,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"730","question":"Một xe điện sử dụng hệ thống phanh tái sinh để thu hồi năng lượng khi giảm tốc. Trong lúc hãm phanh, bánh xe quay với tốc độ góc ω = 40,0 rad/s và động cơ điện hoạt động như một máy phát điện xoay chiều. Biết rằng cuộn dây của động cơ có N = 987 vòng, diện tích mỗi vòng S = 20,0.10<sup>−3</sup> m2; đặt trong từ trường đều B = 925 mT. Suất điện động xoay chiều qua bộ chuyển đổi và tạo ra dòng một chiều để nạp vào ắc quy. Biết 80,0% năng lượng điện tạo ra ở máy phát được nạp vào ắc quy 400,0 V. Điện trở toàn mạch là 4,00 Ω.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046608168-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Suất điện động được tạo ra trong quá trình phanh có giá trị cực đại là bao nhiêu vôn (V) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"de","explanation":"Công thức: suất điện động cực đại của khung dây quay trong từ trường đều: E0 = N.B.ω.S.<br>Thay số: N = 987, B = 925 mT = 0,925 T, ω = 40,0 rad/s, S = 20,0.10^-3 m² → E0 = 987 . 0,925 . 40 . 0,02 = 730,38 V.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: E0 ≈ 730 V.<br>$E_0=NBS\\omega =987.925.10^{−3}.20.10^{−3}.40=730,38V$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481467,"nq":{"form":"bai_tap","type":"short_answer","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":"12","question":"Một xe điện sử dụng hệ thống phanh tái sinh để thu hồi năng lượng khi giảm tốc. Trong lúc hãm phanh, bánh xe quay với tốc độ góc ω = 40,0 rad/s và động cơ điện hoạt động như một máy phát điện xoay chiều. Biết rằng cuộn dây của động cơ có N = 987 vòng, diện tích mỗi vòng S = 20,0.10<sup>−3</sup> m2; đặt trong từ trường đều B = 925 mT. Suất điện động xoay chiều qua bộ chuyển đổi và tạo ra dòng một chiều để nạp vào ắc quy. Biết 80,0% năng lượng điện tạo ra ở máy phát được nạp vào ắc quy 400,0 V. Điện trở toàn mạch là 4,00 Ω.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046608168-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Công suất nạp được vào ắc quy trong mỗi lần phanh là bao nhiêu kilowatt (kW) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Công thức: dùng giá trị hiệu dụng E = E0/√2; dòng điện hiệu dụng qua mạch (điện trở toàn mạch R, nạp cho ắc quy hiệu điện thế U): I = (E − U)/R; công suất điện do máy phát tạo ra P_phát = E.I; công suất nạp vào ắc quy P_nạp = 80%.P_phát.<br>Thay số: E = 730,38/√2 ≈ 516,48 V; I = (516,48 − 400)/4 = 29,12 A; P_phát = 516,48 . 29,12 ≈ 15037,6 W → P_nạp = 0,8 . 15037,6 ≈ 12030 W.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: P_nạp ≈ 12 kW.<br>$E=\\frac{E_0}{\\sqrt2}=\\frac{730,38}{\\sqrt2}V$<br>Acquy là máy thu nên theo định luật Kirchhoff có:  $I=\\frac{E−E_{acquy}}{R}=\\frac{\\frac{730,38}{\\sqrt2}−400}{4}\\approx 29,1\\left(A\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P=0,8EI=0,8.\\frac{730,38}{\\sqrt2}.29,1\\approx 12.10^3W=12kW$","difficultySource":"ai"},"ex":[{"exam":389,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","answer":"12","question":"Một xe điện sử dụng hệ thống phanh tái sinh để thu hồi năng lượng khi giảm tốc. Trong lúc hãm phanh, bánh xe quay với tốc độ góc ω = 40,0 rad/s và động cơ điện hoạt động như một máy phát điện xoay chiều. Biết rằng cuộn dây của động cơ có N = 987 vòng, diện tích mỗi vòng S = 20,0.10<sup>−3</sup> m2; đặt trong từ trường đều B = 925 mT. Suất điện động xoay chiều qua bộ chuyển đổi và tạo ra dòng một chiều để nạp vào ắc quy. Biết 80,0% năng lượng điện tạo ra ở máy phát được nạp vào ắc quy 400,0 V. Điện trở toàn mạch là 4,00 Ω.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046608168-hinh-18.jpg\" alt=\"Hình 18\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Công suất nạp được vào ắc quy trong mỗi lần phanh là bao nhiêu kilowatt (kW) (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"Công thức: dùng giá trị hiệu dụng E = E0/√2; dòng điện hiệu dụng qua mạch (điện trở toàn mạch R, nạp cho ắc quy hiệu điện thế U): I = (E − U)/R; công suất điện do máy phát tạo ra P_phát = E.I; công suất nạp vào ắc quy P_nạp = 80%.P_phát.<br>Thay số: E = 730,38/√2 ≈ 516,48 V; I = (516,48 − 400)/4 = 29,12 A; P_phát = 516,48 . 29,12 ≈ 15037,6 W → P_nạp = 0,8 . 15037,6 ≈ 12030 W.<br>Kết quả: làm tròn đến hàng đơn vị, Đáp số: P_nạp ≈ 12 kW.<br>$E=\\frac{E_0}{\\sqrt2}=\\frac{730,38}{\\sqrt2}V$<br>Acquy là máy thu nên theo định luật Kirchhoff có:  $I=\\frac{E−E_{acquy}}{R}=\\frac{\\frac{730,38}{\\sqrt2}−400}{4}\\approx 29,1\\left(A\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$P=0,8EI=0,8.\\frac{730,38}{\\sqrt2}.29,1\\approx 12.10^3W=12kW$","difficultySource":"ai"}}]},{"id":1481468,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,96","question":"Đồng vị phóng xạ Cobalt (60Co) phát ra tia gamma năng lượng cao có khả năng tiêu diệt tế bào ung thư khi chiếu đúng liều. Một máy xạ trị sử dụng nguồn 60Co có độ phóng xạ 6750 Ci(1Ci = 3,70.10<sup>10</sup>Bq )để điều trị ung thư. Biết 60Co có chu kỳ bán rã là 5,27 năm (1 năm = 365,25 ngày) và khối lượng mol là 59,9 g/mol.<br>Khối lượng 60Co cần để đạt được độ phóng xạ 6750 Ci là bao nhiêu gam (làm tròn đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ H = λN = (ln2/T).N, với N = m.NA/M → m = H.T.M/(ln2.NA); đổi Ci sang Bq: 1 Ci = 3,70.10^10 Bq; đổi chu kì bán rã sang giây.<br>Thay số: H = 6750 . 3,70.10^10 = 2,4975.10^14 Bq; T = 5,27 . 365,25 . 86400 ≈ 1,6632.10^8 s → N = H.T/ln2 = (2,4975.10^14 . 1,6632.10^8)/0,6931 ≈ 5,994.10^22 hạt → m = N.M/NA = (5,994.10^22 . 59,9)/6,02.10^23 ≈ 5,964 g.<br>Kết quả: làm tròn đến hàng phần trăm, Đáp số: m ≈ 5,96 g.<br>$H_0=\\lambda N_0=\\frac{ln2}{T}N_0\\Rightarrow 6750.3,7.10^{10}=\\frac{ln2}{5,27.365,25.24.60.60}.N_0\\Rightarrow N_0\\approx 5,99.10^{22}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{6.10^{22}}{6,02.10^{23}}\\approx 0,0995mol$<br>$m_0=n_0M=0,0995.59,9\\approx 5,96g$","difficultySource":"ai"},"ex":[{"exam":389,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"5,96","question":"Đồng vị phóng xạ Cobalt (60Co) phát ra tia gamma năng lượng cao có khả năng tiêu diệt tế bào ung thư khi chiếu đúng liều. Một máy xạ trị sử dụng nguồn 60Co có độ phóng xạ 6750 Ci(1Ci = 3,70.10<sup>10</sup>Bq )để điều trị ung thư. Biết 60Co có chu kỳ bán rã là 5,27 năm (1 năm = 365,25 ngày) và khối lượng mol là 59,9 g/mol.<br>Khối lượng 60Co cần để đạt được độ phóng xạ 6750 Ci là bao nhiêu gam (làm tròn đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ H = λN = (ln2/T).N, với N = m.NA/M → m = H.T.M/(ln2.NA); đổi Ci sang Bq: 1 Ci = 3,70.10^10 Bq; đổi chu kì bán rã sang giây.<br>Thay số: H = 6750 . 3,70.10^10 = 2,4975.10^14 Bq; T = 5,27 . 365,25 . 86400 ≈ 1,6632.10^8 s → N = H.T/ln2 = (2,4975.10^14 . 1,6632.10^8)/0,6931 ≈ 5,994.10^22 hạt → m = N.M/NA = (5,994.10^22 . 59,9)/6,02.10^23 ≈ 5,964 g.<br>Kết quả: làm tròn đến hàng phần trăm, Đáp số: m ≈ 5,96 g.<br>$H_0=\\lambda N_0=\\frac{ln2}{T}N_0\\Rightarrow 6750.3,7.10^{10}=\\frac{ln2}{5,27.365,25.24.60.60}.N_0\\Rightarrow N_0\\approx 5,99.10^{22}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$n_0=\\frac{N_0}{N_A}=\\frac{6.10^{22}}{6,02.10^{23}}\\approx 0,0995mol$<br>$m_0=n_0M=0,0995.59,9\\approx 5,96g$","difficultySource":"ai"}}]},{"id":1481469,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"11,7","question":"Đồng vị phóng xạ Cobalt (60Co) phát ra tia gamma năng lượng cao có khả năng tiêu diệt tế bào ung thư khi chiếu đúng liều. Một máy xạ trị sử dụng nguồn 60Co có độ phóng xạ 6750 Ci(1Ci = 3,70.10<sup>10</sup>Bq )để điều trị ung thư. Biết 60Co có chu kỳ bán rã là 5,27 năm (1 năm = 365,25 ngày) và khối lượng mol là 59,9 g/mol.<br>Nếu giới hạn sử dụng an toàn là khi độ phóng xạ giảm còn 1450 Ci thì sau bao nhiêu năm phải thay nguồn (làm tròn đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ giảm theo quy luật H(t) = H0.e^(−λt) → t = ln(H0/H)/λ.<br>Thay số: H0 = 6750 Ci, H = 1450 Ci → ln(6750/1450) = ln(4,655) ≈ 1,538; λ = ln2/T ≈ 4,167.10^-9 s^-1 → t = 1,538/4,167.10^-9 ≈ 3,691.10^8 s.<br>Kết quả: đổi ra năm (1 năm = 365,25.86400 s ≈ 3,156.10^7 s): t ≈ 3,691.10^8/3,156.10^7 ≈ 11,69 năm. Làm tròn đến hàng phần mười, Đáp số: t ≈ 11,7 năm.<br>$H=H_0.2^{−\\frac{t}{T}}\\Rightarrow 1450=6750.2^{−\\frac{t}{5,27}}\\Rightarrow t\\approx 11,7$  năm<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":389,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật phóng xạ và chu kì bán rã","answer":"11,7","question":"Đồng vị phóng xạ Cobalt (60Co) phát ra tia gamma năng lượng cao có khả năng tiêu diệt tế bào ung thư khi chiếu đúng liều. Một máy xạ trị sử dụng nguồn 60Co có độ phóng xạ 6750 Ci(1Ci = 3,70.10<sup>10</sup>Bq )để điều trị ung thư. Biết 60Co có chu kỳ bán rã là 5,27 năm (1 năm = 365,25 ngày) và khối lượng mol là 59,9 g/mol.<br>Nếu giới hạn sử dụng an toàn là khi độ phóng xạ giảm còn 1450 Ci thì sau bao nhiêu năm phải thay nguồn (làm tròn đến chữ số hàng phần mười)?","difficulty":"trung-binh","explanation":"Công thức: độ phóng xạ giảm theo quy luật H(t) = H0.e^(−λt) → t = ln(H0/H)/λ.<br>Thay số: H0 = 6750 Ci, H = 1450 Ci → ln(6750/1450) = ln(4,655) ≈ 1,538; λ = ln2/T ≈ 4,167.10^-9 s^-1 → t = 1,538/4,167.10^-9 ≈ 3,691.10^8 s.<br>Kết quả: đổi ra năm (1 năm = 365,25.86400 s ≈ 3,156.10^7 s): t ≈ 3,691.10^8/3,156.10^7 ≈ 11,69 năm. Làm tròn đến hàng phần mười, Đáp số: t ≈ 11,7 năm.<br>$H=H_0.2^{−\\frac{t}{T}}\\Rightarrow 1450=6750.2^{−\\frac{t}{5,27}}\\Rightarrow t\\approx 11,7$  năm<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481515,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":0,"options":["93,75.10<sup>8</sup>.","6, 25.108.","25.108.","75.108."],"question":"Hình bên là đồ thị biểu diễn số hạt nhân phóng xạ còn lại trong một mẫu chất phóng xạ theo thời gian.<br>Sau thời gian Δt = 554 ngày đêm (kể từ thời điểm t = 0 ), số hạt nhân phóng xạ đã bị phân rã là","difficulty":"trung-binh","explanation":"$\\Delta N=N_0.\\left(1−2^{−\\frac{t}{T}}\\right)=100.10^8.\\left(1−2^{\\frac{−554}{138,5}}\\right)=93,75.10^8$","difficultySource":"ai"},"ex":[{"exam":392,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật phóng xạ và chu kì bán rã","answer":0,"options":["93,75.10<sup>8</sup>.","6, 25.108.","25.108.","75.108."],"question":"Hình bên là đồ thị biểu diễn số hạt nhân phóng xạ còn lại trong một mẫu chất phóng xạ theo thời gian.<br>Sau thời gian Δt = 554 ngày đêm (kể từ thời điểm t = 0 ), số hạt nhân phóng xạ đã bị phân rã là","difficulty":"trung-binh","explanation":"$\\Delta N=N_0.\\left(1−2^{−\\frac{t}{T}}\\right)=100.10^8.\\left(1−2^{\\frac{−554}{138,5}}\\right)=93,75.10^8$","difficultySource":"ai"}}]},{"id":1481529,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":3,"options":["360000 J.","441040 J.","801040 J.","1161040 J."],"question":"Một lò nung điện có công suất 20000 W làm nóng chảy hoàn toàn 2 kg đồng có nhiệt độ ban đầu 300C. Biết chỉ có 50% điện năng tiêu thụ của lò được dùng vào việc làm đồng nóng lên và làm đồng nóng chảy. Cho biết nhiệt dung riêng và nhiệt nóng chảy riêng của đồng có giá trị lần lượt là c = 380 J/(kg.K); λ = 1,80.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của đồng là 10840C.<br>Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 2 kg đồng là","difficulty":"trung-binh","explanation":"$Q=mc\\left(t−t_0\\right)+m\\lambda =2.380.\\left(1084−30\\right)+2.1,8.10^5=1161040\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":395,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":3,"options":["360000 J.","441040 J.","801040 J.","1161040 J."],"question":"Một lò nung điện có công suất 20000 W làm nóng chảy hoàn toàn 2 kg đồng có nhiệt độ ban đầu 300C. Biết chỉ có 50% điện năng tiêu thụ của lò được dùng vào việc làm đồng nóng lên và làm đồng nóng chảy. Cho biết nhiệt dung riêng và nhiệt nóng chảy riêng của đồng có giá trị lần lượt là c = 380 J/(kg.K); λ = 1,80.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của đồng là 10840C.<br>Nhiệt lượng cần cung cấp để làm nóng chảy hoàn toàn 2 kg đồng là","difficulty":"trung-binh","explanation":"$Q=mc\\left(t−t_0\\right)+m\\lambda =2.380.\\left(1084−30\\right)+2.1,8.10^5=1161040\\left(J\\right)$","difficultySource":"ai"}}]},{"id":1481530,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["80,104 s.","44,104 s.","36 s.","116,104 s."],"question":"Một lò nung điện có công suất 20000 W làm nóng chảy hoàn toàn 2 kg đồng có nhiệt độ ban đầu 300C. Biết chỉ có 50% điện năng tiêu thụ của lò được dùng vào việc làm đồng nóng lên và làm đồng nóng chảy. Cho biết nhiệt dung riêng và nhiệt nóng chảy riêng của đồng có giá trị lần lượt là c = 380 J/(kg.K); λ = 1,80.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của đồng là 10840C.<br>Thời gian cần làm nóng chảy hoàn toàn 2 kg đồng là","difficulty":"trung-binh","explanation":"$A=\\frac{Q}{H}=\\frac{1161400}{0,5}=2322080J$<br>$t=\\frac{A}{P}=\\frac{2322080}{20000}=116,104s$","difficultySource":"ai"},"ex":[{"exam":395,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","answer":3,"options":["80,104 s.","44,104 s.","36 s.","116,104 s."],"question":"Một lò nung điện có công suất 20000 W làm nóng chảy hoàn toàn 2 kg đồng có nhiệt độ ban đầu 300C. Biết chỉ có 50% điện năng tiêu thụ của lò được dùng vào việc làm đồng nóng lên và làm đồng nóng chảy. Cho biết nhiệt dung riêng và nhiệt nóng chảy riêng của đồng có giá trị lần lượt là c = 380 J/(kg.K); λ = 1,80.10<sup>5</sup> J/kg, nhiệt độ nóng chảy của đồng là 10840C.<br>Thời gian cần làm nóng chảy hoàn toàn 2 kg đồng là","difficulty":"trung-binh","explanation":"$A=\\frac{Q}{H}=\\frac{1161400}{0,5}=2322080J$<br>$t=\\frac{A}{P}=\\frac{2322080}{20000}=116,104s$","difficultySource":"ai"}}]},{"id":1481602,"nq":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"1039","question":"Trong hình là thí nghiệm về nhiệt kế khí ở thể tích không đổi. Nhiệt kế có bình chứa khí được những vào môi trường cần đo nhiệt độ. Thể tích của khí trong bình được giữ cổ định bằng cách nâng hoặc hạ nhánh chứa nước B để giữ mức nước trong cột A không thay đổi. Biết áp suất khí quyển là p0 = 105 Pa. Khối lượng ri êng của nước là 1000 kg/m2 và g = 9,81$m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046697706-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí trong bình là x.10<sup>2</sup> Pa khi chênh lệch mực nước 2 ống là h = 40 cm. Tìm x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Mực nước ở nhánh A được giữ ở vạch $0$, nhánh B hở (áp suất $p_0$) và có mực nước cao hơn nhánh A một đoạn $h$.</p><p class=\"text-base leading-relaxed my-2\">Áp suất của khí bằng áp suất tại mực nước A (cùng độ cao): $p=p_0+\\rho gh$.</p><p class=\"text-base leading-relaxed my-2\">$p=10^5+1000\\cdot 9,81\\cdot 0,40=103924$ Pa.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$p=x\\cdot 10^2$ Pa với $x=1039,24$, làm tròn $x\\approx 1039$.</p>","difficultySource":"ai"},"ex":[{"exam":401,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Áp suất khí quyển theo độ cao (ôn tập)","answer":"1039","question":"Trong hình là thí nghiệm về nhiệt kế khí ở thể tích không đổi. Nhiệt kế có bình chứa khí được những vào môi trường cần đo nhiệt độ. Thể tích của khí trong bình được giữ cổ định bằng cách nâng hoặc hạ nhánh chứa nước B để giữ mức nước trong cột A không thay đổi. Biết áp suất khí quyển là p0 = 105 Pa. Khối lượng ri êng của nước là 1000 kg/m2 và g = 9,81m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046697706-hinh-5.jpg\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí trong bình là x.10<sup>2</sup> Pa khi chênh lệch mực nước 2 ống là h = 40 cm. Tìm x (làm tròn kết quả đến chữ số hàng đơn vị).","difficulty":"de","explanation":"pk = p0 +Dgh = 105 +1000.9,81.0,4 = 103924 Pa = x.10<sup>2</sup>⇒x ≈ 1039.","difficultySource":"ai"}}]},{"id":1481653,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"2,4","question":"Một thiết bị dò bức xạ CR-39 trong môi trường không khí trong nhà có thể tích 40.10<sup>−6</sup>m3 người ta đo được số hạt nhân  ${}_{222}^{}Ra$  phóng xạ trong 1s là 2 phân rã/s. Biết chu kỳ bán rã của  ${}_{222}^{}Ra$  là 3,8 ngày. Số hạt nhân có trong 1m3 không khí bên trong căn nhà đó là x.10<sup>10</sup>. x có giá trị bao nhiêu? (làm tròn đến số thập phân thứ nhất)","difficulty":"trung-binh","explanation":"Hằng số phân rã phóng xạ:   $\\lambda =\\frac{ln2}{T}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Độ phóng xạ:  $H=\\lambda .N=\\frac{ln2}{T}N=>N=\\frac{H.T}{ln2}$<br>Số hạt nhân  ${}_{222}^{}Ra$ chứa trong 1m3 không khí là N1m3 =  $\\frac{N.1}{40.10^{−6}}≃2,37.10^{10}$ (hạt/m3)","difficultySource":"ai"},"ex":[{"exam":412,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"2,4","question":"Một thiết bị dò bức xạ CR-39 trong môi trường không khí trong nhà có thể tích 40.10<sup>−6</sup>m3 người ta đo được số hạt nhân  ${}_{222}^{}Ra$  phóng xạ trong 1s là 2 phân rã/s. Biết chu kỳ bán rã của  ${}_{222}^{}Ra$  là 3,8 ngày. Số hạt nhân có trong 1m3 không khí bên trong căn nhà đó là x.10<sup>10</sup>. x có giá trị bao nhiêu? (làm tròn đến số thập phân thứ nhất)","difficulty":"trung-binh","explanation":"Hằng số phân rã phóng xạ:   $\\lambda =\\frac{ln2}{T}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Độ phóng xạ:  $H=\\lambda .N=\\frac{ln2}{T}N=>N=\\frac{H.T}{ln2}$<br>Số hạt nhân  ${}_{222}^{}Ra$ chứa trong 1m3 không khí là N1m3 =  $\\frac{N.1}{40.10^{−6}}≃2,37.10^{10}$ (hạt/m3)","difficultySource":"ai"}}]},{"id":1481692,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":2,"options":["chỉ lan truyền được trong chân không.","chỉ lan truyền trong các môi trường đàn hồi như rắn, lỏng, khí.","lan truyền được cả chân không và các môi trường vật chất.","không lan truyền được trong chân không."],"question":"Sóng điện từ","difficulty":"de","explanation":"Sóng điện từ có khả năng lan truyền trong nhiều môi trường, bao gồm cả chân không và các môi trường vật chất như chất khí, chất lỏng và chất rắn. Trong chân không, sóng điện từ truyền với tốc độ lớn nhất, khoảng 3×10<sup>8</sup> m/s.<br>Sử dụng các thông tin sau cho Câu 10 và Câu 11: Máy phát điện xoay chiều một pha hoạt động dựa trên hiện tượng cảm ứng điện từ. Khi một khung dây hoặc cuộn dây (stato) cắt qua từ trường biến thiên do chuyển động quay của nam châm (rôto), suất điện động cảm ứng sẽ xuất hiện trong cuộn dây. Suất điện động này biến thiên điều hòa theo thời gian.<br>Cấu tạo của máy phát điện xoay chiều một pha gồm hai bộ phận chính:<br>+ Stato là phần cố định, chứa các cuộn dây, nơi sinh ra suất điện động cảm ứng.<br>+ Rôto là phần quay, có thể là nam châm hoặc cuộn dây, tạo ra từ trường biến thiên qua stato.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046908066-hinh-5.webp\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":416,"idx":6,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":2,"options":["chỉ lan truyền được trong chân không.","chỉ lan truyền trong các môi trường đàn hồi như rắn, lỏng, khí.","lan truyền được cả chân không và các môi trường vật chất.","không lan truyền được trong chân không."],"question":"Sóng điện từ","difficulty":"de","explanation":"Sóng điện từ có khả năng lan truyền trong nhiều môi trường, bao gồm cả chân không và các môi trường vật chất như chất khí, chất lỏng và chất rắn. Trong chân không, sóng điện từ truyền với tốc độ lớn nhất, khoảng 3×10<sup>8</sup> m/s.<br>Sử dụng các thông tin sau cho Câu 10 và Câu 11: Máy phát điện xoay chiều một pha hoạt động dựa trên hiện tượng cảm ứng điện từ. Khi một khung dây hoặc cuộn dây (stato) cắt qua từ trường biến thiên do chuyển động quay của nam châm (rôto), suất điện động cảm ứng sẽ xuất hiện trong cuộn dây. Suất điện động này biến thiên điều hòa theo thời gian.<br>Cấu tạo của máy phát điện xoay chiều một pha gồm hai bộ phận chính:<br>+ Stato là phần cố định, chứa các cuộn dây, nơi sinh ra suất điện động cảm ứng.<br>+ Rôto là phần quay, có thể là nam châm hoặc cuộn dây, tạo ra từ trường biến thiên qua stato.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046908066-hinh-5.webp\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1481700,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Các tia phóng xạ α, β, γ","answer":1,"options":["Tia γ.","Tia α.","Tia β+.","Tia β-."],"question":"Trong không khí, tia phóng xạ nào sau đây có tốc độ nhỏ nhất?","difficulty":"de","explanation":"Tia α chính là các hạt nhân He được phóng ra từ hạt nhân với tốc độ khoảng 2.10<sup>7</sup> m/s, trong khi đó các tia β-, β+ phóng ra với tốc độ rất lớn, có thể đạt xấp xỉ bằng tốc độ ánh sáng, tia γ là sóng điện từ có bước sóng cực ngắn, tốc độ 3.10<sup>8</sup> m/s<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":416,"idx":14,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Các tia phóng xạ α, β, γ","answer":1,"options":["Tia γ.","Tia α.","Tia β+.","Tia β-."],"question":"Trong không khí, tia phóng xạ nào sau đây có tốc độ nhỏ nhất?","difficulty":"de","explanation":"Tia α chính là các hạt nhân He được phóng ra từ hạt nhân với tốc độ khoảng 2.10<sup>7</sup> m/s, trong khi đó các tia β-, β+ phóng ra với tốc độ rất lớn, có thể đạt xấp xỉ bằng tốc độ ánh sáng, tia γ là sóng điện từ có bước sóng cực ngắn, tốc độ 3.10<sup>8</sup> m/s<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1481728,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["7.10<sup>−14</sup> N.","3,5.10<sup>−14</sup> N.","4.10<sup>−14</sup> N.","2.10<sup>−14</sup> N."],"question":"Một electron trong đèn hình tivi kiểu cũ chuyển động về phía trước (Ox) với tốc độ v = 5.10<sup>6</sup> m/s. Bao quanh đèn hình có các cuộn dây tạo ra từ trường với cường độ B = 0,05 T nằm trong mặt phẳng xOy và hợp với Ox một góc α = 60° như hình vẽ. Trong từ trường, lực từ tác dụng lên điện tích q được xác định bởi f = |q|.v.B.sinα, với $\\alpha =\\left(\\vec{v};\\vec{B}\\right)$ . Độ lớn của lực từ tác dụng lên electron là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224541164-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:186.3px;height:auto\" />","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đề hiểu là $v=5\\cdot10^{6}$ m/s và các phương án $7\\cdot10^{-14}$, $3{,}5\\cdot10^{-14}$, $4\\cdot10^{-14}$, $2\\cdot10^{-14}$ N (đề mất dấu mũ).</p><p class=\"text-base leading-relaxed my-2\">Lực từ lên điện tích chuyển động: $f=|q|vB\\sin\\alpha$ với $\\alpha$ là góc giữa $\\vec v$ (dọc Ox) và $\\vec B$, $|q|=1{,}6\\cdot10^{-19}$ C.</p><p class=\"text-base leading-relaxed my-2\">$f=1{,}6\\cdot10^{-19}\\cdot5\\cdot10^{6}\\cdot0{,}05\\cdot\\sin60^\\circ\\approx3{,}46\\cdot10^{-14}$ N, gần nhất là $3{,}5\\cdot10^{-14}$ N.</p><p class=\"text-base leading-relaxed my-2\">Không đúng vì: C ($4\\cdot10^{-14}$ N) là $|q|vB$ với $\\sin\\alpha=1$, quên thừa số $\\sin60^\\circ$; D ($2\\cdot10^{-14}$ N) bằng $4\\cdot10^{-14}\\cdot\\cos60^\\circ$, tức dùng cos thay cho sin; A ($7\\cdot10^{-14}$ N) lớn hơn cả giá trị cực đại $4\\cdot10^{-14}$ N nên không thể xảy ra.</p><p class=\"text-base leading-relaxed my-2\">Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":417,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tính lực từ F = BIl·sinθ","answer":1,"options":["7.10<sup>−14</sup> N.","3,5.10<sup>−14</sup> N.","4.10<sup>−14</sup> N.","2.10<sup>−14</sup> N."],"question":"Một electron trong đèn hình tivi kiểu cũ chuyển động về phía trước (Ox) với tốc độ v = 5.10<sup>6</sup> m/s. Bao quanh đèn hình có các cuộn dây tạo ra từ trường với cường độ B = 0,05 T nằm trong mặt phẳng xOy và hợp với Ox một góc α = 60° như hình vẽ. Trong từ trường, lực từ tác dụng lên điện tích q được xác định bởi f = |q|.v.B.sinα, với $\\alpha =\\left(\\vec{v};\\vec{B}\\right)$ . Độ lớn của lực từ tác dụng lên electron là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224541164-hinh-5.png\" alt=\"Hình 5\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:186.3px;height:auto\" />","difficulty":"de","explanation":"$f=\\left|q\\right|vB.sin\\alpha =1,6.10^{−19}.5.10^6.0,05.sin60=3,46.10^{−14}B$","difficultySource":"ai"}}]},{"id":1481738,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cấu trúc hạt nhân","answer":"78","question":"Đồng vị phóng xạ β- xenon  ${}_{54}^{133}{Xe}$ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Mỗi hạt nhân xenon  ${}_{54}^{133}{Xe}$ phân rã tạo thành một hạt nhân cesium, một hạt β- và một hạt ${}_0^0v$ . Chu kì bán rã của xenon  ${}_{54}^{133}{Xe}$  là T = 5,24 ngày. Một mẫu khí chứa xenon  ${}_{54}^{133}{Xe}$ được sản xuất tại nhà máy có độ phóng xạ H0 = 6,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện và sử dụng cho bệnh nhân sau đó 3 ngày.<br>Hạt nhân cesium có bao nhiêu neutron?","difficulty":"de","explanation":"${}_{54}^{133}{Xe}\\rightarrow_Z^ACs+_{−1}^0e+_0^0v$<br>$\\left\\{\\begin{aligned}153=A+0 <br>54=Z−1\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=133 <br>Z=55\\end{aligned}\\right.\\Rightarrow N=A−Z=133−5=78$","difficultySource":"ai"},"ex":[{"exam":417,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Cấu trúc hạt nhân","answer":"78","question":"Đồng vị phóng xạ β- xenon  ${}_{54}^{133}{Xe}$ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Mỗi hạt nhân xenon  ${}_{54}^{133}{Xe}$ phân rã tạo thành một hạt nhân cesium, một hạt β- và một hạt ${}_0^0v$ . Chu kì bán rã của xenon  ${}_{54}^{133}{Xe}$  là T = 5,24 ngày. Một mẫu khí chứa xenon  ${}_{54}^{133}{Xe}$ được sản xuất tại nhà máy có độ phóng xạ H0 = 6,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện và sử dụng cho bệnh nhân sau đó 3 ngày.<br>Hạt nhân cesium có bao nhiêu neutron?","difficulty":"de","explanation":"${}_{54}^{133}{Xe}\\rightarrow_Z^ACs+_{−1}^0e+_0^0v$<br>$\\left\\{\\begin{aligned}153=A+0 <br>54=Z−1\\end{aligned}\\right.\\Rightarrow \\left\\{\\begin{aligned}A=133 <br>Z=55\\end{aligned}\\right.\\Rightarrow N=A−Z=133−5=78$","difficultySource":"ai"}}]},{"id":1481739,"nq":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"4,2","question":"Đồng vị phóng xạ β- xenon  ${}_{54}^{133}{Xe}$ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Mỗi hạt nhân xenon  ${}_{54}^{133}{Xe}$ phân rã tạo thành một hạt nhân cesium, một hạt β- và một hạt ${}_0^0v$ . Chu kì bán rã của xenon  ${}_{54}^{133}{Xe}$  là T = 5,24 ngày. Một mẫu khí chứa xenon  ${}_{54}^{133}{Xe}$ được sản xuất tại nhà máy có độ phóng xạ H0 = 6,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện và sử dụng cho bệnh nhân sau đó 3 ngày.<br>Độ phóng xạ của mẫu xenon  ${}_{54}^{133}{Xe}$ khi bệnh nhân sử dụng là a.10<sup>9</sup> Bq. Giá trị của a bằng bao nhiêu?<br>(làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ của mẫu giảm theo định luật phóng xạ: $H = H_0 \\cdot 2^{-t/T}$, với $H_0$ là độ phóng xạ ban đầu, $t$ là thời gian kể từ lúc sản xuất, $T$ là chu kì bán rã.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $H_0 = 6{,}25.10^9$ Bq, $t = 3$ ngày, $T = 5{,}24$ ngày:</p><p class=\"text-base leading-relaxed my-2\">$H = 6{,}25.10^9 \\cdot 2^{-3/5{,}24}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H = 6{,}25.10^9 \\cdot 0{,}6724 \\approx 4{,}20.10^9$ Bq</p><p class=\"text-base leading-relaxed my-2\">Vậy $a \\approx 4{,}2$.</p>","difficultySource":"ai"},"ex":[{"exam":417,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Độ phóng xạ và bài toán xác định tuổi","answer":"4,2","question":"Đồng vị phóng xạ β- xenon  ${}_{54}^{133}{Xe}$ được sử dụng trong phương pháp nguyên tử đánh dấu của y học hạt nhân khi kiểm tra chức năng và chẩn đoán các bệnh về phổi. Mỗi hạt nhân xenon  ${}_{54}^{133}{Xe}$ phân rã tạo thành một hạt nhân cesium, một hạt β- và một hạt ${}_0^0v$ . Chu kì bán rã của xenon  ${}_{54}^{133}{Xe}$  là T = 5,24 ngày. Một mẫu khí chứa xenon  ${}_{54}^{133}{Xe}$ được sản xuất tại nhà máy có độ phóng xạ H0 = 6,25.10<sup>9</sup> Bq. Mẫu đó được vận chuyển về bệnh viện và sử dụng cho bệnh nhân sau đó 3 ngày.<br>Độ phóng xạ của mẫu xenon  ${}_{54}^{133}{Xe}$ khi bệnh nhân sử dụng là a.10<sup>9</sup> Bq. Giá trị của a bằng bao nhiêu?<br>(làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Độ phóng xạ của mẫu giảm theo định luật phóng xạ: $H = H_0 \\cdot 2^{-t/T}$, với $H_0$ là độ phóng xạ ban đầu, $t$ là thời gian kể từ lúc sản xuất, $T$ là chu kì bán rã.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $H_0 = 6{,}25.10^9$ Bq, $t = 3$ ngày, $T = 5{,}24$ ngày:</p><p class=\"text-base leading-relaxed my-2\">$H = 6{,}25.10^9 \\cdot 2^{-3/5{,}24}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow H = 6{,}25.10^9 \\cdot 0{,}6724 \\approx 4{,}20.10^9$ Bq</p><p class=\"text-base leading-relaxed my-2\">Vậy $a \\approx 4{,}2$.</p>","difficultySource":"ai"}}]},{"id":1481821,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"5,6","question":"Z là vùng không gian tồn tại một điện trường đều và một từ trường đều vuông góc với nhau ( $\\vec{E}\\perp \\vec{B}$ , hình vẽ). Độ lớn của cường độ điện trường là E = 2,80k V/m và độ lớn của cảm ứng từ là B = 0,500 T . Một ion dương có khối lượng m = 1,66.10<sup>−26</sup> kg, điện tích q = 1,60.10<sup>−19</sup>C chuyển động với vận tốc  $\\vec{v}$  vào vùng Z theo phương vuông góc với cảm ứng từ  $\\vec{B}$ . Lực từ tác dụng lên ion có độ lớn  $F=Bv\\left|q\\right|;$  có phương vuông góc với cảm ứng từ  $\\vec{B}$  và vận tốc  $\\vec{v}$ . Bỏ qua tác dụng của trọng lực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046989158-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Vận tốc v phải bằng bao nhiêu km/s để khi chuyển động qua vùng Z , ion không bị lệch so với phương ban đầu?","difficulty":"trung-binh","explanation":"Từ hình vẽ, bản tụ phía dưới tích điện dương (+), bản phía trên tích điện âm (-). Do đó, vectơ cường độ điện trường  $\\vec{E}$  có hướng từ dưới lên trên. Lực điện tác dụng lên ion dương  $\\vec{F}_d=q\\vec{E}$  cùng chiều với  $\\vec{E}$  nên hướng thẳng đứng lên trên.<br>Từ trường  $\\vec{B}$  có hướng từ trong ra ngoài mặt phẳng hình vẽ. Vận tốc  $\\vec{v}$ hướng từ trái sang phải. Áp dụng quy tắc bàn tay trái, lực từ (lực Lorentz)  $\\vec{F}_t$  hướng thẳng đứng xuống dưới.<br>Để ion không bị lệch, độ lớn lực điện và lực từ phải bằng nhau:<br>$F_d=F_t\\Leftrightarrow \\left|q\\right|E=\\left|q\\right|vB\\Rightarrow v=\\frac{E}{B}$<br>$\\begin{aligned}\\Rightarrow v=\\frac{2800}{0,500}=5600\\left(m/s\\right)=5,6 km/h <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"},"ex":[{"exam":425,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"5,6","question":"Z là vùng không gian tồn tại một điện trường đều và một từ trường đều vuông góc với nhau ( $\\vec{E}\\perp \\vec{B}$ , hình vẽ). Độ lớn của cường độ điện trường là E = 2,80k V/m và độ lớn của cảm ứng từ là B = 0,500 T . Một ion dương có khối lượng m = 1,66.10<sup>−26</sup> kg, điện tích q = 1,60.10<sup>−19</sup>C chuyển động với vận tốc  $\\vec{v}$  vào vùng Z theo phương vuông góc với cảm ứng từ  $\\vec{B}$ . Lực từ tác dụng lên ion có độ lớn  $F=Bv\\left|q\\right|;$  có phương vuông góc với cảm ứng từ  $\\vec{B}$  và vận tốc  $\\vec{v}$ . Bỏ qua tác dụng của trọng lực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046989158-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Vận tốc v phải bằng bao nhiêu km/s để khi chuyển động qua vùng Z , ion không bị lệch so với phương ban đầu?","difficulty":"trung-binh","explanation":"Từ hình vẽ, bản tụ phía dưới tích điện dương (+), bản phía trên tích điện âm (-). Do đó, vectơ cường độ điện trường  $\\vec{E}$  có hướng từ dưới lên trên. Lực điện tác dụng lên ion dương  $\\vec{F}_d=q\\vec{E}$  cùng chiều với  $\\vec{E}$  nên hướng thẳng đứng lên trên.<br>Từ trường  $\\vec{B}$  có hướng từ trong ra ngoài mặt phẳng hình vẽ. Vận tốc  $\\vec{v}$ hướng từ trái sang phải. Áp dụng quy tắc bàn tay trái, lực từ (lực Lorentz)  $\\vec{F}_t$  hướng thẳng đứng xuống dưới.<br>Để ion không bị lệch, độ lớn lực điện và lực từ phải bằng nhau:<br>$F_d=F_t\\Leftrightarrow \\left|q\\right|E=\\left|q\\right|vB\\Rightarrow v=\\frac{E}{B}$<br>$\\begin{aligned}\\Rightarrow v=\\frac{2800}{0,500}=5600\\left(m/s\\right)=5,6 km/h <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"}}]},{"id":1481822,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"1,16","question":"Z là vùng không gian tồn tại một điện trường đều và một từ trường đều vuông góc với nhau ( $\\vec{E}\\perp \\vec{B}$ , hình vẽ). Độ lớn của cường độ điện trường là E = 2,80k V/m và độ lớn của cảm ứng từ là B = 0,500 T . Một ion dương có khối lượng m = 1,66.10<sup>−26</sup> kg, điện tích q = 1,60.10<sup>−19</sup>C chuyển động với vận tốc  $\\vec{v}$  vào vùng Z theo phương vuông góc với cảm ứng từ  $\\vec{B}$ . Lực từ tác dụng lên ion có độ lớn  $F=Bv\\left|q\\right|;$  có phương vuông góc với cảm ứng từ  $\\vec{B}$  và vận tốc  $\\vec{v}$ . Bỏ qua tác dụng của trọng lực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046989158-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu vùng Z chỉ có từ trường, lực từ làm ion chuyển động trên một quỹ đạo tròn có bán kính là bao nhiêu mm (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Lực từ (lực Lorentz) tác dụng lên ion là:  $F_t=\\left|q\\right|vB$<br>Lực hướng tâm là:  $F_{ht}=m\\frac{v^2}{R}$<br>Ta có:  $\\left|q\\right|vB=m\\frac{v^2}{R}\\Rightarrow T=\\frac{mv}{\\left|qB\\right|}$<br>$\\begin{aligned}\\Rightarrow T=\\frac{1,66.10^{−26}.5600}{1,60.10^{−19}.0,5}=1,162.10^{−3}m\\approx 1,16mm <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":425,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"1,16","question":"Z là vùng không gian tồn tại một điện trường đều và một từ trường đều vuông góc với nhau ( $\\vec{E}\\perp \\vec{B}$ , hình vẽ). Độ lớn của cường độ điện trường là E = 2,80k V/m và độ lớn của cảm ứng từ là B = 0,500 T . Một ion dương có khối lượng m = 1,66.10<sup>−26</sup> kg, điện tích q = 1,60.10<sup>−19</sup>C chuyển động với vận tốc  $\\vec{v}$  vào vùng Z theo phương vuông góc với cảm ứng từ  $\\vec{B}$ . Lực từ tác dụng lên ion có độ lớn  $F=Bv\\left|q\\right|;$  có phương vuông góc với cảm ứng từ  $\\vec{B}$  và vận tốc  $\\vec{v}$ . Bỏ qua tác dụng của trọng lực.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046989158-hinh-8.png\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nếu vùng Z chỉ có từ trường, lực từ làm ion chuyển động trên một quỹ đạo tròn có bán kính là bao nhiêu mm (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"Lực từ (lực Lorentz) tác dụng lên ion là:  $F_t=\\left|q\\right|vB$<br>Lực hướng tâm là:  $F_{ht}=m\\frac{v^2}{R}$<br>Ta có:  $\\left|q\\right|vB=m\\frac{v^2}{R}\\Rightarrow T=\\frac{mv}{\\left|qB\\right|}$<br>$\\begin{aligned}\\Rightarrow T=\\frac{1,66.10^{−26}.5600}{1,60.10^{−19}.0,5}=1,162.10^{−3}m\\approx 1,16mm <br>Website: thukhoadaihoc.vn\\end{aligned}$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1482062,"nq":{"form":"bai_tap","type":"short_answer","topic":"Sự chuyển thể","answer":"1,1","question":"Khi lắp đặt các thanh ray của đường sắt, người ta luôn để một khoảng hở giữa hai thanh ray để bù vào sự nở dài của nó khi nhiệt độ tăng lên. Mỗi thanh ray đường sắt có chiều dài ban đầu ℓ0 = 10 m ở nhiệt độ t0 = 200C. Biết chiều dài thanh ray ở nhiệt độ t là ℓ = ℓ0[1 + α(t − t0)], với α = 11.10<sup>−6</sup> K−1 là hệ số nở của thép làm thanh ray.<br>Khi nhiệt độ của thanh ray tăng thêm một lượng 100C thì tỉ số giữa độ nở dài so với chiều dài ban đầu của nó bằng x.10<sup>−4</sup>. Giá trị của x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\frac{\\Delta ℓ}{ℓ_0}=\\frac{ℓ−ℓ_0}{ℓ_0}=\\frac{ℓ}{ℓ_0}−1=\\alpha \\left(t−t_0\\right)=11.10^{−6}.10=1,1.10^{−4}$","difficultySource":"ai"},"ex":[{"exam":447,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Sự chuyển thể","answer":"1,1","question":"Khi lắp đặt các thanh ray của đường sắt, người ta luôn để một khoảng hở giữa hai thanh ray để bù vào sự nở dài của nó khi nhiệt độ tăng lên. Mỗi thanh ray đường sắt có chiều dài ban đầu ℓ0 = 10 m ở nhiệt độ t0 = 200C. Biết chiều dài thanh ray ở nhiệt độ t là ℓ = ℓ0[1 + α(t − t0)], với α = 11.10<sup>−6</sup> K−1 là hệ số nở của thép làm thanh ray.<br>Khi nhiệt độ của thanh ray tăng thêm một lượng 100C thì tỉ số giữa độ nở dài so với chiều dài ban đầu của nó bằng x.10<sup>−4</sup>. Giá trị của x bằng bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\frac{\\Delta ℓ}{ℓ_0}=\\frac{ℓ−ℓ_0}{ℓ_0}=\\frac{ℓ}{ℓ_0}−1=\\alpha \\left(t−t_0\\right)=11.10^{−6}.10=1,1.10^{−4}$","difficultySource":"ai"}}]},{"id":1482063,"nq":{"form":"bai_tap","type":"short_answer","topic":"Sự chuyển thể","answer":"3,3","question":"Khi lắp đặt các thanh ray của đường sắt, người ta luôn để một khoảng hở giữa hai thanh ray để bù vào sự nở dài của nó khi nhiệt độ tăng lên. Mỗi thanh ray đường sắt có chiều dài ban đầu ℓ0 = 10 m ở nhiệt độ t0 = 200C. Biết chiều dài thanh ray ở nhiệt độ t là ℓ = ℓ0[1 + α(t − t0)], với α = 11.10<sup>−6</sup> K−1 là hệ số nở của thép làm thanh ray.<br>Khoảng cách tối thiểu giữa hai thanh ray bằng bao nhiêu mm để khi nhiệt độ tăng lên đến 500C thì vẫn còn đủ khoảng trống cho chúng nở ra (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\Delta ℓ=ℓ−ℓ_0=ℓ_0\\alpha \\left(t−t_0\\right)=10.11.10^{−6}.\\left(50−20\\right)=3,3.10^{−3}m=3,3\\left(mm\\right)$<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Bếp điện có ghi 220 V − 800 W được nối với điện áp không đổi 220 V, được dùng để đun sôi 2 lít nước ở 200C. Biết hiệu suất của bếp là H = 80%, nhiệt dung riêng của nước là 4200 J/kgK, khối lượng riêng của nước là 1000 kg/m3 và nước sôi ở 1000C.<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Bếp điện có ghi 220 V − 800 W được nối với điện áp không đổi 220 V, được dùng để đun sôi 2 lít nước ở 200C. Biết hiệu suất của bếp là H = 80%, nhiệt dung riêng của nước là 4200 J/kgK, khối lượng riêng của nước là 1000 kg/m3 và nước sôi ở 1000C.","difficultySource":"ai"},"ex":[{"exam":447,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Sự chuyển thể","answer":"3,3","question":"Khi lắp đặt các thanh ray của đường sắt, người ta luôn để một khoảng hở giữa hai thanh ray để bù vào sự nở dài của nó khi nhiệt độ tăng lên. Mỗi thanh ray đường sắt có chiều dài ban đầu ℓ0 = 10 m ở nhiệt độ t0 = 200C. Biết chiều dài thanh ray ở nhiệt độ t là ℓ = ℓ0[1 + α(t − t0)], với α = 11.10<sup>−6</sup> K−1 là hệ số nở của thép làm thanh ray.<br>Khoảng cách tối thiểu giữa hai thanh ray bằng bao nhiêu mm để khi nhiệt độ tăng lên đến 500C thì vẫn còn đủ khoảng trống cho chúng nở ra (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"de","explanation":"$\\Delta ℓ=ℓ−ℓ_0=ℓ_0\\alpha \\left(t−t_0\\right)=10.11.10^{−6}.\\left(50−20\\right)=3,3.10^{−3}m=3,3\\left(mm\\right)$<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Bếp điện có ghi 220 V − 800 W được nối với điện áp không đổi 220 V, được dùng để đun sôi 2 lít nước ở 200C. Biết hiệu suất của bếp là H = 80%, nhiệt dung riêng của nước là 4200 J/kgK, khối lượng riêng của nước là 1000 kg/m3 và nước sôi ở 1000C.<br>Sử dụng thông tin sau cho Câu 5 và Câu 6: Bếp điện có ghi 220 V − 800 W được nối với điện áp không đổi 220 V, được dùng để đun sôi 2 lít nước ở 200C. Biết hiệu suất của bếp là H = 80%, nhiệt dung riêng của nước là 4200 J/kgK, khối lượng riêng của nước là 1000 kg/m3 và nước sôi ở 1000C.","difficultySource":"ai"}}]},{"id":1482118,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"3,6","question":"Mặt Trời là nguồn năng lượng chính duy trì sự sống trên Trái Đất, với công suất phát xạ trung bình khoảng 4.10<sup>26</sup> W. Khoảng 90% năng lượng này đến từ chuỗi phản ứng tổng hợp hạt nhân proton − proton xảy ra ở lõi Mặt Trời, theo phương trình: $4p\\rightarrow_2^4He+2\\beta^++2v$ . Mỗi phản ứng như vậy giải phóng khoảng 26,7 MeV năng lượng, phần lớn dưới dạng động năng của các hạt sinh ra và một phần nhỏ dưới dạng neutrino v. Giả sử toàn bộ năng lượng từ Mặt Trời toả đều theo mọi hướng ra không gian dưới dạng bức xạ điện từ và neutrino. Khoảng cách trung bình từ Mặt Trời đến bề mặt Trái Đất là khoảng 1,5.10<sup>11</sup> m.<br>Năng lượng do chuỗi phản ứng tồng hợp hạt nhân proton-proton cung cấp trong mỗi giây bằng x.10<sup>26</sup> J.<br>Tìm giá trị của x.","difficulty":"de","explanation":"Năng lượng do chuỗi phản ứng tổng hợp hạt nhân proton-proton cung cấp trong mỗi giây bằng:<br>𝐸 = 90%.𝒫.𝑡 = 90%.4.1026.1 = 3,6.1026 J.<br>Vậy x = 3,6.","difficultySource":"ai"},"ex":[{"exam":449,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"3,6","question":"Mặt Trời là nguồn năng lượng chính duy trì sự sống trên Trái Đất, với công suất phát xạ trung bình khoảng 4.10<sup>26</sup> W. Khoảng 90% năng lượng này đến từ chuỗi phản ứng tổng hợp hạt nhân proton − proton xảy ra ở lõi Mặt Trời, theo phương trình: $4p\\rightarrow_2^4He+2\\beta^++2v$ . Mỗi phản ứng như vậy giải phóng khoảng 26,7 MeV năng lượng, phần lớn dưới dạng động năng của các hạt sinh ra và một phần nhỏ dưới dạng neutrino v. Giả sử toàn bộ năng lượng từ Mặt Trời toả đều theo mọi hướng ra không gian dưới dạng bức xạ điện từ và neutrino. Khoảng cách trung bình từ Mặt Trời đến bề mặt Trái Đất là khoảng 1,5.10<sup>11</sup> m.<br>Năng lượng do chuỗi phản ứng tồng hợp hạt nhân proton-proton cung cấp trong mỗi giây bằng x.10<sup>26</sup> J.<br>Tìm giá trị của x.","difficulty":"de","explanation":"Năng lượng do chuỗi phản ứng tổng hợp hạt nhân proton-proton cung cấp trong mỗi giây bằng:<br>𝐸 = 90%.𝒫.𝑡 = 90%.4.1026.1 = 3,6.1026 J.<br>Vậy x = 3,6.","difficultySource":"ai"}}]},{"id":1482119,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2,15","question":"Mặt Trời là nguồn năng lượng chính duy trì sự sống trên Trái Đất, với công suất phát xạ trung bình khoảng 4.10<sup>26</sup> W. Khoảng 90% năng lượng này đến từ chuỗi phản ứng tổng hợp hạt nhân proton − proton xảy ra ở lõi Mặt Trời, theo phương trình: $4p\\rightarrow_2^4He+2\\beta^++2v$ . Mỗi phản ứng như vậy giải phóng khoảng 26,7 MeV năng lượng, phần lớn dưới dạng động năng của các hạt sinh ra và một phần nhỏ dưới dạng neutrino v. Giả sử toàn bộ năng lượng từ Mặt Trời toả đều theo mọi hướng ra không gian dưới dạng bức xạ điện từ và neutrino. Khoảng cách trung bình từ Mặt Trời đến bề mặt Trái Đất là khoảng 1,5.10<sup>11</sup> m.<br>Trên mỗi mét vuông tại bề mặt Trái Đất nơi nhận được neutrino, trong mỗi giờ nhận được x.10<sup>18</sup> neutrino từ quá trình này. Tìm giá trị của x.","difficulty":"kho","explanation":"Năng lượng do chuỗi phản ứng tổng hợp hạt nhân proton-proton cung cấp trong mỗi giờ bằng 3600.E (J)<br>3600.𝐸<br>Số phản ứng tổng hợp hạt nhân proton-proton đã xảy ra trong mỗi giờ:  $N=\\frac{3600.E}{26,7.1,6.10^{−13}}$<br>Số hạt neutrino tạo thành: 2N<br>Năng lượng tỏa đều theo mọi hướng dưới dạng bức xạ điện từ và neutrino với diện tích mặt cầu là 𝑆 = 4𝜋𝑅2<br>Số hạt neutrino nhận được trên mỗi mét vuông tại bề mặt Trái Đất là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047198102-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> hạt.<br>Vậy, x = 2,15.","difficultySource":"ai"},"ex":[{"exam":449,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"2,15","question":"Mặt Trời là nguồn năng lượng chính duy trì sự sống trên Trái Đất, với công suất phát xạ trung bình khoảng 4.10<sup>26</sup> W. Khoảng 90% năng lượng này đến từ chuỗi phản ứng tổng hợp hạt nhân proton − proton xảy ra ở lõi Mặt Trời, theo phương trình: $4p\\rightarrow_2^4He+2\\beta^++2v$ . Mỗi phản ứng như vậy giải phóng khoảng 26,7 MeV năng lượng, phần lớn dưới dạng động năng của các hạt sinh ra và một phần nhỏ dưới dạng neutrino v. Giả sử toàn bộ năng lượng từ Mặt Trời toả đều theo mọi hướng ra không gian dưới dạng bức xạ điện từ và neutrino. Khoảng cách trung bình từ Mặt Trời đến bề mặt Trái Đất là khoảng 1,5.10<sup>11</sup> m.<br>Trên mỗi mét vuông tại bề mặt Trái Đất nơi nhận được neutrino, trong mỗi giờ nhận được x.10<sup>18</sup> neutrino từ quá trình này. Tìm giá trị của x.","difficulty":"kho","explanation":"Năng lượng do chuỗi phản ứng tổng hợp hạt nhân proton-proton cung cấp trong mỗi giờ bằng 3600.E (J)<br>3600.𝐸<br>Số phản ứng tổng hợp hạt nhân proton-proton đã xảy ra trong mỗi giờ:  $N=\\frac{3600.E}{26,7.1,6.10^{−13}}$<br>Số hạt neutrino tạo thành: 2N<br>Năng lượng tỏa đều theo mọi hướng dưới dạng bức xạ điện từ và neutrino với diện tích mặt cầu là 𝑆 = 4𝜋𝑅2<br>Số hạt neutrino nhận được trên mỗi mét vuông tại bề mặt Trái Đất là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047198102-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> hạt.<br>Vậy, x = 2,15.","difficultySource":"ai"}}]},{"id":1482146,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"4,1","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi một hạt nhân  ${}_{92}^{235}U$ phân hạch là 200 MeV. Biết một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Năng lượng tỏa ra khi 500 g  ${}_{92}^{235}U$ phân hạch là x.10<sup>13</sup> J. Tìm giá trị của x (Kết quả làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{92}^{235}U$  có trong 500 gam là:<br>$N=\\frac{m}{M}.N_A=\\frac{500}{235}.6,02.10^{23}\\approx 1,28085.10^{24}$  hạt<br>Năng lượng tỏa ra khi toàn bộ số hạt này phân hạch:<br>E = N.ΔE =1,28085.1024.200MeV  $\\approx$   4,0987.10<sup>13</sup> J.<br>So sánh với dạng x.10<sup>13</sup> J, ta có x  $\\approx$  4,1.","difficultySource":"ai"},"ex":[{"exam":451,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"4,1","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi một hạt nhân  ${}_{92}^{235}U$ phân hạch là 200 MeV. Biết một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Năng lượng tỏa ra khi 500 g  ${}_{92}^{235}U$ phân hạch là x.10<sup>13</sup> J. Tìm giá trị của x (Kết quả làm tròn kết quả đến chữ số hàng phần mười).","difficulty":"trung-binh","explanation":"Số hạt nhân  ${}_{92}^{235}U$  có trong 500 gam là:<br>$N=\\frac{m}{M}.N_A=\\frac{500}{235}.6,02.10^{23}\\approx 1,28085.10^{24}$  hạt<br>Năng lượng tỏa ra khi toàn bộ số hạt này phân hạch:<br>E = N.ΔE =1,28085.1024.200MeV  $\\approx$   4,0987.10<sup>13</sup> J.<br>So sánh với dạng x.10<sup>13</sup> J, ta có x  $\\approx$  4,1.","difficultySource":"ai"}}]},{"id":1482147,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"0,77","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi một hạt nhân  ${}_{92}^{235}U$ phân hạch là 200 MeV. Biết một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Một nhà máy điện hạt nhân sử dụng năng lượng từ các phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ trên để tạo ra điện năng. Biết công suất của nhà máy là 500 MW, hiệu suất của nhà máy là 25%. Lượng  ${}_{92}^{235}U$  tiêu thụ trong một năm là bao nhiêu tấn? (Kết quả làm tròn đến hàng phần trăm).","difficulty":"kho","explanation":"Thời gian 1 năm tính theo giây: t = 365.24.3600 = 31536000 s .<br>A = P.t = 500.106.31536000 =1,5768.10<sup>16</sup> J .<br>Vì hiệu suất nhà máy là H = 25% nên tổng năng lượng tỏa ra từ phản ứng phân hạch cần cung cấp là:<br>$Q=\\frac{A}{H}=\\frac{1,5768.10^{16}}{0,25}=6,3072.10^{16}J$<br>Số hạt nhân  ${}_{92}^{235}U$  cần phân hạch để cung cấp mức năng lượng này:<br>$N=\\frac{Q}{200.1,6.10^{−13}}=\\frac{6,3072.10^{16}}{3,2.10^{−11}}=1,971.10^{27}$  hạt<br>Khối lượng   ${}_{92}^{235}U$ tiêu thụ tương ứng là:<br>$m=\\frac{N}{N_A}.M=\\frac{1,971.10^{27}}{6,02.10^{23}}.235\\approx 769410g\\approx 769,41kg\\approx 0,77$  tấn","difficultySource":"ai"},"ex":[{"exam":451,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhà máy điện hạt nhân và phản ứng nhiệt hạch","answer":"0,77","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi một hạt nhân  ${}_{92}^{235}U$ phân hạch là 200 MeV. Biết một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$ là 235 g/mol.<br>Một nhà máy điện hạt nhân sử dụng năng lượng từ các phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ trên để tạo ra điện năng. Biết công suất của nhà máy là 500 MW, hiệu suất của nhà máy là 25%. Lượng  ${}_{92}^{235}U$  tiêu thụ trong một năm là bao nhiêu tấn? (Kết quả làm tròn đến hàng phần trăm).","difficulty":"kho","explanation":"Thời gian 1 năm tính theo giây: t = 365.24.3600 = 31536000 s .<br>A = P.t = 500.106.31536000 =1,5768.10<sup>16</sup> J .<br>Vì hiệu suất nhà máy là H = 25% nên tổng năng lượng tỏa ra từ phản ứng phân hạch cần cung cấp là:<br>$Q=\\frac{A}{H}=\\frac{1,5768.10^{16}}{0,25}=6,3072.10^{16}J$<br>Số hạt nhân  ${}_{92}^{235}U$  cần phân hạch để cung cấp mức năng lượng này:<br>$N=\\frac{Q}{200.1,6.10^{−13}}=\\frac{6,3072.10^{16}}{3,2.10^{−11}}=1,971.10^{27}$  hạt<br>Khối lượng   ${}_{92}^{235}U$ tiêu thụ tương ứng là:<br>$m=\\frac{N}{N_A}.M=\\frac{1,971.10^{27}}{6,02.10^{23}}.235\\approx 769410g\\approx 769,41kg\\approx 0,77$  tấn","difficultySource":"ai"}}]},{"id":1482182,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["6,2.10<sup>5</sup> Pa.","12,5.10<sup>5</sup> Pa.","3,1.10<sup>5</sup> Pa.","25,0.10<sup>5</sup> Pa."],"question":"Một mol khí hydrogen (xem là khí lí tưởng) thực hiện quá trình biến đổi từ trạng thái (1) sang trạng thái (2), được biểu diễn trên đồ thị như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047247101-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí ở trạng thái (1) xấp xỉ bằng","difficulty":"de","explanation":"Áp suất của khối khí ở trạng thái (1) là:<br>$p_1=p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.300}{2.{10}^{-3}}\\approx 12,5.{10}^5$  Pa.","difficultySource":"ai"},"ex":[{"exam":455,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Phương trình Clapeyron – Mendeleev","answer":1,"options":["6,2.10<sup>5</sup> Pa.","12,5.10<sup>5</sup> Pa.","3,1.10<sup>5</sup> Pa.","25,0.10<sup>5</sup> Pa."],"question":"Một mol khí hydrogen (xem là khí lí tưởng) thực hiện quá trình biến đổi từ trạng thái (1) sang trạng thái (2), được biểu diễn trên đồ thị như hình vẽ.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047247101-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất của khối khí ở trạng thái (1) xấp xỉ bằng","difficulty":"de","explanation":"Áp suất của khối khí ở trạng thái (1) là:<br>$p_1=p_2=\\frac{nRT_2}{V_2}=\\frac{1.8,31.300}{2.{10}^{-3}}\\approx 12,5.{10}^5$  Pa.","difficultySource":"ai"}}]},{"id":1482333,"nq":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"4,8","question":"Một electron chuyển động trong từ trường đều có độ lớn cảm ứng từ B = 3.105 T. Electron chỉ chịu tác dụng của lực từ và chuyển động đều theo quỹ đạo tròn có bán kính r = 0,91 m. Biết độ lớn lực từ tác dụng lên electron được xác định bởi biểu thức F = e.v.B (N). Trong đó, e = 1,6.10<sup>19</sup> (C) là độ lớn điện tích của electron và v (m/s) là tốc độ chuyển động của electron. Biết khối lượng của electron là 9,1.10<sup>31</sup> kg.<br>Tốc độ chuyển động của electron khi đó bằng x.10<sup>6</sup> m/s. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"trung-binh","explanation":"Vì electron chỉ chịu tác dụng của lực từ và chuyển động tròn đều nên ta có:<br>$F_{từ}=F_{hướng tâm}$    $e.v.B=m.\\frac{v^2}{r}$   $v=\\frac{r.e.B}{m}=\\frac{0,91.1,6.{10}^{-19}.3.{10}^{-5}}{9,1.{10}^{-31}}=4,8.{10}^6$  m/s.<br>Vậy x = 4,8.","difficultySource":"ai"},"ex":[{"exam":462,"idx":22,"el":{"form":"bai_tap","type":"short_answer","topic":"Lực từ. Cảm ứng từ","answer":"4,8","question":"Một electron chuyển động trong từ trường đều có độ lớn cảm ứng từ B = 3.105 T. Electron chỉ chịu tác dụng của lực từ và chuyển động đều theo quỹ đạo tròn có bán kính r = 0,91 m. Biết độ lớn lực từ tác dụng lên electron được xác định bởi biểu thức F = e.v.B (N). Trong đó, e = 1,6.10<sup>19</sup> (C) là độ lớn điện tích của electron và v (m/s) là tốc độ chuyển động của electron. Biết khối lượng của electron là 9,1.10<sup>31</sup> kg.<br>Tốc độ chuyển động của electron khi đó bằng x.10<sup>6</sup> m/s. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"trung-binh","explanation":"Vì electron chỉ chịu tác dụng của lực từ và chuyển động tròn đều nên ta có:<br>$F_{từ}=F_{hướng tâm}$    $e.v.B=m.\\frac{v^2}{r}$   $v=\\frac{r.e.B}{m}=\\frac{0,91.1,6.{10}^{-19}.3.{10}^{-5}}{9,1.{10}^{-31}}=4,8.{10}^6$  m/s.<br>Vậy x = 4,8.","difficultySource":"ai"}}]},{"id":1482334,"nq":{"form":"bai_tap","type":"short_answer","topic":"Chu kì và tần số của chuyển động tròn đều","answer":"1,2","question":"Một electron chuyển động trong từ trường đều có độ lớn cảm ứng từ B = 3.105 T. Electron chỉ chịu tác dụng của lực từ và chuyển động đều theo quỹ đạo tròn có bán kính r = 0,91 m. Biết độ lớn lực từ tác dụng lên electron được xác định bởi biểu thức F = e.v.B (N). Trong đó, e = 1,6.10<sup>19</sup> (C) là độ lớn điện tích của electron và v (m/s) là tốc độ chuyển động của electron. Biết khối lượng của electron là 9,1.10<sup>31</sup> kg.<br>Thời gian để electron chuyển động được một vòng tròn quỹ đạo bằng bao nhiêu microgiây (s)? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"trung-binh","explanation":"Thời gian để electron chuyển động được một vòng tròn quỹ đạo là:<br>$t=T=\\frac{2\\pi }{\\omega }$  và  $v=r.\\omega$    $t=\\frac{2\\pi .r}{v}=\\frac{2.3,14.0,91}{4,8.{10}^6}\\approx 1,2.{10}^{-6}s$  = 1,2 s.","difficultySource":"ai"},"ex":[{"exam":462,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Chu kì và tần số của chuyển động tròn đều","answer":"1,2","question":"Một electron chuyển động trong từ trường đều có độ lớn cảm ứng từ B = 3.105 T. Electron chỉ chịu tác dụng của lực từ và chuyển động đều theo quỹ đạo tròn có bán kính r = 0,91 m. Biết độ lớn lực từ tác dụng lên electron được xác định bởi biểu thức F = e.v.B (N). Trong đó, e = 1,6.10<sup>19</sup> (C) là độ lớn điện tích của electron và v (m/s) là tốc độ chuyển động của electron. Biết khối lượng của electron là 9,1.10<sup>31</sup> kg.<br>Thời gian để electron chuyển động được một vòng tròn quỹ đạo bằng bao nhiêu microgiây (s)? (Làm tròn kết quả đến chữ số hàng phần chục)","difficulty":"trung-binh","explanation":"Thời gian để electron chuyển động được một vòng tròn quỹ đạo là:<br>$t=T=\\frac{2\\pi }{\\omega }$  và  $v=r.\\omega$    $t=\\frac{2\\pi .r}{v}=\\frac{2.3,14.0,91}{4,8.{10}^6}\\approx 1,2.{10}^{-6}s$  = 1,2 s.","difficultySource":"ai"}}]},{"id":1492226,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["379,5 m/s.","219,1 m/s.","435,3 m/s.","424,3 m/s."],"question":"Chất khí có áp suất 1,2.10<sup>5</sup> Pa và khối lượng riêng 2,5 kg/m3 thì có tốc độ căn quân phương của phân tử là","difficulty":"de","explanation":"$p=\\frac{1}{3}Dv_C^2\\Rightarrow 1,2.10^5=\\frac{1}{3}.2,5.v_C^2\\Rightarrow v_c\\approx 379,8 \\Omega /s$","difficultySource":"ai"},"ex":[{"exam":262,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Liên hệ áp suất với động năng phân tử","answer":0,"options":["379,5 m/s.","219,1 m/s.","435,3 m/s.","424,3 m/s."],"question":"Chất khí có áp suất 1,2.10<sup>5</sup> Pa và khối lượng riêng 2,5 kg/m3 thì có tốc độ căn quân phương của phân tử là","difficulty":"de","explanation":"$p=\\frac{1}{3}Dv_C^2\\Rightarrow 1,2.10^5=\\frac{1}{3}.2,5.v_C^2\\Rightarrow v_c\\approx 379,8 \\Omega /s$","difficultySource":"ai"}}]},{"id":1493697,"nq":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"1,2","question":"Có 1 g khí Heli thực hiện một chu trình 1-2-3-4-1 được biểu diễn trên giản đồ P - T. Cho p0 = 1,38.10<sup>5</sup> Pa, T0 = 300 K. Công mà khí thực hiện trong giai đoạn 2, 1 đến 2 là bao nhiêu kJ (làm tròn kết quả đến chữ số phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224407931-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:200.9px;height:auto\" />","difficulty":"trung-binh","explanation":"Quá trình (1) → (2) là quá trình đẳng áp có  $T_2=2T_1\\Rightarrow V_2=2V_1=2V_0$  .<br>Công mà khối khí thực hiện trong giai đoạn 1 đến 2 là:<br>$A_{12}=p_1\\left(V_2−V_1\\right)=2p_0V_0=2\\frac{m}{\\mu }RT_0=2.\\frac{1}{4}.8,31.300=1246,5\\left(J\\right)\\approx 1,2\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":315,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Vận dụng phương trình trạng thái","answer":"1,2","question":"Có 1 g khí Heli thực hiện một chu trình 1-2-3-4-1 được biểu diễn trên giản đồ P - T. Cho p0 = 1,38.10<sup>5</sup> Pa, T0 = 300 K. Công mà khí thực hiện trong giai đoạn 2, 1 đến 2 là bao nhiêu kJ (làm tròn kết quả đến chữ số phần mười)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224407931-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:200.9px;height:auto\" />","difficulty":"trung-binh","explanation":"Quá trình (1) → (2) là quá trình đẳng áp có  $T_2=2T_1\\Rightarrow V_2=2V_1=2V_0$  .<br>Công mà khối khí thực hiện trong giai đoạn 1 đến 2 là:<br>$A_{12}=p_1\\left(V_2−V_1\\right)=2p_0V_0=2\\frac{m}{\\mu }RT_0=2.\\frac{1}{4}.8,31.300=1246,5\\left(J\\right)\\approx 1,2\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":1495109,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Đồ thị hình bên biểu diễn quá trình biến đổi trạng thái của một khối khí lí tưởng xác định. Biết thể tích khí ở trạng thái (1) là 10 lít.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224477356-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:204.9px;height:auto\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (1) đến trạng thái (3) bằng quá trình đẳng áp và quá trình đẳng nhiệt.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (2) là 900K.","answer":true},{"text":"Thể tích khối khí khi áp suất có giá trị 4.10<sup>5</sup> pa là 20 lít.","answer":false},{"text":"Khối khí có thể biến đổi trực tiếp từ trạng thái (1) đến trạng thái (2) bằng quá trình đẳng tích.","answer":false}],"explanation":"a) đúng<br>Từ (1) đến (2) là đẳng áp, (2) đến (3) là đẳng nhiệt<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Đề bài không cho chặt chẽ câu từ<br>b) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296081-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất không đổi. Nhiệt độ tăng bao nhiêu, thể tích tăng bấy nhiêu<br>Từ đồ thị: 900K<br>c) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296254-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\frac{p_1V_1}{T_1}=\\frac{p_4V_4}{T_4}\\Rightarrow \\frac{2.10}{300}=\\frac{4.V_4}{900}\\Rightarrow V_4=15\\left(lit\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Từ (1) sang (2): Đẳng áp","difficultySource":"ai"},"ex":[{"exam":366,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Đồ thị hình bên biểu diễn quá trình biến đổi trạng thái của một khối khí lí tưởng xác định. Biết thể tích khí ở trạng thái (1) là 10 lít.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224477356-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:204.9px;height:auto\" />","difficulty":"kho","statements":[{"text":"Quá trình biến đổi từ trạng thái (1) đến trạng thái (3) bằng quá trình đẳng áp và quá trình đẳng nhiệt.","answer":true},{"text":"Nhiệt độ của khối khí ở trạng thái (2) là 900K.","answer":true},{"text":"Thể tích khối khí khi áp suất có giá trị 4.10<sup>5</sup> pa là 20 lít.","answer":false},{"text":"Khối khí có thể biến đổi trực tiếp từ trạng thái (1) đến trạng thái (2) bằng quá trình đẳng tích.","answer":false}],"explanation":"a) đúng<br>Từ (1) đến (2) là đẳng áp, (2) đến (3) là đẳng nhiệt<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Đề bài không cho chặt chẽ câu từ<br>b) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296081-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất không đổi. Nhiệt độ tăng bao nhiêu, thể tích tăng bấy nhiêu<br>Từ đồ thị: 900K<br>c) sai<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046296254-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>$\\frac{p_1V_1}{T_1}=\\frac{p_4V_4}{T_4}\\Rightarrow \\frac{2.10}{300}=\\frac{4.V_4}{900}\\Rightarrow V_4=15\\left(lit\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) sai<br>Từ (1) sang (2): Đẳng áp","difficultySource":"ai"}}]},{"id":1496285,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình vẽ bên mô tả sơ đồ một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg, tiết diện của thanh nén là 30 cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì ghế hạ xuống 12 cm khi ổn định. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và lấy g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046821709-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa","answer":false}],"explanation":"a) Sai. Khi ghế để trống, khối khí trong xi lanh chịu áp suất khí quyển CỘNG với áp suất do trọng lượng của mặt ghế và xi lanh (6 kg) đè lên pit-tông: p = p0 + mg/S = 10⁵ + (6.10)/(30.10⁻⁴) = 1,2.10⁵ Pa ≠ p0.<br>b) Đúng. Ghế hạ xuống nghĩa là học sinh đã ngồi lên làm thể tích khí trong xi lanh giảm (bị nén lại), nên khối khí nhận công từ bên ngoài.<br>c) Đúng. Gọi ℓ1 là chiều dài cột khí khi ghế trống (p1 = 1,2.10⁵ Pa) và ℓ2 = ℓ1 − 12 (cm) khi có học sinh ngồi, với p2 = 10⁵ + (60.10)/(30.10⁻⁴) = 3.10⁵ Pa. Áp dụng định luật Boyle: ℓ1.p1 = ℓ2.p2 ⇒ ℓ1.1,2 = (ℓ1−12).3 ⇒ ℓ1 = 20 cm.<br>d) Sai. Theo tính toán trên, khi học sinh ngồi lên ghế thì áp suất khí trong xi lanh là p2 = 3.10⁵ Pa, không phải 2.10⁵ Pa.<br>a) sai<br>Khi ghế để trống không có ai ngồi lên ghế chịu áp suất khí quyển và áp suất do trọng lượng của mặt ghế và xi lanh gây ra ở khối khí trong xi lanh<br>$p_k=10^5+\\frac{6.10}{30.10^{−4}}=1,2.10^5\\left(Pa\\right)$   $\\left(p=\\frac{F}{S}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Quá trình ghế hạ xuống → Mình đã ngồi lên rồi → khối khí nhận công và giảm thể tích khí ở trong xi lanh<br>c) đúng<br>Khi ghế để trống:  $ℓ_1;p_1=1,2.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khi ngồi lên ghế:  $ℓ_2=ℓ_1−12cm;p_2=10^5+\\frac{60.10}{30.10^{−4}}=3.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow Boyle:ℓ_1.p_1=ℓ_2.p_2\\Rightarrow ℓ_1.1,2=\\left(ℓ_1−12\\right).3\\Rightarrow ℓ_1=20cm$<br>d) sai<br>Khi học sinh ngồi lên ghế:  $p_2=3.10^5\\left(Pa\\right)$  (đã tính ở câu c)","difficultySource":"ai"},"ex":[{"exam":409,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng nhiệt và định luật Boyle","question":"Hình vẽ bên mô tả sơ đồ một chiếc ghế nâng hạ bằng khí thông qua chuyển động lên xuống của xi lanh nối với mặt ghế. Thanh nén khí cố định trên đế bịt kín một lượng khí lí tưởng trong xi lanh. Bỏ qua ma sát giữa thanh nén và xi lanh. Tổng khối lượng của mặt ghế và xi lanh là 6 kg, tiết diện của thanh nén là 30 cm2. Một học sinh nặng 54 kg ngồi lên ghế (hai chân để lơ lửng không chạm mặt sàn) thì ghế hạ xuống 12 cm khi ổn định. Coi nhiệt độ của khí trong xi lanh không đổi, áp suất khí quyển là 105 Pa và lấy g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046821709-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi ghế để trống, áp suất của khí trong xi lanh bằng áp suất khí quyển.","answer":false},{"text":"Quá trình ghế hạ xuống, khí trong xi lanh nhận công.","answer":true},{"text":"Khi ghế để trống, cột khí trong xi lanh dài 20 cm.","answer":true},{"text":"Khi học sinh ngồi trên ghế, áp suất của khí trong xi lanh là 2.10<sup>5</sup> Pa","answer":false}],"explanation":"a) Sai. Khi ghế để trống, khối khí trong xi lanh chịu áp suất khí quyển CỘNG với áp suất do trọng lượng của mặt ghế và xi lanh (6 kg) đè lên pit-tông: p = p0 + mg/S = 10⁵ + (6.10)/(30.10⁻⁴) = 1,2.10⁵ Pa ≠ p0.<br>b) Đúng. Ghế hạ xuống nghĩa là học sinh đã ngồi lên làm thể tích khí trong xi lanh giảm (bị nén lại), nên khối khí nhận công từ bên ngoài.<br>c) Đúng. Gọi ℓ1 là chiều dài cột khí khi ghế trống (p1 = 1,2.10⁵ Pa) và ℓ2 = ℓ1 − 12 (cm) khi có học sinh ngồi, với p2 = 10⁵ + (60.10)/(30.10⁻⁴) = 3.10⁵ Pa. Áp dụng định luật Boyle: ℓ1.p1 = ℓ2.p2 ⇒ ℓ1.1,2 = (ℓ1−12).3 ⇒ ℓ1 = 20 cm.<br>d) Sai. Theo tính toán trên, khi học sinh ngồi lên ghế thì áp suất khí trong xi lanh là p2 = 3.10⁵ Pa, không phải 2.10⁵ Pa.<br>a) sai<br>Khi ghế để trống không có ai ngồi lên ghế chịu áp suất khí quyển và áp suất do trọng lượng của mặt ghế và xi lanh gây ra ở khối khí trong xi lanh<br>$p_k=10^5+\\frac{6.10}{30.10^{−4}}=1,2.10^5\\left(Pa\\right)$   $\\left(p=\\frac{F}{S}\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) đúng<br>Quá trình ghế hạ xuống → Mình đã ngồi lên rồi → khối khí nhận công và giảm thể tích khí ở trong xi lanh<br>c) đúng<br>Khi ghế để trống:  $ℓ_1;p_1=1,2.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Khi ngồi lên ghế:  $ℓ_2=ℓ_1−12cm;p_2=10^5+\\frac{60.10}{30.10^{−4}}=3.10^5\\left(Pa\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\Rightarrow Boyle:ℓ_1.p_1=ℓ_2.p_2\\Rightarrow ℓ_1.1,2=\\left(ℓ_1−12\\right).3\\Rightarrow ℓ_1=20cm$<br>d) sai<br>Khi học sinh ngồi lên ghế:  $p_2=3.10^5\\left(Pa\\right)$  (đã tính ở câu c)","difficultySource":"ai"}}]},{"id":1496313,"nq":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Một học sinh sử dụng bộ thí nghiệm như hình 1 để tiến hành thí nghiệm khảo sát thể tích của một lượng khí xác định theo nhiệt độ của nó ở áp suất không đổi 1,5 bar (1 bar = 105 Pa). Học sinh này thu được kết quả như bảng sau:<br>Thể tích V (ml)\t2,8\t2,6\t2,4<br>Nhiệt độ T (K)\t350\t325\t300<br>Hình 1<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046833037-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224525007-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:174.3px;height:auto\" />","difficulty":"kho","statements":[{"text":"Số mol khí sử dụng trong thí nghiệm là 1,20.10<sup>−4</sup> mol","answer":false},{"text":"Giá trị trung bình của tỉ số V/T là 6.10<sup>−3</sup> (ml/K).","answer":false},{"text":"Đồ thị biểu diễn mối liên hệ giữa V và T có dạng như hình 2.","answer":true},{"text":"Thể tích tỉ lệ thuận với nhiệt độ tuyệt đối.","answer":true}],"explanation":"a) Sai. Từ pV = nRT ⇒ n = pV/(RT); vì áp suất không đổi p = 1,5.10⁵ Pa và tỉ số V/T không đổi (≈ 8.10⁻³ ml/K = 8.10⁻⁹ m³/K) ⇒ n = 1,5.10⁵.8.10⁻⁹/8,31 ≈ 1,44.10⁻⁴ mol, không phải 1,20.10⁻⁴ mol.<br>b) Sai. Tính trung bình: (2,8/350 + 2,6/325 + 2,4/300)/3 = (0,008+0,008+0,008)/3 = 8.10⁻³ (ml/K), không phải 6.10⁻³ (ml/K).<br>c) Đúng. Ở áp suất không đổi (đẳng áp), đồ thị V theo T tuyệt đối là một đường thẳng đi qua gốc tọa độ, đúng như dạng ở Hình 2.<br>d) Đúng. Theo định luật Gay-Lussac (Charles), khi áp suất một khối lượng khí xác định không đổi thì thể tích tỉ lệ thuận với nhiệt độ tuyệt đối: V/T = hằng số.<br>a) sai<br>$pV=nRT\\Rightarrow p.\\frac{V}{T}:R=n$<br>$1,5.10^5.\\frac{1}{125}.10^{−6}:8,31=n\\Rightarrow n=1,44.10^{−4}\\left(mol\\right)$   $\\left(1m^3=10^6mℓ\\right)$<br>b) sai<br>$\\overline{\\frac{V}{T}}=\\frac{1}{3}.\\left(\\frac{2,8}{350}+\\frac{2,6}{325}+\\frac{2,4}{300}\\right)=\\frac{1}{125}\\left(ml/K\\right)=8.10^{−3}\\left(ml/K\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Đẳng áp, V và nhiệt độ tuyệt đối T liên hệ với nhau là đường thẳng đi qua gốc toạ độ O<br>d) đúng<br>Định luật Charles<br>- Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó:  $\\frac{V}{T}=const$","difficultySource":"ai"},"ex":[{"exam":410,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Quá trình đẳng áp và định luật Charles","question":"Một học sinh sử dụng bộ thí nghiệm như hình 1 để tiến hành thí nghiệm khảo sát thể tích của một lượng khí xác định theo nhiệt độ của nó ở áp suất không đổi 1,5 bar (1 bar = 105 Pa). Học sinh này thu được kết quả như bảng sau:<br>Thể tích V (ml)\t2,8\t2,6\t2,4<br>Nhiệt độ T (K)\t350\t325\t300<br>Hình 1<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046833037-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224525007-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:174.3px;height:auto\" />","difficulty":"kho","statements":[{"text":"Số mol khí sử dụng trong thí nghiệm là 1,20.10<sup>−4</sup> mol","answer":false},{"text":"Giá trị trung bình của tỉ số V/T là 6.10<sup>−3</sup> (ml/K).","answer":false},{"text":"Đồ thị biểu diễn mối liên hệ giữa V và T có dạng như hình 2.","answer":true},{"text":"Thể tích tỉ lệ thuận với nhiệt độ tuyệt đối.","answer":true}],"explanation":"a) Sai. Từ pV = nRT ⇒ n = pV/(RT); vì áp suất không đổi p = 1,5.10⁵ Pa và tỉ số V/T không đổi (≈ 8.10⁻³ ml/K = 8.10⁻⁹ m³/K) ⇒ n = 1,5.10⁵.8.10⁻⁹/8,31 ≈ 1,44.10⁻⁴ mol, không phải 1,20.10⁻⁴ mol.<br>b) Sai. Tính trung bình: (2,8/350 + 2,6/325 + 2,4/300)/3 = (0,008+0,008+0,008)/3 = 8.10⁻³ (ml/K), không phải 6.10⁻³ (ml/K).<br>c) Đúng. Ở áp suất không đổi (đẳng áp), đồ thị V theo T tuyệt đối là một đường thẳng đi qua gốc tọa độ, đúng như dạng ở Hình 2.<br>d) Đúng. Theo định luật Gay-Lussac (Charles), khi áp suất một khối lượng khí xác định không đổi thì thể tích tỉ lệ thuận với nhiệt độ tuyệt đối: V/T = hằng số.<br>a) sai<br>$pV=nRT\\Rightarrow p.\\frac{V}{T}:R=n$<br>$1,5.10^5.\\frac{1}{125}.10^{−6}:8,31=n\\Rightarrow n=1,44.10^{−4}\\left(mol\\right)$   $\\left(1m^3=10^6mℓ\\right)$<br>b) sai<br>$\\overline{\\frac{V}{T}}=\\frac{1}{3}.\\left(\\frac{2,8}{350}+\\frac{2,6}{325}+\\frac{2,4}{300}\\right)=\\frac{1}{125}\\left(ml/K\\right)=8.10^{−3}\\left(ml/K\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>c) đúng<br>Đẳng áp, V và nhiệt độ tuyệt đối T liên hệ với nhau là đường thẳng đi qua gốc toạ độ O<br>d) đúng<br>Định luật Charles<br>- Khi áp suất của một khối lượng khí xác định giữ không đổi thì thể tích của khí tỉ lệ thuận với nhiệt độ tuyệt đối của nó:  $\\frac{V}{T}=const$","difficultySource":"ai"}}]},{"id":1496416,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":1,"options":["12.103 V.","1,2.10<sup>3</sup> V.","2,2.10<sup>3</sup> V.","22.103 V."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 60 cm2 được đặt trong một từ trường đều có B = 0,2 T. Trong 0,5 s vòng dây quay đều được một góc 60° như hình bên. Độ lớn suất điện động cảm ứng trong vòng dây là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224531863-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:245.4px;height:auto\" />","difficulty":"trung-binh","explanation":"Độ lớn suất điện động cảm ứng trong vòng dây là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|e_c\\right|=\\left|\\frac{\\Delta }{\\Delta t}\\right|=\\left|\\frac{{}_2-{}_1}{\\Delta t}\\right|=\\left|\\frac{NBS.\\cos\\left(\\alpha_2\\right)-NBS.\\cos\\left(\\alpha_1\\right)}{\\Delta t}\\right|$<br>$\\left|e_c\\right|=\\left|\\frac{1.0,2.60.{10}^{-4}.\\cos\\left(60^{\\circ}\\right)-1.0,2.60.{10}^{-4}.\\cos\\left(0^{\\circ}\\right)}{0,5}\\right|=1,2.{10}^{-3} V$ .","difficultySource":"ai"},"ex":[{"exam":414,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":1,"options":["12.103 V.","1,2.10<sup>3</sup> V.","2,2.10<sup>3</sup> V.","22.103 V."],"question":"Một vòng dây dẫn phẳng hình tròn có diện tích S = 60 cm2 được đặt trong một từ trường đều có B = 0,2 T. Trong 0,5 s vòng dây quay đều được một góc 60° như hình bên. Độ lớn suất điện động cảm ứng trong vòng dây là<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224531863-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:245.4px;height:auto\" />","difficulty":"trung-binh","explanation":"Độ lớn suất điện động cảm ứng trong vòng dây là:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\left|e_c\\right|=\\left|\\frac{\\Delta }{\\Delta t}\\right|=\\left|\\frac{{}_2-{}_1}{\\Delta t}\\right|=\\left|\\frac{NBS.\\cos\\left(\\alpha_2\\right)-NBS.\\cos\\left(\\alpha_1\\right)}{\\Delta t}\\right|$<br>$\\left|e_c\\right|=\\left|\\frac{1.0,2.60.{10}^{-4}.\\cos\\left(60^{\\circ}\\right)-1.0,2.60.{10}^{-4}.\\cos\\left(0^{\\circ}\\right)}{0,5}\\right|=1,2.{10}^{-3} V$ .","difficultySource":"ai"}}]},{"id":1496445,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 00C đến khi tan chảy hết thành nước và hóa hơi ở 1000C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lấy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup>J/Kg và nhiệt dung riêng của nước đá là 4200J/Kg.K, nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup>J/Kg, bỏ qua nhiệt dung của nhiệt lượng kế.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224535699-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:203.6px;height:auto\" />","difficulty":"kho","statements":[{"text":"Nếu tiến hành đun đến khi lượng nước bay hơi hết cần cung cấp nhiệt lượng tổng cộng là 325KJ.","answer":false},{"text":"Tại điểm B trên đồ thị, nước bắt đầu xảy ra sự sôi.","answer":true},{"text":"Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi.","answer":true},{"text":"Tại điểm C lượng nước còn lại là 96g.","answer":true}],"explanation":"a) sai<br>Giai đoạn:<br>$O\\rightarrow A:$  Nóng chảy → Cần cung cấp một nhiệt lượng mλ<br>$A\\rightarrow B:$  Tăng nhiệt → Cần cung cấp  $m.c.\\Delta t$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Tổng 2 giai đoạn:  $90.10^3=m\\lambda t+mc\\Delta t$<br>$90.10^3=m.3,3.10^5+m.4200.100\\Rightarrow m=0,12kg=120g$<br>$0,12.2,3.10^6=276kJ Website: thukhoadaihoc.vn$<br>$\\Rightarrow 90+276=366kJ$<br>b) đúng<br>Tại điểm B trên đồ thị, nước bắt đầu xảy ra sự sôi<br>c) đúng<br>Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi → là quá trình sôi<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Từ  $B\\rightarrow C:\\left(145,2−90\\right).10^3=55,2.10^3=m^/.2,3.10^6\\Rightarrow m^/=0,024kg=24g$<br>Còn lại:  $120gam−24gam=96gam$","difficultySource":"ai"},"ex":[{"exam":415,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một học sinh tiến hành đun một khối nước đá đựng trong nhiệt lượng kế từ 00C đến khi tan chảy hết thành nước và hóa hơi ở 1000C. Hình bên là đồ thị biểu diễn sự phụ thuộc của nhiệt lượng mà khối nước đá nhận được từ lúc đun đến lúc bay hơi và sự thay đổi nhiệt độ của nó. Lấy nhiệt nóng chảy riêng của nước đá là 3,3.10<sup>5</sup>J/Kg và nhiệt dung riêng của nước đá là 4200J/Kg.K, nhiệt hóa hơi riêng của nước là 2,3.10<sup>6</sup>J/Kg, bỏ qua nhiệt dung của nhiệt lượng kế.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224535699-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:203.6px;height:auto\" />","difficulty":"kho","statements":[{"text":"Nếu tiến hành đun đến khi lượng nước bay hơi hết cần cung cấp nhiệt lượng tổng cộng là 325KJ.","answer":false},{"text":"Tại điểm B trên đồ thị, nước bắt đầu xảy ra sự sôi.","answer":true},{"text":"Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi.","answer":true},{"text":"Tại điểm C lượng nước còn lại là 96g.","answer":true}],"explanation":"a) sai<br>Giai đoạn:<br>$O\\rightarrow A:$  Nóng chảy → Cần cung cấp một nhiệt lượng mλ<br>$A\\rightarrow B:$  Tăng nhiệt → Cần cung cấp  $m.c.\\Delta t$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Tổng 2 giai đoạn:  $90.10^3=m\\lambda t+mc\\Delta t$<br>$90.10^3=m.3,3.10^5+m.4200.100\\Rightarrow m=0,12kg=120g$<br>$0,12.2,3.10^6=276kJ Website: thukhoadaihoc.vn$<br>$\\Rightarrow 90+276=366kJ$<br>b) đúng<br>Tại điểm B trên đồ thị, nước bắt đầu xảy ra sự sôi<br>c) đúng<br>Trong đoạn BC trên đồ thị, khối nước nhận nhiệt lượng để thực hiện quá trình hóa hơi → là quá trình sôi<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>d) đúng<br>Từ  $B\\rightarrow C:\\left(145,2−90\\right).10^3=55,2.10^3=m^/.2,3.10^6\\Rightarrow m^/=0,024kg=24g$<br>Còn lại:  $120gam−24gam=96gam$","difficultySource":"ai"}}]},{"id":1496641,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"1,3","question":"Để thuận tiện rút thuốc từ lọ thuốc kín, y tá thường sử dụng ống tiêm để bơm một lượng nhỏ khí vào lọ thuốc như hình vẽ, một chai thuốc có thể tích 0,9 ml và chứa 0,5 ml thuốc, áp suất của khí trong lọ là 105 Pa. Một lượng khí trong ống tiêm có tiết diện 0,3 cm2 dài 0,4 cm và áp suất 105 Pa được y tá bơm vào lọ thuốc. Biết nhiệt độ bên trong và bên ngoài lọ thuốc bằng nhau và không thay đổi. Áp suất của lượng khí mới trong lọ thuốc là a.10<sup>5</sup> Pa. Tìm a. Làm tròn 1 chữ số thập phân sau dấu phẩy.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224554884-hinh-25.png\" alt=\"Hình 25\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:98.9px;height:auto\" />","difficulty":"trung-binh","explanation":"Thuốc rất là khó nén  $\\Rightarrow V_K=const$<br>$V_K=0,9−0,5=0,4 ml$<br>Thể tích ống bơm:  $V_b=Sℓ=0,3.0,4=0,12\\left(cm^3\\right)=0,12\\left(ml\\right)$<br>$T=const;$<br>$V_K.p_0+V_b.p_0=p^/V_K$<br>$\\Rightarrow 0,4.10^5+0,12.10^5=p^/.0,4$<br>$\\Rightarrow p^/=1,3.10^5\\left(Pa\\right)$","difficultySource":"ai"},"ex":[{"exam":422,"idx":21,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Boyle. Định luật Charles","answer":"1,3","question":"Để thuận tiện rút thuốc từ lọ thuốc kín, y tá thường sử dụng ống tiêm để bơm một lượng nhỏ khí vào lọ thuốc như hình vẽ, một chai thuốc có thể tích 0,9 ml và chứa 0,5 ml thuốc, áp suất của khí trong lọ là 105 Pa. Một lượng khí trong ống tiêm có tiết diện 0,3 cm2 dài 0,4 cm và áp suất 105 Pa được y tá bơm vào lọ thuốc. Biết nhiệt độ bên trong và bên ngoài lọ thuốc bằng nhau và không thay đổi. Áp suất của lượng khí mới trong lọ thuốc là a.10<sup>5</sup> Pa. Tìm a. Làm tròn 1 chữ số thập phân sau dấu phẩy.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224554884-hinh-25.png\" alt=\"Hình 25\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:98.9px;height:auto\" />","difficulty":"trung-binh","explanation":"Thuốc rất là khó nén  $\\Rightarrow V_K=const$<br>$V_K=0,9−0,5=0,4 ml$<br>Thể tích ống bơm:  $V_b=Sℓ=0,3.0,4=0,12\\left(cm^3\\right)=0,12\\left(ml\\right)$<br>$T=const;$<br>$V_K.p_0+V_b.p_0=p^/V_K$<br>$\\Rightarrow 0,4.10^5+0,12.10^5=p^/.0,4$<br>$\\Rightarrow p^/=1,3.10^5\\left(Pa\\right)$","difficultySource":"ai"}}]},{"id":1497166,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":3,"options":["1,2.10<sup>−4</sup> Wb","1,2.10<sup>−6</sup> Wb","2,4.10<sup>−6</sup> Wb","2,4.10<sup>−4</sup>Wb"],"question":"Một khung dây phẳng diện tích 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ hợp với vectơ pháp tuyến của mặt phẳng khung dây một góc 600 và có độ lớn 0,12 T . Từ thông qua khung dây này là","difficulty":"de","explanation":"Đổi đơn vị:  $S=40cm^2=40.10^{−4}m^2$<br>Từ thông qua khung dây là:<br>$\\Phi =BScos\\alpha =0,12.40.10^{−4}.cos(60^0)=2,4.10^{−4}Wb$","difficultySource":"ai"},"ex":[{"exam":442,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":3,"options":["1,2.10<sup>−4</sup> Wb","1,2.10<sup>−6</sup> Wb","2,4.10<sup>−6</sup> Wb","2,4.10<sup>−4</sup>Wb"],"question":"Một khung dây phẳng diện tích 40 cm2 đặt trong từ trường đều có vectơ cảm ứng từ hợp với vectơ pháp tuyến của mặt phẳng khung dây một góc 600 và có độ lớn 0,12 T . Từ thông qua khung dây này là","difficulty":"de","explanation":"Đổi đơn vị:  $S=40cm^2=40.10^{−4}m^2$<br>Từ thông qua khung dây là:<br>$\\Phi =BScos\\alpha =0,12.40.10^{−4}.cos(60^0)=2,4.10^{−4}Wb$","difficultySource":"ai"}}]},{"id":1497510,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng đang ở trạng thái (1) có nhiệt độ 780 K biến đổi trạng thái được mô tả bởi đồ thị áp suất khí p phụ thuộc vào thể tích khí V như hình vẽ. Đường biểu diễn quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là một phần của đường hyperbol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047239790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở trạng thái (2), thể tích của khối khí là 6 lít.","answer":true},{"text":"Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) là quá trình đẳng tích.","answer":false},{"text":"Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là quá trình đẳng áp.","answer":false},{"text":"Ở trạng thái (1), nhiệt độ của khối khí là 5070C.","answer":true}],"explanation":"Từ đồ thị, ta xác định được các thông số trạng thái của khối khí:<br>Trạng thái (1): p1 = 6.10<sup>5</sup> Pa;V1 = 2 lít; T1 = 780 K .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trạng thái (2): p2 = 2.10<sup>5</sup> Pa;V2 = ?<br>Trạng thái (3): p3 = 2.10<sup>5</sup> Pa;V3 = 2 lít.<br>a) đúng<br>Quá trình biến đổi từ (1) sang (2) có đường biểu diễn là một phần của đường hyperbol trong hệ tọa độ p - V, do đó đây là quá trình đẳng nhiệt (T1 =T2 ).<br>Áp dụng định luật Boyle, ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>p1V1 = p2V2 → 6.105.2 = 2.10<sup>5</sup>.V2 → V2 = 6 (lít).<br>b) sai<br>Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có đường biểu diễn nằm ngang, vuông góc với trục tung p (áp suất không đổi p2 = p3 = 2.10<sup>5</sup> Pa ). Do đó, đây là quá trình đẳng áp, không phải đẳng tích. Quá trình (3) sang (1) mới là đẳng tích).<br>c) sai<br>Như đã phân tích ở ý a, đường biểu diễn (1) → (2) là hyperbol nên đây là quá trình đẳng nhiệt, không phải quá trình đẳng áp.<br>d) đúng<br>Ở trạng thái (1), nhiệt độ tuyệt đối của khối khí là T1 = 780 K .<br>Đổi sang thang nhiệt độ Celsius:  $t_1=780−273=507^0C$","difficultySource":"ai"},"ex":[{"exam":454,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một khối khí lí tưởng đang ở trạng thái (1) có nhiệt độ 780 K biến đổi trạng thái được mô tả bởi đồ thị áp suất khí p phụ thuộc vào thể tích khí V như hình vẽ. Đường biểu diễn quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là một phần của đường hyperbol.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791047239790-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Ở trạng thái (2), thể tích của khối khí là 6 lít.","answer":true},{"text":"Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) là quá trình đẳng tích.","answer":false},{"text":"Quá trình biến đổi từ trạng thái (1) sang trạng thái (2) là quá trình đẳng áp.","answer":false},{"text":"Ở trạng thái (1), nhiệt độ của khối khí là 5070C.","answer":true}],"explanation":"Từ đồ thị, ta xác định được các thông số trạng thái của khối khí:<br>Trạng thái (1): p1 = 6.10<sup>5</sup> Pa;V1 = 2 lít; T1 = 780 K .<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Trạng thái (2): p2 = 2.10<sup>5</sup> Pa;V2 = ?<br>Trạng thái (3): p3 = 2.10<sup>5</sup> Pa;V3 = 2 lít.<br>a) đúng<br>Quá trình biến đổi từ (1) sang (2) có đường biểu diễn là một phần của đường hyperbol trong hệ tọa độ p - V, do đó đây là quá trình đẳng nhiệt (T1 =T2 ).<br>Áp dụng định luật Boyle, ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>p1V1 = p2V2 → 6.105.2 = 2.10<sup>5</sup>.V2 → V2 = 6 (lít).<br>b) sai<br>Quá trình biến đổi từ trạng thái (2) sang trạng thái (3) có đường biểu diễn nằm ngang, vuông góc với trục tung p (áp suất không đổi p2 = p3 = 2.10<sup>5</sup> Pa ). Do đó, đây là quá trình đẳng áp, không phải đẳng tích. Quá trình (3) sang (1) mới là đẳng tích).<br>c) sai<br>Như đã phân tích ở ý a, đường biểu diễn (1) → (2) là hyperbol nên đây là quá trình đẳng nhiệt, không phải quá trình đẳng áp.<br>d) đúng<br>Ở trạng thái (1), nhiệt độ tuyệt đối của khối khí là T1 = 780 K .<br>Đổi sang thang nhiệt độ Celsius:  $t_1=780−273=507^0C$","difficultySource":"ai"}}]},{"id":1497771,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["Mỗi kilôgam đồng toả ra nhiệt lượng 1,8.10<sup>5</sup> J khi hoá lỏng hoàn toàn","Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy","Khối đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng","Khối đồng sẽ toả ra 1,8.10<sup>5</sup> J khi nóng chảy hoàn toàn"],"question":"Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg. Câu nào dưới đây là đúng?","difficulty":"de","explanation":"Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy","difficultySource":"ai"},"ex":[{"exam":464,"idx":8,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["Mỗi kilôgam đồng toả ra nhiệt lượng 1,8.10<sup>5</sup> J khi hoá lỏng hoàn toàn","Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy","Khối đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng","Khối đồng sẽ toả ra 1,8.10<sup>5</sup> J khi nóng chảy hoàn toàn"],"question":"Nhiệt nóng chảy riêng của đồng là 1,8.10<sup>5</sup> J/kg. Câu nào dưới đây là đúng?","difficulty":"de","explanation":"Mỗi kilôgam đồng cần thu nhiệt lượng 1,8.10<sup>5</sup> J để hoá lỏng hoàn toàn ở nhiệt độ nóng chảy","difficultySource":"ai"}}]},{"id":1504551,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực và trường hợp lực xiên góc","answer":0,"options":["1,2.10<sup>−20</sup> J.","1,2.10<sup>−14</sup> J.","1,2.10<sup>−17</sup> J.","1,2.10<sup>−11</sup> J."],"question":"Mỗi tế bào cơ trong cơ thể người có thể coi như một động cơ siêu nhỏ, khi con người hoạt động, tế bào cơ sử dụng năng lượng hóa học để thực hiện công. Trong mỗi nhịp hoạt động, tế bào cơ có thể sinh một lực <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/116/1791218813408-hinh-6.png\" alt=\"Hình 6\" class=\"eq\" style=\"width:68px;height:20.9px\" />N để dịch chuyển 8 nm. Công mà tế bào cơ sinh ra trong mỗi nhịp hoạt động bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực cùng hướng với dịch chuyển nên $A=Fs$; cần đổi $s$ về mét trước khi thay số.</p><p class=\"text-base leading-relaxed my-2\">$s=8\\ \\text{nm}=8\\cdot10^{-9}$ m, $F=1{,}5\\cdot10^{-12}$ N.</p><p class=\"text-base leading-relaxed my-2\">$A=1{,}5\\cdot10^{-12}\\cdot8\\cdot10^{-9}=1{,}2\\cdot10^{-20}$ J.</p><p class=\"text-base leading-relaxed my-2\">Sai vì: $1{,}2\\cdot10^{-11}$ J là không đổi nm sang m (dùng $s=8$); $1{,}2\\cdot10^{-14}$ J ứng với $s=8\\cdot10^{-3}$ m (nhầm nm với mm); $1{,}2\\cdot10^{-17}$ J ứng với $s=8\\cdot10^{-6}$ m (nhầm nm với $\\mu$m).</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>A</b>.</p>","difficultySource":"ai"},"ex":[{"exam":743,"idx":23,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực và trường hợp lực xiên góc","answer":0,"options":["1,2.10<sup>−20</sup> J.","1,2.10<sup>−14</sup> J.","1,2.10<sup>−17</sup> J.","1,2.10<sup>−11</sup> J."],"question":"Mỗi tế bào cơ trong cơ thể người có thể coi như một động cơ siêu nhỏ, khi con người hoạt động, tế bào cơ sử dụng năng lượng hóa học để thực hiện công. Trong mỗi nhịp hoạt động, tế bào cơ có thể sinh một lực <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/116/1791218813408-hinh-6.png\" alt=\"Hình 6\" class=\"eq\" style=\"width:68px;height:20.9px\" />N để dịch chuyển 8 nm. Công mà tế bào cơ sinh ra trong mỗi nhịp hoạt động bằng","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1506094,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Hai điện tích điểm q1 = - 3,2.10<sup>−7</sup> C và q2 = 2,4.10<sup>−7</sup> C đặt trong chân không tại hai điểm A và B cách nhau 12 cm.","difficulty":"trung-binh","statements":[{"text":"Đơn vị đo điện tích là Vôn (V).","answer":false},{"text":"Biểu thức tính độ lớn lực tương tác tĩnh điện giữa điện tích q1 và điện tích q2 là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218893870-hinh-19.png\" alt=\"Hình 19\" class=\"eq\" style=\"width:77px;height:40.8px\" />","answer":true},{"text":"Lực tương tác tĩnh điện giữa điện tích q1 và điện tích q2 là lực hút.","answer":true},{"text":"Giữ nguyên các điều kiện khác, khi tăng khoảng cách giữa hai điện tích trên lên 2 lần thì độ lớn lực tương tác tĩnh điện giữa chúng là 12 mN.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Sai. Đơn vị điện tích là culông (C); vôn (V) là đơn vị hiệu điện thế.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Định luật Coulomb: $F=k\\dfrac{|q_1q_2|}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $q_1\\lt0$ và $q_2\\gt0$ trái dấu nên hai điện tích hút nhau.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. Với $r=12\\ cm$: $F=9.10^9\\cdot\\dfrac{3,2.10^{-7}\\cdot2,4.10^{-7}}{0,12^2}=0,048\\ N=48\\ mN$. Khi $r$ tăng 2 lần thì $F$ giảm 4 lần: $F'=\\dfrac{48}{4}=12\\ mN$.</p>","difficultySource":"ai"},"ex":[{"exam":811,"idx":10,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Hai điện tích điểm q1 = - 3,2.10<sup>−7</sup> C và q2 = 2,4.10<sup>−7</sup> C đặt trong chân không tại hai điểm A và B cách nhau 12 cm.","difficulty":"trung-binh","statements":[{"text":"Đơn vị đo điện tích là Vôn (V).","answer":false},{"text":"Biểu thức tính độ lớn lực tương tác tĩnh điện giữa điện tích q1 và điện tích q2 là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218893870-hinh-19.png\" alt=\"Hình 19\" class=\"eq\" style=\"width:77px;height:40.8px\" />","answer":true},{"text":"Lực tương tác tĩnh điện giữa điện tích q1 và điện tích q2 là lực hút.","answer":true},{"text":"Giữ nguyên các điều kiện khác, khi tăng khoảng cách giữa hai điện tích trên lên 2 lần thì độ lớn lực tương tác tĩnh điện giữa chúng là 12 mN.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1506383,"nq":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"16,5","question":"Hai bản kim loại có kích thước lớn và bằng nhau, đặt song song với nhau, cách nhau một khoảng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218915454-hinh-3.png\" alt=\"Hình 3\" class=\"eq\" style=\"width:72px;height:13.4px\" /> như hình vẽ. Hiệu điện thế giữa hai bản phẳng là 48 V. Một electron (qe=-1,6.10<sup>−19</sup>C; me=9,1.10<sup>−31</sup> kg) bay vào chính giữa hai bản phẳng theo phương vuông góc với các đường sức điện với vận tốc 200 m/s. Biết  electron bay ra khỏi điện trường sát mép bản dương. Bỏ qua điện trường của Trái Đất, lực cản môi trường, trọng lực tác dụng lên electron. Tầm xa của electron theo phương Ox là bao nhiêu µm? Kết quả làm tròn đến hàng phần mười.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218915741-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:157.5px;height:auto\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong điện trường đều: $E=\\dfrac{U}{d}=\\dfrac{48}{0,24}=200\\ V/m$. Gia tốc của electron: $a=\\dfrac{|q_e|E}{m_e}=\\dfrac{1,6.10^{-19}\\cdot200}{9,1.10^{-31}}\\approx3,52.10^{13}\\ m/s^2$.</p><p class=\"text-base leading-relaxed my-2\">Electron bay vào chính giữa hai bản, theo phương Ox với $v_0=200\\ m/s$ (chuyển động đều), còn theo phương vuông góc chịu lực không đổi hướng về bản dương (chuyển động nhanh dần đều).</p><p class=\"text-base leading-relaxed my-2\">Ra sát mép bản dương nên độ dịch theo phương điện trường là $\\dfrac d2=0,12\\ m$: $\\dfrac d2=\\dfrac12at^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=\\sqrt{\\dfrac{d}{a}}\\approx8,26.10^{-8}\\ s$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow x=v_0t=200\\cdot8,26.10^{-8}\\approx1,65.10^{-5}\\ m\\approx16,5\\ \\mu m$.</p>","difficultySource":"ai"},"ex":[{"exam":826,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"16,5","question":"Hai bản kim loại có kích thước lớn và bằng nhau, đặt song song với nhau, cách nhau một khoảng <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218915454-hinh-3.png\" alt=\"Hình 3\" class=\"eq\" style=\"width:72px;height:13.4px\" /> như hình vẽ. Hiệu điện thế giữa hai bản phẳng là 48 V. Một electron (qe=-1,6.10<sup>−19</sup>C; me=9,1.10<sup>−31</sup> kg) bay vào chính giữa hai bản phẳng theo phương vuông góc với các đường sức điện với vận tốc 200 m/s. Biết  electron bay ra khỏi điện trường sát mép bản dương. Bỏ qua điện trường của Trái Đất, lực cản môi trường, trọng lực tác dụng lên electron. Tầm xa của electron theo phương Ox là bao nhiêu µm? Kết quả làm tròn đến hàng phần mười.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218915741-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:157.5px;height:auto\" />","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":1507760,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":1,"options":["không truyền được trong chân không.","mang năng lượng.","luôn lan truyền với tốc độ 3.10<sup>8</sup> m/s.","là sóng dọc"],"question":"Sóng điện từ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ mang năng lượng (sóng truyền năng lượng từ nguồn đi xa).</p><p class=\"text-base leading-relaxed my-2\">A sai: sóng điện từ truyền được trong chân không. D sai: sóng điện từ là sóng ngang.</p><p class=\"text-base leading-relaxed my-2\">C sai: tốc độ $3\\cdot10^8$ m/s chỉ đúng trong chân không; trong môi trường khác tốc độ nhỏ hơn nên chữ \"luôn\" làm phát biểu sai.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":889,"idx":11,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":1,"options":["không truyền được trong chân không.","mang năng lượng.","luôn lan truyền với tốc độ 3.10<sup>8</sup> m/s.","là sóng dọc"],"question":"Sóng điện từ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ mang năng lượng (sóng truyền năng lượng từ nguồn đi xa).</p><p class=\"text-base leading-relaxed my-2\">A sai: sóng điện từ truyền được trong chân không. D sai: sóng điện từ là sóng ngang.</p><p class=\"text-base leading-relaxed my-2\">C sai: tốc độ $3\\cdot10^8$ m/s chỉ đúng trong chân không; trong môi trường khác tốc độ nhỏ hơn nên chữ \"luôn\" làm phát biểu sai.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Chọn B.</p>","difficultySource":"ai"}}]},{"id":1510372,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một nhóm học sinh thực hiện thí nghiệm tìm hiểu về hiện tượng cảm ứng điện từ như sau: dùng một cuộn dây có hai đầu dây nối vào điện kế G , đặt một nam châm thẳng dọc theo trục của cuộn dây như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259684448-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi nam châm và cuộn dây đứng yên thì dòng điện cảm ứng xuất hiện trong cuộn dây luôn không đổi.","answer":false},{"text":"Khi di chuyển nam châm ra xa hoặc lại gần cuộn dây thì trong cuộn dây xuất hiện một suất  điện động cảm ứng.","answer":true},{"text":"Nam châm di chuyển với tốc độ càng lớn thì độ lớn dòng điện cảm ứng càng lớn.","answer":true},{"text":"Biết điện trở tổng cộng của cuộn dây và điện kế G là 3W. Cho nam châm dịch chuyển ra xa cuộn dây sao cho số chỉ của điện kế G không đổi và bằng 3mA. Khi này, tốc độ biến thiên của từ thông qua cuộn dây là 9.10<sup>−3</sup>Wb/s và dòng điện cảm ứng trong đoạn dây MN có chiều từ M đến N .","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Sai. Khi nam châm và cuộn dây đứng yên, từ thông qua cuộn dây không đổi nên không có dòng điện cảm ứng (dòng bằng $0$).</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Di chuyển nam châm lại gần hoặc ra xa làm từ thông qua cuộn dây biến thiên, nên xuất hiện suất điện động cảm ứng.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $|e_c|=\\left|\\dfrac{\\Delta\\Phi}{\\Delta t}\\right|$ tăng khi nam châm di chuyển nhanh hơn, nên $I=\\dfrac{|e_c|}{R}$ càng lớn.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $|e_c|=IR=3\\cdot 10^{-3}\\cdot 3=9\\cdot 10^{-3}\\ \\text{V}$, nên $\\left|\\dfrac{\\Delta\\Phi}{\\Delta t}\\right|=9\\cdot 10^{-3}\\ \\text{Wb/s}$.</p><p class=\"text-base leading-relaxed my-2\">Chiều dòng: nam châm ra xa làm từ thông (hướng từ phải sang trái trong ống) giảm; theo định luật Lenz, từ trường cảm ứng cùng chiều (hướng sang trái). Theo chiều quấn dây trên hình, dòng đi ra đầu bên phải của cuộn dây rồi qua $M$ đến $N$. Vậy dòng trong đoạn $MN$ có chiều từ $M$ đến $N$.</p>","difficultySource":"ai"},"ex":[{"exam":133,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một nhóm học sinh thực hiện thí nghiệm tìm hiểu về hiện tượng cảm ứng điện từ như sau: dùng một cuộn dây có hai đầu dây nối vào điện kế G , đặt một nam châm thẳng dọc theo trục của cuộn dây như hình vẽ. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259684448-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khi nam châm và cuộn dây đứng yên thì dòng điện cảm ứng xuất hiện trong cuộn dây luôn không đổi.","answer":false},{"text":"Khi di chuyển nam châm ra xa hoặc lại gần cuộn dây thì trong cuộn dây xuất hiện một suất  điện động cảm ứng.","answer":true},{"text":"Nam châm di chuyển với tốc độ càng lớn thì độ lớn dòng điện cảm ứng càng lớn.","answer":true},{"text":"Biết điện trở tổng cộng của cuộn dây và điện kế G là 3W. Cho nam châm dịch chuyển ra xa cuộn dây sao cho số chỉ của điện kế G không đổi và bằng 3mA. Khi này, tốc độ biến thiên của từ thông qua cuộn dây là 9.10<sup>−3</sup>Wb/s và dòng điện cảm ứng trong đoạn dây MN có chiều từ M đến N .","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Sai. Khi nam châm và cuộn dây đứng yên, từ thông qua cuộn dây không đổi nên không có dòng điện cảm ứng (dòng bằng $0$).</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Di chuyển nam châm lại gần hoặc ra xa làm từ thông qua cuộn dây biến thiên, nên xuất hiện suất điện động cảm ứng.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $|e_c|=\\left|\\dfrac{\\Delta\\Phi}{\\Delta t}\\right|$ tăng khi nam châm di chuyển nhanh hơn, nên $I=\\dfrac{|e_c|}{R}$ càng lớn.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $|e_c|=IR=3\\cdot 10^{-3}\\cdot 3=9\\cdot 10^{-3}\\ \\text{V}$, nên $\\left|\\dfrac{\\Delta\\Phi}{\\Delta t}\\right|=9\\cdot 10^{-3}\\ \\text{Wb/s}$.</p><p class=\"text-base leading-relaxed my-2\">Chiều dòng: nam châm ra xa làm từ thông (hướng từ phải sang trái trong ống) giảm; theo định luật Lenz, từ trường cảm ứng cùng chiều (hướng sang trái). Theo chiều quấn dây trên hình, dòng đi ra đầu bên phải của cuộn dây rồi qua $M$ đến $N$. Vậy dòng trong đoạn $MN$ có chiều từ $M$ đến $N$.</p>","difficultySource":"ai"}}]},{"id":1510689,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"6,56","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi phân hạch một hạt nhân là 200 MeV. Biết 1 eV = 1,60.10<sup>−19</sup>J; một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$  là 235 g/mol.<br>Năng lượng tỏa ra trong quá trình phân hạch hạt nhân của 800 g  ${}_{92}^{235}U$ trong lò phản ứng là  $x.10^{13}$  (J). Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt nhân U-235 trong 800 g: $N=\\dfrac{m}{A}N_A=\\dfrac{800}{235}\\cdot 6{,}02\\cdot10^{23}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N\\approx 2{,}049\\cdot10^{24}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng mỗi phân hạch: $200\\ \\text{MeV}=200\\cdot10^6\\cdot1{,}60\\cdot10^{-19}=3{,}2\\cdot10^{-11}$ J.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tổng cộng: $Q=N\\cdot 3{,}2\\cdot10^{-11}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q\\approx 2{,}049\\cdot10^{24}\\cdot3{,}2\\cdot10^{-11}\\approx 6{,}56\\cdot10^{13}$ J.</p><p class=\"text-base leading-relaxed my-2\">Vậy $x\\approx 6{,}56$.</p>","difficultySource":"ai"},"ex":[{"exam":261,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"6,56","question":"Trong phản ứng phân hạch hạt nhân  ${}_{92}^{235}U$ , năng lượng trung bình tỏa ra khi phân hạch một hạt nhân là 200 MeV. Biết 1 eV = 1,60.10<sup>−19</sup>J; một năm có 365 ngày. Khối lượng mol nguyên tử của  ${}_{92}^{235}U$  là 235 g/mol.<br>Năng lượng tỏa ra trong quá trình phân hạch hạt nhân của 800 g  ${}_{92}^{235}U$ trong lò phản ứng là  $x.10^{13}$  (J). Tìm giá trị của x (làm tròn kết quả đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Số hạt nhân U-235 trong 800 g: $N=\\dfrac{m}{A}N_A=\\dfrac{800}{235}\\cdot 6{,}02\\cdot10^{23}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N\\approx 2{,}049\\cdot10^{24}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng mỗi phân hạch: $200\\ \\text{MeV}=200\\cdot10^6\\cdot1{,}60\\cdot10^{-19}=3{,}2\\cdot10^{-11}$ J.</p><p class=\"text-base leading-relaxed my-2\">Năng lượng tổng cộng: $Q=N\\cdot 3{,}2\\cdot10^{-11}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q\\approx 2{,}049\\cdot10^{24}\\cdot3{,}2\\cdot10^{-11}\\approx 6{,}56\\cdot10^{13}$ J.</p><p class=\"text-base leading-relaxed my-2\">Vậy $x\\approx 6{,}56$.</p>","difficultySource":"ai"}}]},{"id":1513107,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":1,"options":["-144 V.","4 V.","-4 V.","144 V."],"question":"Khi một điện tích q = 6.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì lực điện sinh công 24.10<sup>−6</sup> J. Hiệu điện thế giữa M và N là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích q di chuyển từ M đến N: $A_{MN} = qU_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U_{MN} = \\dfrac{A_{MN}}{q}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U_{MN} = \\dfrac{24.10^{-6}}{6.10^{-6}} = 4\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Vậy hiệu điện thế giữa M và N là 4 V. Chọn B.</p>","difficultySource":"ai"},"ex":[{"exam":701,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":1,"options":["-144 V.","4 V.","-4 V.","144 V."],"question":"Khi một điện tích q = 6.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì lực điện sinh công 24.10<sup>−6</sup> J. Hiệu điện thế giữa M và N là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích q di chuyển từ M đến N: $A_{MN} = qU_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U_{MN} = \\dfrac{A_{MN}}{q}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U_{MN} = \\dfrac{24.10^{-6}}{6.10^{-6}} = 4\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Vậy hiệu điện thế giữa M và N là 4 V. Chọn B.</p>","difficultySource":"ai"}}]},{"id":1513109,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":0,"options":["11 nC","1,1.10<sup>−9</sup> C","44.10<sup>−9</sup> C","4,4 nC"],"question":"Một tụ điện có điện dung 50 pF được mắc vào hiệu điện thế 220V.  Điện tích mà tụ tích được là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện: $Q = CU$ (với $C$ là điện dung, $U$ là hiệu điện thế giữa hai bản tụ).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 50\\ \\text{pF} = 50\\cdot 10^{-12}\\ \\text{F}$, $U = 220\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">$Q = 50\\cdot 10^{-12}\\cdot 220$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 1{,}1\\cdot 10^{-8}\\ \\text{C} = 11\\ \\text{nC}$</p><p class=\"text-base leading-relaxed my-2\">Vậy chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":701,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":0,"options":["11 nC","1,1.10<sup>−9</sup> C","44.10<sup>−9</sup> C","4,4 nC"],"question":"Một tụ điện có điện dung 50 pF được mắc vào hiệu điện thế 220V.  Điện tích mà tụ tích được là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện: $Q = CU$ (với $C$ là điện dung, $U$ là hiệu điện thế giữa hai bản tụ).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 50\\ \\text{pF} = 50\\cdot 10^{-12}\\ \\text{F}$, $U = 220\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">$Q = 50\\cdot 10^{-12}\\cdot 220$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 1{,}1\\cdot 10^{-8}\\ \\text{C} = 11\\ \\text{nC}$</p><p class=\"text-base leading-relaxed my-2\">Vậy chọn đáp án A.</p>","difficultySource":"ai"}}]},{"id":1513124,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["2,5.10<sup>11</sup> hạt","2,5.10<sup>27</sup> hạt","5.10<sup>11</sup> hạt","5.10<sup>12</sup> hạt"],"question":"Biết điện tích nguyên tố có giá trị 1,6.10<sup>−19</sup> C; Trong một vật dẫn tích điện - 8.10<sup>−8</sup> C, số hạt electron nhiều hơn số hạt proton là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật tích điện âm nên số electron nhiều hơn số proton. Điện tích của vật bằng độ chênh lệch số hạt nhân với điện tích nguyên tố: $|q| = N\\cdot e$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{|q|}{e}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{8.10^{-8}}{1,6.10^{-19}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 5.10^{11}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Vậy số electron nhiều hơn số proton là $5.10^{11}$ hạt. Chọn C.</p>","difficultySource":"ai"},"ex":[{"exam":701,"idx":18,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật 2 Newton — bài toán động lực học","answer":2,"options":["2,5.10<sup>11</sup> hạt","2,5.10<sup>27</sup> hạt","5.10<sup>11</sup> hạt","5.10<sup>12</sup> hạt"],"question":"Biết điện tích nguyên tố có giá trị 1,6.10<sup>−19</sup> C; Trong một vật dẫn tích điện - 8.10<sup>−8</sup> C, số hạt electron nhiều hơn số hạt proton là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Vật tích điện âm nên số electron nhiều hơn số proton. Điện tích của vật bằng độ chênh lệch số hạt nhân với điện tích nguyên tố: $|q| = N\\cdot e$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{|q|}{e}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = \\dfrac{8.10^{-8}}{1,6.10^{-19}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 5.10^{11}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">Vậy số electron nhiều hơn số proton là $5.10^{11}$ hạt. Chọn C.</p>","difficultySource":"ai"}}]},{"id":1513405,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công suất","answer":0,"options":["7,2.10<sup>6</sup> (J).","5,4.10<sup>6</sup> (J)","3,6.10<sup>6</sup> (J).","1,8.10<sup>6</sup> (J)."],"question":"Đổi 2 kWh bằng bao nhiêu Jun (J)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\ \\text{kWh} = 1000\\ \\text{W} \\times 3600\\ \\text{s} = 3{,}6.10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2\\ \\text{kWh} = 2 \\times 3{,}6.10^6\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2\\ \\text{kWh} = 7{,}2.10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>A</b>.</p>","difficultySource":"ai"},"ex":[{"exam":739,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công suất","answer":0,"options":["7,2.10<sup>6</sup> (J).","5,4.10<sup>6</sup> (J)","3,6.10<sup>6</sup> (J).","1,8.10<sup>6</sup> (J)."],"question":"Đổi 2 kWh bằng bao nhiêu Jun (J)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $1\\ \\text{kWh} = 1000\\ \\text{W} \\times 3600\\ \\text{s} = 3{,}6.10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2\\ \\text{kWh} = 2 \\times 3{,}6.10^6\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 2\\ \\text{kWh} = 7{,}2.10^6\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>A</b>.</p>","difficultySource":"ai"}}]},{"id":1513830,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tụ điện và điện dung","answer":"0,00001","question":"Một tụ điện có điện dung C = 2.10<sup>−6</sup> F mắc vào hai cực của nguồn điện hiệu điện thế 5 V. Điện tích của tụ điện có giá trị là bao nhiêu Culông (C) ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện được xác định bởi công thức: $Q = C\\,U$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 2.10^{-6}\\cdot 5$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 10^{-5}\\ \\text{C}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện tích của tụ điện là $Q = 10^{-5}$ C (= 0,00001 C).</p>","difficultySource":"ai"},"ex":[{"exam":811,"idx":18,"el":{"form":"bai_tap","type":"short_answer","topic":"Tụ điện và điện dung","answer":"0,00001","question":"Một tụ điện có điện dung C = 2.10<sup>−6</sup> F mắc vào hai cực của nguồn điện hiệu điện thế 5 V. Điện tích của tụ điện có giá trị là bao nhiêu Culông (C) ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích của tụ điện được xác định bởi công thức: $Q = C\\,U$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 2.10^{-6}\\cdot 5$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow Q = 10^{-5}\\ \\text{C}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện tích của tụ điện là $Q = 10^{-5}$ C (= 0,00001 C).</p>","difficultySource":"ai"}}]},{"id":1514354,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":2,"options":["7,5.10<sup>8</sup> km.","3,75.10<sup>8</sup> km.","3,75.10<sup>8</sup> m.","7,5.10<sup>8</sup> m."],"question":"Sóng vô tuyến ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng, bằng cách phát một tín hiệu từ Trái Đất tới Mặt Trăng và thu tín hiệu trở lại. Các nhà khoa học đo khoảng thời gian từ khi phát đến khi nhận tín hiệu trở lại là 2,5 s. Biết tốc độ của sóng vô tuyến này là 3.10<sup>8</sup> m/s. Khoảng cách từ Trái Đất tới Mặt Trăng là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Tín hiệu đi từ Trái Đất đến Mặt Trăng rồi phản xạ trở lại nên quãng đường sóng đi được là $2d$, với tốc độ không đổi $c = 3.10^8$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$2d = c\\,t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d = \\dfrac{c\\,t}{2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d = \\dfrac{3.10^8 \\cdot 2{,}5}{2} = 3{,}75.10^8$ m.</p><p class=\"text-base leading-relaxed my-2\">Vậy khoảng cách Trái Đất – Mặt Trăng là $3{,}75.10^8$ m. Chọn C.</p>","difficultySource":"ai"},"ex":[{"exam":885,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":2,"options":["7,5.10<sup>8</sup> km.","3,75.10<sup>8</sup> km.","3,75.10<sup>8</sup> m.","7,5.10<sup>8</sup> m."],"question":"Sóng vô tuyến ngắn được sử dụng để đo khoảng cách từ Trái Đất đến Mặt Trăng, bằng cách phát một tín hiệu từ Trái Đất tới Mặt Trăng và thu tín hiệu trở lại. Các nhà khoa học đo khoảng thời gian từ khi phát đến khi nhận tín hiệu trở lại là 2,5 s. Biết tốc độ của sóng vô tuyến này là 3.10<sup>8</sup> m/s. Khoảng cách từ Trái Đất tới Mặt Trăng là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Tín hiệu đi từ Trái Đất đến Mặt Trăng rồi phản xạ trở lại nên quãng đường sóng đi được là $2d$, với tốc độ không đổi $c = 3.10^8$ m/s.</p><p class=\"text-base leading-relaxed my-2\">$2d = c\\,t$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d = \\dfrac{c\\,t}{2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow d = \\dfrac{3.10^8 \\cdot 2{,}5}{2} = 3{,}75.10^8$ m.</p><p class=\"text-base leading-relaxed my-2\">Vậy khoảng cách Trái Đất – Mặt Trăng là $3{,}75.10^8$ m. Chọn C.</p>","difficultySource":"ai"}}]},{"id":1538163,"nq":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Trong một mẫu đá được các nhà du hành mang về Trái Đất từ Mặt Trăng, các nhà khoa học phát hiện có 75% potassium  ${}_{19}^{40}K$  ban đầu đã biến thành argon ${}_{18}^{40}{Ar}$ . Cho biết, khi được hình thành, mẫu đá không chứa argon; toàn bộ argon được tạo ra có nguồn gốc từ potassium và không bị thất thoát vào môi trường; chu kì bán rã của  ${}_{19}^{40}K$  là 1,25.10<sup>9</sup> năm.","difficulty":"kho","statements":[{"text":"Phương trình phóng xạ của  ${}_{19}^{40}K$  là:  ${}_{19}^{40}K\\rightarrow_{18}^{40}Ar+\\beta^−$","answer":false},{"text":"${}_{19}^{40}K$ là chất phóng xạ β+.","answer":false},{"text":"Tuổi của mẫu đá đó là 2,5 tỉ năm.","answer":true},{"text":"Sau 7,5.10<sup>9</sup> năm kể từ hiện tại, lượng potassium  ${}_{19}^{40}K$  còn lại trong mẫu đá bằng 6,25% khi hình thành.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân K-40 (Z = 19) biến thành Ar-40 (Z = 18): số khối giữ nguyên, điện tích giảm 1 đơn vị, nên đây là phóng xạ $\\beta^+$: ${}_{19}^{40}K$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow{}_{18}^{40}Ar+{}_{+1}^{0}e$ (kèm neutrino).</p><p class=\"text-base leading-relaxed my-2\">a) Phương trình ghi $\\beta^-$ không bảo toàn điện tích ($19\\neq 18-1$). <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) K-40 là chất phóng xạ $\\beta^+$. <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">c) 75% K đã phân rã nên K còn lại 25%: $N=N_0 2^{-t/T}=0{,}25N_0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=2T=2{,}5.10^9$ năm. <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Sau thêm $7{,}5.10^9$ năm $=6T$ kể từ hiện tại, K còn lại so với lúc hình thành là:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{N}{N_0}=0{,}25\\cdot 2^{-6}\\approx 0{,}39\\%\\neq 6{,}25\\%$. <b>Sai</b>.</p>","difficultySource":"ai"},"ex":[{"exam":175,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Độ phóng xạ và bài toán xác định tuổi","question":"Trong một mẫu đá được các nhà du hành mang về Trái Đất từ Mặt Trăng, các nhà khoa học phát hiện có 75% potassium  ${}_{19}^{40}K$  ban đầu đã biến thành argon ${}_{18}^{40}{Ar}$ . Cho biết, khi được hình thành, mẫu đá không chứa argon; toàn bộ argon được tạo ra có nguồn gốc từ potassium và không bị thất thoát vào môi trường; chu kì bán rã của  ${}_{19}^{40}K$  là 1,25.10<sup>9</sup> năm.","difficulty":"kho","statements":[{"text":"Phương trình phóng xạ của  ${}_{19}^{40}K$  là:  ${}_{19}^{40}K\\rightarrow_{18}^{40}Ar+\\beta^−$","answer":false},{"text":"${}_{19}^{40}K$ là chất phóng xạ β+.","answer":false},{"text":"Tuổi của mẫu đá đó là 2,5 tỉ năm.","answer":true},{"text":"Sau 7,5.10<sup>9</sup> năm kể từ hiện tại, lượng potassium  ${}_{19}^{40}K$  còn lại trong mẫu đá bằng 6,25% khi hình thành.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt nhân K-40 (Z = 19) biến thành Ar-40 (Z = 18): số khối giữ nguyên, điện tích giảm 1 đơn vị, nên đây là phóng xạ $\\beta^+$: ${}_{19}^{40}K$</p><p class=\"text-base leading-relaxed my-2\">$\\rightarrow{}_{18}^{40}Ar+{}_{+1}^{0}e$ (kèm neutrino).</p><p class=\"text-base leading-relaxed my-2\">a) Phương trình ghi $\\beta^-$ không bảo toàn điện tích ($19\\neq 18-1$). <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\">b) K-40 là chất phóng xạ $\\beta^+$. <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">c) 75% K đã phân rã nên K còn lại 25%: $N=N_0 2^{-t/T}=0{,}25N_0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t=2T=2{,}5.10^9$ năm. <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">d) Sau thêm $7{,}5.10^9$ năm $=6T$ kể từ hiện tại, K còn lại so với lúc hình thành là:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{N}{N_0}=0{,}25\\cdot 2^{-6}\\approx 0{,}39\\%\\neq 6{,}25\\%$. <b>Sai</b>.</p>","difficultySource":"ai"}}]},{"id":1539297,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công suất của động cơ, máy kéo","answer":"5,0","question":"#2 Một máy bay đang bay với tốc độ 250 m/s và động cơ sinh ra lực kéo 2.10<sup>6</sup> N để duy trì tốc độ này của máy bay. Công suất của động cơ máy bay là x. 10<sup>8</sup> W. Giá trị x là bao nhiêu? (Kết quả làm tròn đến phần mười).<br>A.<br>B.<br>C. <@>5<br>D.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Máy bay bay đều nên lực kéo cân bằng với lực cản, và công suất của động cơ được tính theo công thức $P = F \\cdot v$, trong đó $F$ là lực kéo (N) và $v$ là tốc độ (m/s).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2.10^6\\ \\text{N}$, $v = 250\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 2.10^6 \\cdot 250 = 5.10^8\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">So sánh với $P = x.10^8\\ \\text{W}$ ta được $x = 5$.</p>","difficultySource":"ai"},"ex":[{"exam":636,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Công suất của động cơ, máy kéo","answer":"5,0","question":"#2 Một máy bay đang bay với tốc độ 250 m/s và động cơ sinh ra lực kéo 2.10<sup>6</sup> N để duy trì tốc độ này của máy bay. Công suất của động cơ máy bay là x. 10<sup>8</sup> W. Giá trị x là bao nhiêu? (Kết quả làm tròn đến phần mười).<br>A.<br>B.<br>C. <@>5<br>D.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Máy bay bay đều nên lực kéo cân bằng với lực cản, và công suất của động cơ được tính theo công thức $P = F \\cdot v$, trong đó $F$ là lực kéo (N) và $v$ là tốc độ (m/s).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2.10^6\\ \\text{N}$, $v = 250\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow P = 2.10^6 \\cdot 250 = 5.10^8\\ \\text{W}$.</p><p class=\"text-base leading-relaxed my-2\">So sánh với $P = x.10^8\\ \\text{W}$ ta được $x = 5$.</p>","difficultySource":"ai"}}]},{"id":1539317,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực và trường hợp lực xiên góc","answer":"9,6","question":"Trong điện trường đều của Trái Đất, chọn mặt đất là mốc thế năng điện. Điện trường đều đo được ở bề mặt Trái Đất là 120 V/m. Một hạt bụi mịn PM2.5 có điện tích q =1,6.10<sup>−19</sup> C đang lơ lửng ở độ cao  $h$  so với mặt đất. Sau đó, hạt bụi dịch chuyển thẳng đứng xuống dưới  $5 cm$  so với vị trí ban đầu. Tính công của lực điện trường đều của Trái Đất trong dịch chuyển trên của hạt bụi mịn (kết quả tính ra  đơn vị 10-19J).","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong điện trường đều, công của lực điện khi điện tích dịch chuyển dọc theo đường sức: $A=qEd$. Đề không nêu chiều, ta hiểu điện trường của Trái Đất hướng xuống và hạt bụi mang điện dương nên lực điện cùng chiều dịch chuyển (xuống).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q=1{,}6\\cdot10^{-19}\\ C$, $E=120\\ V/m$, $d=5\\ cm=0{,}05\\ m$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A=1{,}6\\cdot10^{-19}\\cdot120\\cdot0{,}05=9{,}6\\cdot10^{-19}\\ J$. Đáp số: 9,6.</p>","difficultySource":"ai"},"ex":[{"exam":638,"idx":18,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực và trường hợp lực xiên góc","answer":"9,6","question":"Trong điện trường đều của Trái Đất, chọn mặt đất là mốc thế năng điện. Điện trường đều đo được ở bề mặt Trái Đất là 120 V/m. Một hạt bụi mịn PM2.5 có điện tích q =1,6.10<sup>−19</sup> C đang lơ lửng ở độ cao  $h$  so với mặt đất. Sau đó, hạt bụi dịch chuyển thẳng đứng xuống dưới  $5 cm$  so với vị trí ban đầu. Tính công của lực điện trường đều của Trái Đất trong dịch chuyển trên của hạt bụi mịn (kết quả tính ra  đơn vị 10-19J).","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":1540063,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":0,"options":["1,82.10<sup>−24</sup> (kg.m/s).","8.10<sup>−24</sup> (kg.m/s).","1,6.10<sup>−24</sup> (kg.m/s)","4,91.10<sup>−24</sup> (kg.m/s)."],"question":"Một electron chuyển động với tốc độ 2.10<sup>6</sup>m/s. Biết khối lượng electron bằng 9,1.10<sup>−31</sup>kg. Tính động lượng của electron?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật có khối lượng $m$ chuyển động với vận tốc $\\vec{v}$ được xác định bởi $\\vec{p} = m\\vec{v}$. Vì electron chuyển động thẳng nên độ lớn: $p = m v$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 9{,}1\\cdot 10^{-31}\\ \\text{kg}$ và $v = 2\\cdot 10^{6}\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$p = 9{,}1\\cdot 10^{-31}\\cdot 2\\cdot 10^{6} = 18{,}2\\cdot 10^{-25} = 1{,}82\\cdot 10^{-24}\\ \\text{kg.m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của electron là $1{,}82\\cdot 10^{-24}\\ \\text{kg.m/s}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":744,"idx":20,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm động lượng, xung lượng của lực","answer":0,"options":["1,82.10<sup>−24</sup> (kg.m/s).","8.10<sup>−24</sup> (kg.m/s).","1,6.10<sup>−24</sup> (kg.m/s)","4,91.10<sup>−24</sup> (kg.m/s)."],"question":"Một electron chuyển động với tốc độ 2.10<sup>6</sup>m/s. Biết khối lượng electron bằng 9,1.10<sup>−31</sup>kg. Tính động lượng của electron?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động lượng của một vật có khối lượng $m$ chuyển động với vận tốc $\\vec{v}$ được xác định bởi $\\vec{p} = m\\vec{v}$. Vì electron chuyển động thẳng nên độ lớn: $p = m v$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 9{,}1\\cdot 10^{-31}\\ \\text{kg}$ và $v = 2\\cdot 10^{6}\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$p = 9{,}1\\cdot 10^{-31}\\cdot 2\\cdot 10^{6} = 18{,}2\\cdot 10^{-25} = 1{,}82\\cdot 10^{-24}\\ \\text{kg.m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: động lượng của electron là $1{,}82\\cdot 10^{-24}\\ \\text{kg.m/s}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1540382,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":3,"options":["2,7.10<sup>−10</sup> N.","2,7.10<sup>−6</sup> N.","8,1.10<sup>−10</sup> N.","8,1.10<sup>−6</sup> N."],"question":"Lực tương tác giữa hai điện tích q1 = q2 = -3.10<sup>−9</sup> C khi đặt cách nhau 10 cm trong không khí là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật Cu-lông: lực tương tác giữa hai điện tích điểm đặt trong chân không (không khí coi như chân không) có độ lớn</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 10\\ \\text{cm} = 0,1\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 9.10^9 \\cdot \\dfrac{(3.10^{-9})^2}{(0,1)^2} = 9.10^9 \\cdot \\dfrac{9.10^{-18}}{0,01}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot 9.10^{-16} = 81.10^{-7}\\ \\text{N} = 8,1.10^{-6}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Hai điện tích cùng dấu nên lực là lực đẩy. Đáp án đúng là D.</p>","difficultySource":"ai"},"ex":[{"exam":808,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":3,"options":["2,7.10<sup>−10</sup> N.","2,7.10<sup>−6</sup> N.","8,1.10<sup>−10</sup> N.","8,1.10<sup>−6</sup> N."],"question":"Lực tương tác giữa hai điện tích q1 = q2 = -3.10<sup>−9</sup> C khi đặt cách nhau 10 cm trong không khí là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật Cu-lông: lực tương tác giữa hai điện tích điểm đặt trong chân không (không khí coi như chân không) có độ lớn</p><p class=\"text-base leading-relaxed my-2\">$F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 10\\ \\text{cm} = 0,1\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 9.10^9 \\cdot \\dfrac{(3.10^{-9})^2}{(0,1)^2} = 9.10^9 \\cdot \\dfrac{9.10^{-18}}{0,01}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^9 \\cdot 9.10^{-16} = 81.10^{-7}\\ \\text{N} = 8,1.10^{-6}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Hai điện tích cùng dấu nên lực là lực đẩy. Đáp án đúng là D.</p>","difficultySource":"ai"}}]},{"id":1540404,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên lí chồng chất điện trường","answer":1,"options":["45000 V/m.","0 V/m.","18000 V/m","12500 V/m"],"question":"Một thí nghiệm về điện trường được thực hiện trong môi trường không khí lý tưởng. Hai điện tích điểm q1=3.10<sup>−9</sup> C, q2=3.10<sup>−9</sup> C được đặt cố định tại hai điểm A và B, cách nhau 10 cm. Một học sinh thực hiện đo cường độ điện trường tại điểm M, là trung điểm của đoạn AB. Biết rằng không có các nguồn điện khác gây nhiễu trong phạm vi đo. Hãy tính giá trị cường độ điện trường tại M.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai điện tích điểm $q_1$ và $q_2$ đặt tại A và B, cùng độ lớn và cùng dấu (dương). Cường độ điện trường do điện tích điểm gây ra: $E = k\\dfrac{|q|}{r^2}$, với $k = 9.10^9$ N.m²/C² và $r$ là khoảng cách từ điện tích đến điểm đang xét.</p><p class=\"text-base leading-relaxed my-2\">Vì M là trung điểm AB nên $MA = MB = \\dfrac{AB}{2} = \\dfrac{0{,}1}{2} = 0{,}05$ m.</p><p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do mỗi điện tích gây ra tại M:</p><p class=\"text-base leading-relaxed my-2\">$E_1 = E_2 = k\\dfrac{|q|}{MA^2} = 9.10^9 \\cdot \\dfrac{3.10^{-9}}{(0{,}05)^2} = 10800$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Hai vectơ $\\vec{E}_1$ và $\\vec{E}_2$ có cùng độ lớn, cùng phương (đường thẳng AB) nhưng ngược chiều nhau vì hai điện tích cùng dấu nằm hai phía của M: $\\vec{E}_1$ hướng từ A đến M, $\\vec{E}_2$ hướng từ B đến M, và chúng đều hướng ra xa điện tích tương ứng.</p><p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tổng hợp tại M theo nguyên lí chồng chất điện trường:</p><p class=\"text-base leading-relaxed my-2\">$\\vec{E}_M = \\vec{E}_1 + \\vec{E}_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E_M = |E_1 - E_2| = 10800 - 10800 = 0$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường tại M bằng 0 V/m, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nguyên lí chồng chất điện trường","answer":1,"options":["45000 V/m.","0 V/m.","18000 V/m","12500 V/m"],"question":"Một thí nghiệm về điện trường được thực hiện trong môi trường không khí lý tưởng. Hai điện tích điểm q1=3.10<sup>−9</sup> C, q2=3.10<sup>−9</sup> C được đặt cố định tại hai điểm A và B, cách nhau 10 cm. Một học sinh thực hiện đo cường độ điện trường tại điểm M, là trung điểm của đoạn AB. Biết rằng không có các nguồn điện khác gây nhiễu trong phạm vi đo. Hãy tính giá trị cường độ điện trường tại M.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai điện tích điểm $q_1$ và $q_2$ đặt tại A và B, cùng độ lớn và cùng dấu (dương). Cường độ điện trường do điện tích điểm gây ra: $E = k\\dfrac{|q|}{r^2}$, với $k = 9.10^9$ N.m²/C² và $r$ là khoảng cách từ điện tích đến điểm đang xét.</p><p class=\"text-base leading-relaxed my-2\">Vì M là trung điểm AB nên $MA = MB = \\dfrac{AB}{2} = \\dfrac{0{,}1}{2} = 0{,}05$ m.</p><p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do mỗi điện tích gây ra tại M:</p><p class=\"text-base leading-relaxed my-2\">$E_1 = E_2 = k\\dfrac{|q|}{MA^2} = 9.10^9 \\cdot \\dfrac{3.10^{-9}}{(0{,}05)^2} = 10800$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Hai vectơ $\\vec{E}_1$ và $\\vec{E}_2$ có cùng độ lớn, cùng phương (đường thẳng AB) nhưng ngược chiều nhau vì hai điện tích cùng dấu nằm hai phía của M: $\\vec{E}_1$ hướng từ A đến M, $\\vec{E}_2$ hướng từ B đến M, và chúng đều hướng ra xa điện tích tương ứng.</p><p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tổng hợp tại M theo nguyên lí chồng chất điện trường:</p><p class=\"text-base leading-relaxed my-2\">$\\vec{E}_M = \\vec{E}_1 + \\vec{E}_2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E_M = |E_1 - E_2| = 10800 - 10800 = 0$ V/m.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường tại M bằng 0 V/m, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":1540405,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["-1,6.10<sup>−19</sup> J","-3,2.10<sup>−18</sup> J","1,6.10<sup>−19</sup> J","3,2.10<sup>−18</sup> J"],"question":"Trong một máy gia tốc hạt mini sử dụng trong nghiên cứu vật lý, một electron được tăng tốc từ trạng thái nghỉ nhờ một điện trường đều có cường độ 1000 V/m. Electron di chuyển theo phương của đường sức điện và đi được quãng đường 2 cm. Tính công của lực điện tác dụng lên electron trong quá trình di chuyển.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Electron tăng tốc từ trạng thái nghỉ nên lực điện cùng chiều dịch chuyển; công của lực điện là dương: $A=|q|Ed$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A=1{,}6\\cdot10^{-19}\\cdot1000\\cdot0{,}02=3{,}2\\cdot10^{-18}\\ J$. Chọn D.</p><p class=\"text-base leading-relaxed my-2\">Hai phương án âm (A, B) sai dấu; C sai độ lớn.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["-1,6.10<sup>−19</sup> J","-3,2.10<sup>−18</sup> J","1,6.10<sup>−19</sup> J","3,2.10<sup>−18</sup> J"],"question":"Trong một máy gia tốc hạt mini sử dụng trong nghiên cứu vật lý, một electron được tăng tốc từ trạng thái nghỉ nhờ một điện trường đều có cường độ 1000 V/m. Electron di chuyển theo phương của đường sức điện và đi được quãng đường 2 cm. Tính công của lực điện tác dụng lên electron trong quá trình di chuyển.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1540408,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":1,"options":["534.105 V/m","5625 V/m","5625 V/m2","3.10<sup>4</sup> V/m"],"question":"Một quả cầu nhỏ mang điện tích 10-9 C đặt trong không khí. Một con muỗi bay ngang qua một điểm cách tâm quả cầu 4 cm. Hỏi tại điểm này, cường độ điện trường do quả cầu gây ra là bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm gây ra: $E=k\\dfrac{|q|}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E=9\\cdot10^9\\cdot\\dfrac{10^{-9}}{(0{,}04)^2}=5625\\ V/m$. Chọn B.</p><p class=\"text-base leading-relaxed my-2\">Phương án C sai đơn vị (V/m$^2$); A và D sai độ lớn.</p>","difficultySource":"ai"},"ex":[{"exam":815,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":1,"options":["534.105 V/m","5625 V/m","5625 V/m2","3.10<sup>4</sup> V/m"],"question":"Một quả cầu nhỏ mang điện tích 10-9 C đặt trong không khí. Một con muỗi bay ngang qua một điểm cách tâm quả cầu 4 cm. Hỏi tại điểm này, cường độ điện trường do quả cầu gây ra là bao nhiêu?","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1540476,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"1000","question":"Xét một điện trường đều giữa hai bản kim loại phẳng đặt song song, gần nhau,cách điện, tích điện trái dấu, mốc điện thế tại bản âm. Điểm M trong điện trường cách bản âm 4cm. Một điện tích<br>q = 2.10<sup>−4</sup>C chuyển động từ M về bản âm thì công của lực điện là A = 0,2J. Tính điện thế của điện trường tại M ra đơn vị Vôn.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Mốc điện thế được chọn tại bản âm, nên điện thế của bản âm là $V_N = 0$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến bản âm N: $A_{MN} = q\\,(V_M - V_N)$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_M = \\dfrac{A_{MN}}{q} + V_N = \\dfrac{A_{MN}}{q}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{0{,}2}{2\\cdot 10^{-4}} = 1000\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại M là $V_M = 1000\\ \\text{V}$. Khoảng cách 4 cm không cần dùng trong bài này.</p>","difficultySource":"ai"},"ex":[{"exam":819,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"1000","question":"Xét một điện trường đều giữa hai bản kim loại phẳng đặt song song, gần nhau,cách điện, tích điện trái dấu, mốc điện thế tại bản âm. Điểm M trong điện trường cách bản âm 4cm. Một điện tích<br>q = 2.10<sup>−4</sup>C chuyển động từ M về bản âm thì công của lực điện là A = 0,2J. Tính điện thế của điện trường tại M ra đơn vị Vôn.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Mốc điện thế được chọn tại bản âm, nên điện thế của bản âm là $V_N = 0$.</p><p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích di chuyển từ M đến bản âm N: $A_{MN} = q\\,(V_M - V_N)$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_M = \\dfrac{A_{MN}}{q} + V_N = \\dfrac{A_{MN}}{q}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{0{,}2}{2\\cdot 10^{-4}} = 1000\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện thế tại M là $V_M = 1000\\ \\text{V}$. Khoảng cách 4 cm không cần dùng trong bài này.</p>","difficultySource":"ai"}}]},{"id":1540493,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"0,5","question":"Ta cần thực hiện một công 8.10<sup>−5</sup>J để dịch chuyển điện tích 1,6.10<sup>−4</sup> C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Điện thế tại M là bao nhiêu V?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc điện thế tại vô cực, điện thế tại M được xác định bằng công của lực điện khi đưa một đơn vị điện tích dương từ M ra vô cực, hoặc bằng công của lực ngoài khi đưa điện tích từ vô cực đến M (lực ngoài cân bằng với lực điện, dịch chuyển không gia tốc).</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: điện thế tại M = công của lực ngoài đưa điện tích từ vô cực đến M chia cho điện tích: $V_M = \\dfrac{A_{\\infty M}}{q}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{8.10^{-5}}{1{,}6.10^{-4}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_M = 0{,}5\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Vậy điện thế tại M là $0{,}5\\ \\text{V}$.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"0,5","question":"Ta cần thực hiện một công 8.10<sup>−5</sup>J để dịch chuyển điện tích 1,6.10<sup>−4</sup> C từ vô cực đến điểm M. Chọn gốc điện thế tại vô cực. Điện thế tại M là bao nhiêu V?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn gốc điện thế tại vô cực, điện thế tại M được xác định bằng công của lực điện khi đưa một đơn vị điện tích dương từ M ra vô cực, hoặc bằng công của lực ngoài khi đưa điện tích từ vô cực đến M (lực ngoài cân bằng với lực điện, dịch chuyển không gia tốc).</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: điện thế tại M = công của lực ngoài đưa điện tích từ vô cực đến M chia cho điện tích: $V_M = \\dfrac{A_{\\infty M}}{q}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $V_M = \\dfrac{8.10^{-5}}{1{,}6.10^{-4}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow V_M = 0{,}5\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Vậy điện thế tại M là $0{,}5\\ \\text{V}$.</p>","difficultySource":"ai"}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
